INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94433, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蛇是没有脚、身体又细又长的动物，在地上爬。", "primary_collocate": null, "pronunciation": "shé", "ipa": "ʂɤ˧˥", "syllable_count": 1, "sentences": [{"text": "蛇没有脚，只能在地上爬。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蛇又细又长，颜色是绿的。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在书上看到了一条蛇。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见蛇，吓得叫了起来。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇从树下慢慢爬过去了。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画了一条长长的蛇。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥说他昨天在河边见过蛇。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇的身体很长，像一根绳子。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶最怕家里出现蛇。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇不会走路，它是用身体往前爬的。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条蛇", "label": "量词"}, {"form": "毒蛇", "label": "复合"}, {"form": "蟒蛇", "label": "复合"}], "register": "中性", "sense_fingerprint": "蛇：没有脚、又细又长、在地上爬的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛇", "is_correct": true, "explanation": "shé（第二声）指没有脚、身体细长、在地上爬的动物，是本题的正确答案。"}, {"text": "社", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是社会、团体。"}, {"text": "射", "is_correct": false, "explanation": "shè（第四声）与 shé 声调不同，意思是发射、射箭。"}, {"text": "舍", "is_correct": false, "explanation": "shě（第三声）与 shé（第二声）声调不同，意思是舍弃、舍不得。"}, {"text": "哲", "is_correct": false, "explanation": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是哲学、智慧。"}], "explanations": {"蛇": "shé（第二声）指没有脚、身体细长、在地上爬的动物，是本题的正确答案。", "社": "shè（第四声）与 shé（第二声）声调不同，意思是社会、团体。", "射": "shè（第四声）与 shé 声调不同，意思是发射、射箭。", "舍": "shě（第三声）与 shé（第二声）声调不同，意思是舍弃、舍不得。", "哲": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是哲学、智慧。"}, "sentence_index": null, "correct_answer": "蛇"}, "level_3": {"options": [{"text": "蛇", "is_correct": true, "explanation": "正确：只有蛇没有脚，又只能靠身体在地上爬。"}, {"text": "鸟", "is_correct": false, "explanation": "语义：鸟有脚，而且会飞，不符合“没有脚”的描述。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“爬”要求有生命的动物作主语，桌子不能爬。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫有四条腿，会走路，不符合“没有脚”的描述。"}], "explanations": {"蛇": "正确：只有蛇没有脚，又只能靠身体在地上爬。", "鸟": "语义：鸟有脚，而且会飞，不符合“没有脚”的描述。", "桌子": "搭配：“爬”要求有生命的动物作主语，桌子不能爬。", "猫": "语义：猫有四条腿，会走路，不符合“没有脚”的描述。"}, "sentence_index": 0, "correct_answer": "蛇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶的院子里有一根蛇。", "explanation": "这里应该用〈条〉。“根”用于绳子、棍子这类细长而硬的东西，蛇要用“条”。"}, {"text": "我在河边看见一块蛇。", "explanation": "这里应该用〈条〉。“块”用于块状的东西，不能用来数蛇。"}, {"text": "路上有一座蛇挡住了去路。", "explanation": "这里应该用〈条〉。“座”用于山、房屋这类大型固定物，不能用来数蛇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94433, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛇", "is_correct": true, "explanation": "shé（第二声）指没有脚、身体细长、在地上爬的动物，是本题的正确答案。"}, {"text": "设", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是设立、设计。"}, {"text": "奢", "is_correct": false, "explanation": "shē（第一声）与 shé 声调不同，意思是奢侈、浪费。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是折断、折叠。"}, {"text": "摄", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是拍摄、摄影。"}], "explanations": {"蛇": "shé（第二声）指没有脚、身体细长、在地上爬的动物，是本题的正确答案。", "设": "shè（第四声）与 shé（第二声）声调不同，意思是设立、设计。", "奢": "shē（第一声）与 shé 声调不同，意思是奢侈、浪费。", "折": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是折断、折叠。", "摄": "shè（第四声）与 shé（第二声）声调不同，意思是拍摄、摄影。"}, "sentence_index": null, "correct_answer": "蛇"}, "level_3": {"options": [{"text": "蛇", "is_correct": true, "explanation": "正确：河边的蛇是可以看见的，“见过”搭配得当。"}, {"text": "方程", "is_correct": false, "explanation": "语义：方程是数学算式，不会在河边被见到。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“见过”通常接可见的事物，声音不能说见过。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法是语言规则，不是能在河边见到的东西。"}], "explanations": {"蛇": "正确：河边的蛇是可以看见的，“见过”搭配得当。", "方程": "语义：方程是数学算式，不会在河边被见到。", "声音": "搭配：“见过”通常接可见的事物，声音不能说见过。", "语法": "语义：语法是语言规则，不是能在河边见到的东西。"}, "sentence_index": 6, "correct_answer": "蛇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那条蛇有四条腿，在草地上快步走。", "explanation": "这里说蛇有四条腿、快步走，与“没有脚、在地上爬”的意义相反。"}, {"text": "蛇会用两只脚站起来，走进屋里。", "explanation": "这里说蛇用两只脚站立行走，与“没有脚”的意义相反。"}, {"text": "这条蛇的脚很长，它常常跑得很快。", "explanation": "这里说蛇的脚很长、跑得很快，与“没有脚、在地上爬”的意义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EX