INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家院子里发现了一个蛇。", "corrected_sentence": "我家院子里发现了一条蛇。", "error_description": "“蛇”前应说量词“条”，说“一个蛇”是学习者常见的错误。“个”是通用量词，不能用来数蛇。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
