INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种身体细长、无四肢的爬行动物，有的有毒。", "primary_collocate": null, "pronunciation": "shé", "ipa": "ʂɤ˧˥", "syllable_count": 1, "sentences": [{"text": "草丛里有一条蛇。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蛇有毒，别靠近它。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条蛇正在慢慢爬过马路。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天蛇躲在洞里睡觉。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的蛇有毒，有的蛇没有毒。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条蛇咬了他的腿。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最怕蛇，一看见就跑。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇没有腿，却爬得很快。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上看见一条很大的蛇。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的蛇正躺在石头上晒太阳。", "target_word": "蛇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条蛇", "label": "量词"}, {"form": "毒蛇", "label": "复合"}, {"form": "蟒蛇", "label": "复合"}], "register": "中性", "sense_fingerprint": "蛇：身体细长、无四肢的爬行动物，有的有毒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛇", "is_correct": true, "explanation": "shé（第二声）指身体细长、无四肢的爬行动物，有的有毒，是本题的正确答案。"}, {"text": "社", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是社会、团体。"}, {"text": "射", "is_correct": false, "explanation": "shè（第四声）与 shé 声调不同，意思是发射、射箭。"}, {"text": "舍", "is_correct": false, "explanation": "shě（第三声）与 shé（第二声）声调不同，意思是舍弃、舍不得。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是折断、折叠。"}, {"text": "摄", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是拍摄、摄影。"}], "explanations": {"蛇": "shé（第二声）指身体细长、无四肢的爬行动物，有的有毒，是本题的正确答案。", "社": "shè（第四声）与 shé（第二声）声调不同，意思是社会、团体。", "射": "shè（第四声）与 shé 声调不同，意思是发射、射箭。", "舍": "shě（第三声）与 shé（第二声）声调不同，意思是舍弃、舍不得。", "折": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是折断、折叠。", "摄": "shè（第四声）与 shé（第二声）声调不同，意思是拍摄、摄影。"}, "sentence_index": null, "correct_answer": "蛇"}, "level_3": {"options": [{"text": "蛇", "is_correct": true, "explanation": "正确：“一条”搭配细长的蛇，符合“草丛里”的场景。"}, {"text": "老虎", "is_correct": false, "explanation": "搭配：老虎用“只”计量，不能说“一条老虎”。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树用“棵”计量，“一条树”不成立。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会在草丛里，也不能用“条”来数。"}], "explanations": {"蛇": "正确：“一条”搭配细长的蛇，符合“草丛里”的场景。", "老虎": "搭配：老虎用“只”计量，不能说“一条老虎”。", "树": "搭配：树用“棵”计量，“一条树”不成立。", "太阳": "语义：太阳不会在草丛里，也不能用“条”来数。"}, "sentence_index": 0, "correct_answer": "蛇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在草丛里看见一根蛇。", "explanation": "这里应该用〈条〉。“根”用于绳子、棍子这类细长而硬的东西，蛇要用“条”。"}, {"text": "花园里来了一棵蛇。", "explanation": "这里应该用〈条〉。“棵”用于树木和植物，不能用来数蛇。"}, {"text": "我在河边看见一朵蛇。", "explanation": "这里应该用〈条〉。“朵”用于花、云等，不能用来数蛇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94434, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蛇", "is_correct": true, "explanation": "shé（第二声）指身体细长、无四肢的爬行动物，是本题的正确答案。"}, {"text": "设", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是设立、设计。"}, {"text": "奢", "is_correct": false, "explanation": "shē（第一声）与 shé 声调不同，意思是奢侈、浪费。"}, {"text": "哲", "is_correct": false, "explanation": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是哲学、智慧。"}, {"text": "赦", "is_correct": false, "explanation": "shè（第四声）与 shé（第二声）声调不同，意思是赦免、宽恕。"}], "explanations": {"蛇": "shé（第二声）指身体细长、无四肢的爬行动物，是本题的正确答案。", "设": "shè（第四声）与 shé（第二声）声调不同，意思是设立、设计。", "奢": "shē（第一声）与 shé 声调不同，意思是奢侈、浪费。", "哲": "zhé（第二声）与 shé 声母不同（zh 与 sh），意思是哲学、智慧。", "赦": "shè（第四声）与 shé（第二声）声调不同，意思是赦免、宽恕。"}, "sentence_index": null, "correct_answer": "蛇"}, "level_3": {"options": [{"text": "蛇", "is_correct": true, "explanation": "正确：人怕的是蛇，看见了就跑。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是让人害怕、一看见就跑的东西。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气看不见，不能说“一看见”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不会让人吓得一看见就跑。"}], "explanations": {"蛇": "正确：人怕的是蛇，看见了就跑。", "饭": "语义：饭不是让人害怕、一看见就跑的东西。", "空气": "搭配：空气看不见，不能说“一看见”。", "水果": "语义：水果不会让人吓得一看见就跑。"}, "sentence_index": 6, "correct_answer": "蛇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那条蛇长着四条腿，常在院子里跑。", "explanation": "这里说蛇长着四条腿，与“无四肢”的意义相反。"}, {"text": "这条蛇是哺乳动物，会给小蛇喂奶。", "explanation": "这里说蛇是哺乳动物，与“爬行动物”的意义相反。"}, {"text": "这条蛇是一种鸟，喜欢在树上做窝。", "explanation": "这里说蛇是鸟，与“爬行动物”的意义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口有一个蛇。", "corrected_sentence": "我家门口有一条蛇。", "error_description": "“蛇”前应说量词“条”，不能用通用量词“个”。“一个蛇”是学习者常见的错误，应说“一条蛇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条蛇爬了很快。", "corrected_sentence": "那条蛇爬得很快。", "error_description": "补语标记应为“得”，误用“了”：“了”不能引出补语，“爬了很快”不成立，应说“爬得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
