INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "给予的辅助性钱物。", "primary_collocate": null, "pronunciation": "bǔ zhù", "ipa": "pu˨˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "学校每个月给他一百元补助。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民可以从政府得到种地补助。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔补助会在月底发给大家。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他申请了交通补助。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年给老员工住房补助。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家对大学生有生活补助。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份补助只能用来买书。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了政府的补助，他们家的日子好多了。", "target_word": "补助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下个月补助就会到账。", "target_word": "补助", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工资不高，但是公司有餐费补助。", "target_word": "补助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "补助金", "label": "复合"}, {"form": "生活补助", "label": "复合"}, {"form": "補助", "label": "繁体"}], "register": "中性", "sense_fingerprint": "政府、学校或单位给予的辅助性钱物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补助", "is_correct": true, "explanation": "补助是学校或单位给予的辅助钱物，与“给他一百元”相符，正确。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：罚款是因违规而被收取的钱，学校不会“给”人罚款，句意相反。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的钱，方向与“给他”相反。"}, {"text": "欠款", "is_correct": false, "explanation": "搭配：欠款是欠别人的钱，不能用“给他一百元”来表述。"}], "explanations": {"补助": "补助是学校或单位给予的辅助钱物，与“给他一百元”相符，正确。", "罚款": "语义：罚款是因违规而被收取的钱，学校不会“给”人罚款，句意相反。", "学费": "语义：学费是学生交给学校的钱，方向与“给他”相反。", "欠款": "搭配：欠款是欠别人的钱，不能用“给他一百元”来表述。"}, "sentence_index": 0, "correct_answer": "补助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向银行借了一笔补助，说好以后还。", "explanation": "这里应该用〈借款〉。补助是给予的钱物，不用偿还；要还的钱款应说借款。"}, {"text": "他每天早上都要读一份补助。", "explanation": "这里应该用〈报纸〉。补助是给予的钱物，不能用来读；每天早上要读的应说报纸。"}, {"text": "他这次数学考试考了一百分的补助。", "explanation": "这里应该用〈分数〉。补助是钱物，考试成绩要说分数，不能说成补助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补助", "is_correct": true, "explanation": "补助是别人给的、用于帮助生活的钱，与“只能用来买书”的限定相符，正确。"}, {"text": "押金", "is_correct": false, "explanation": "语义：押金会退还，不是给予的钱，“只能用来买书”的说法说不通。"}, {"text": "欠款", "is_correct": false, "explanation": "语义：欠款是应还给别人的钱，不是别人给的钱，“只能用来买书”的说法不通。"}, {"text": "罚金", "is_correct": false, "explanation": "语义：罚金是违规受罚所交的钱，与“只能用来买书”的用途说明矛盾。"}], "explanations": {"补助": "补助是别人给的、用于帮助生活的钱，与“只能用来买书”的限定相符，正确。", "押金": "语义：押金会退还，不是给予的钱，“只能用来买书”的说法说不通。", "欠款": "语义：欠款是应还给别人的钱，不是别人给的钱，“只能用来买书”的说法不通。", "罚金": "语义：罚金是违规受罚所交的钱，与“只能用来买书”的用途说明矛盾。"}, "sentence_index": 6, "correct_answer": "补助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天放学后去补助功课。", "explanation": "这里应该用〈补习〉。补助指给予的钱物，不能表示辅导功课。"}, {"text": "银行每个月给他的存款付了补助。", "explanation": "这里应该用〈利息〉。补助是政府或单位的辅助给予，不是存款产生的收益。"}, {"text": "他每个月都要交补助。", "explanation": "这里应该用〈房租〉。补助是给予别人的钱，不能说自己要交出去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民每个月都能领到一只补助。", "corrected_sentence": "农民每个月都能领到一笔补助。", "error_description": "错误形式：一只补助；正确形式：一笔补助。补助是钱款，量词应用“笔”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校给每个学生发了一本补助。", "corrected_sentence": "学校给每个学生发了一笔补助。", "error_description": "错误在于量词：补助是钱款，量词应用“笔”，不能用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
