INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94437, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "译是把一种话改成另一种话说出来。", "primary_collocate": null, "pronunciation": "yì", "ipa": "i˥˩", "syllable_count": 1, "sentences": [{"text": "请你把这句话译成中文。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上把老板的话译给客人听。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句英语你能译成汉语吗？", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我把这段话译一下。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用法语说，我来译给大家听。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听不懂日语，请你帮我译一下。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一边听，一边译成中文告诉我们。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没学过英语，没办法把这些话译出来。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得太快了，我来不及译。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人听不懂方言，王先生就当场译成普通话。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "译了", "label": "体标：了"}, {"form": "译过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "把一种语言的话改成另一种语言说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "译", "is_correct": true, "explanation": "译：把一种语言的话改成另一种语言说出来，正是本词的意思。"}, {"text": "一", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是数字「一」。"}, {"text": "以", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用、凭借。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是移动。"}, {"text": "医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是医生、治病。"}], "explanations": {"译": "译：把一种语言的话改成另一种语言说出来，正是本词的意思。", "一": "yī（第一声）与 yì（第四声）声调不同，意思是数字「一」。", "以": "yǐ（第三声）与 yì（第四声）声调不同，意思是用、凭借。", "移": "yí（第二声）与 yì（第四声）声调不同，意思是移动。", "医": "yī（第一声）与 yì（第四声）声调不同，意思是医生、治病。"}, "sentence_index": null, "correct_answer": "译"}, "level_3": {"options": [{"text": "译", "is_correct": true, "explanation": "译：把一种语言的话改成另一种语言，符合「把这句话……成中文」。"}, {"text": "删", "is_correct": false, "explanation": "语义：「删」是去掉，不能表示把话变成另一种语言。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：「砍成」用于具体物件，不能用于语言。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：「烧成」指烧制物件，不能用于话语。"}], "explanations": {"译": "译：把一种语言的话改成另一种语言，符合「把这句话……成中文」。", "删": "语义：「删」是去掉，不能表示把话变成另一种语言。", "砍": "搭配：「砍成」用于具体物件，不能用于语言。", "烧": "搭配：「烧成」指烧制物件，不能用于话语。"}, "sentence_index": 0, "correct_answer": "译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都懂中文，他却把老板的话译给大家听。", "explanation": "这里应该用〈转述〉。大家都懂中文，不需要语言转换，只能转述。"}, {"text": "老师在课上译这道数学题。", "explanation": "这里应该用〈讲解〉。译是把一种语言的话改成另一种语言，讲解数学题不是语言转换。"}, {"text": "导游在博物馆里译那些文物。", "explanation": "这里应该用〈解说〉。译只用于语言文字，文物是实物，要解说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94437, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "译", "is_correct": true, "explanation": "译：把一种语言的话改成另一种语言说出来，正是本词的意思。"}, {"text": "衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是衣服。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经。"}, {"text": "疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是怀疑。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是椅子。"}], "explanations": {"译": "译：把一种语言的话改成另一种语言说出来，正是本词的意思。", "衣": "yī（第一声）与 yì（第四声）声调不同，意思是衣服。", "已": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经。", "疑": "yí（第二声）与 yì（第四声）声调不同，意思是怀疑。", "椅": "yǐ（第三声）与 yì（第四声）声调不同，意思是椅子。"}, "sentence_index": null, "correct_answer": "译"}, "level_3": {"options": [{"text": "译", "is_correct": true, "explanation": "译：一边听一边把话转成另一种语言说出来，符合句意。"}, {"text": "猜", "is_correct": false, "explanation": "语义：「猜」是推测，不能表示把话转换成另一种语言。"}, {"text": "挤", "is_correct": false, "explanation": "搭配：「挤成」多用于物体被压，不能用于话语。"}, {"text": "吵", "is_correct": false, "explanation": "配价：「吵」是不及物动词，后面不能接「中文」作结果。"}], "explanations": {"译": "译：一边听一边把话转成另一种语言说出来，符合句意。", "猜": "语义：「猜」是推测，不能表示把话转换成另一种语言。", "挤": "搭配：「挤成」多用于物体被压，不能用于话语。", "吵": "配价：「吵」是不及物动词，后面不能接「中文」作结果。"}, "sentence_index": 6, "correct_answer": "译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在厨房里译了一锅汤。", "explanation": "这里应该用〈煮〉。译是语言转换，汤要煮，不能说译。"}, {"text": "师傅在译那台老式收音机。", "explanation": "这里应该用〈修理〉。译只用于语言文字，收音机是机器，要修理。"}, {"text": "他在乡下译了整个童年。", "explanation": "这里应该用〈度过〉。译只用于语言文字，童年是时间，要说度过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想把老板这句话译成外国客人听。", "corrected_sentence": "他想把老板这句话译给外国客人听。", "error_description": "「译」后接听话的人时要用「给」，应写作「译给外国客人听」；「译成」的「成」只接译文的语言或形式，不能接人，「译成外国客人听」不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把德国客人的话译给了中文。", "corrected_sentence": "他把德国客人的话译成了中文。", "error_description": "「译」后接语言时要用「成」，应说「译成了中文」；「译给」的「给」表示对象（译给某人听），不能与语言名词搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
