INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "翻译，把一种语言文字转换为另一种。", "primary_collocate": null, "pronunciation": "yì", "ipa": "i˥˩", "syllable_count": 1, "sentences": [{"text": "这本小说已经译成十几种语言了。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这首中国诗译成了英文。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章太难，我一个人译不完。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她正在译一本法语的儿童书。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这封信译成日文，明天交给我。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词很难译，因为汉语里没有对应的说法。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他译过很多本德国小说。", "target_word": "译", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗译成别的语言，味道就变了。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天晚上译两页书，已经译了半年。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书译得很好，读起来像中文原著。", "target_word": "译", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "译了", "label": "体标：了"}, {"form": "译过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "把书、文章等文字材料翻成另一种语言文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，正是本词的意思。"}, {"text": "衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是衣服。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经。"}, {"text": "疑", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是怀疑。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是椅子。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，正是本词的意思。", "衣": "yī（第一声）与 yì（第四声）声调不同，意思是衣服。", "已": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经。", "疑": "yí（第二声）与 yì（第四声）声调不同，意思是怀疑。", "椅": "yǐ（第三声）与 yì（第四声）声调不同，意思是椅子。"}, "sentence_index": null, "correct_answer": "译"}, "level_3": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，符合「已经……成十几种语言」。"}, {"text": "删", "is_correct": false, "explanation": "语义：「删」是去掉，不能表示把文字变成另一种语言。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切成」用于具体物体，小说不能切成语言。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮成」用于烹饪，不能用于语言。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，符合「已经……成十几种语言」。", "删": "语义：「删」是去掉，不能表示把文字变成另一种语言。", "切": "搭配：「切成」用于具体物体，小说不能切成语言。", "煮": "搭配：「煮成」用于烹饪，不能用于语言。"}, "sentence_index": 0, "correct_answer": "译"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她坐在沙发上，译着旧相册。", "explanation": "这里应该用〈翻看〉。译是把文字转换成另一种语言，相册是图片，要翻看。"}, {"text": "她每天早上译一杯牛奶。", "explanation": "这里应该用〈喝〉。译是语言转换，牛奶是饮品，要喝，不能说译。"}, {"text": "他花了一下午译那把旧吉他。", "explanation": "这里应该用〈修补〉。译是语言转换，吉他是乐器，要修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，正是本词的意思。"}, {"text": "一", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是数字「一」。"}, {"text": "以", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用、凭借。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，意思是移动。"}, {"text": "医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是医生、治病。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，正是本词的意思。", "一": "yī（第一声）与 yì（第四声）声调不同，意思是数字「一」。", "以": "yǐ（第三声）与 yì（第四声）声调不同，意思是用、凭借。", "移": "yí（第二声）与 yì（第四声）声调不同，意思是移动。", "医": "yī（第一声）与 yì（第四声）声调不同，意思是医生、治病。"}, "sentence_index": null, "correct_answer": "译"}, "level_3": {"options": [{"text": "译", "is_correct": true, "explanation": "译：翻译，把文字转换成另一种语言，符合「他……过很多本德国小说」。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，小说不能吃。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，小说不能唱。"}, {"text": "跳", "is_correct": false, "explanation": "配价：「跳」是不及物动词，不能带「小说」作宾语。"}], "explanations": {"译": "译：翻译，把文字转换成另一种语言，符合「他……过很多本德国小说」。", "吃": "搭配：「吃」的对象是食物，小说不能吃。", "唱": "搭配：「唱」的对象是歌曲，小说不能唱。", "跳": "配价：「跳」是不及物动词，不能带「小说」作宾语。"}, "sentence_index": 6, "correct_answer": "译"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计每天都译一遍收支。", "explanation": "这里应该用〈计算〉。译是语言转换，收支是数字，要计算。"}, {"text": "妈妈在厨房译晚饭。", "explanation": "这里应该用〈做〉。译只用于语言文字，晚饭要做，不能说译。"}, {"text": "工匠每天都译一扇屏风。", "explanation": "这里应该用〈修复〉。译是语言转换，屏风是器物，要修复，不能说译。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同译很准确。", "corrected_sentence": "这份合同译得很准确。", "error_description": "「译」与「很准确」之间需要补语标记「得」，应说「译得很准确」，不能直接说「译很准确」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌的歌词译给了英文。", "corrected_sentence": "这首歌的歌词译成了英文。", "error_description": "「译」后接语言时要用「成」，应说「译成了英文」；「给」表示给予的对象，不能与「英文」搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走出", "is_correct": true, "explanation": "正确。走出与走进是反义词，指从里面走到外面，方向相反。"}, {"text": "写", "is_correct": false, "explanation": "“写”是书写动作，与“走进”的移动义没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”是发声演唱，与“走进”的移动义没有反义关系。"}, {"text": "站", "is_correct": false, "explanation": "“站”指身体直立不动，与“走进”的移动义没有反义关系。"}], "correct_answer": "走出", "explanations": {"走出": "正确。走出与走进是反义词，指从里面走到外面，方向相反。", "写": "“写”是书写动作，与“走进”的移动义没有反义关系。", "唱": "“唱”是发声演唱，与“走进”的移动义没有反义关系。", "站": "“站”指身体直立不动，与“走进”的移动义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走出", "is_correct": true, "explanation": "正确。走出与走进是反义词，指从里面走到外面，方向相反。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与“走进”没有反义关系。"}, {"text": "听", "is_correct": false, "explanation": "“听”指用耳朵接收声音，与“走进”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指把食物咽下，与“走进”没有反义关系。"}], "correct_answer": "走出", "explanations": {"走出": "正确。走出与走进是反义词，指从里面走到外面，方向相反。", "跑": "“跑”指快速移动，与“走进”没有反义关系。", "听": "“听”指用耳朵接收声音，与“走进”没有反义关系。", "吃": "“吃”指把食物咽下，与“走进”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走进是从外面走到里面去。", "primary_collocate": null, "pronunciation": "zǒu jìn", "ipa": "tsoʊ˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "请走进来坐一会儿。", "target_word": "走进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从门外走进屋里。", "target_word": "走进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们从操场走进教学楼。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看见一个人走进了那家书店。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门开了，一位老人走进来。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从大门走进学校，向教室走去。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才有人走进了我们的房间。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳很大，他走进树下的阴影里。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面太冷，快走进屋里吧。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们排好队，一个一个走进会议室。", "target_word": "走进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走进了", "label": "体标（了）"}, {"form": "走进来", "label": "复合"}, {"form": "走进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "从外面向里面移动，强调由外到内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走进", "is_correct": true, "explanation": "正确。“请走进来”表示请人从外面进到屋里，符合语境。"}, {"text": "飞进", "is_correct": false, "explanation": "语义：“飞”指在空中移动，请人进屋坐不会说“飞进来”。"}, {"text": "滚进", "is_correct": false, "explanation": "语域：“滚”带有驱赶、粗鲁的色彩，与礼貌邀请的语域不符。"}, {"text": "开进", "is_correct": false, "explanation": "搭配：“开进”多指车辆驶入，请人步行进屋不说“开进来”。"}], "explanations": {"走进": "正确。“请走进来”表示请人从外面进到屋里，符合语境。", "飞进": "语义：“飞”指在空中移动，请人进屋坐不会说“飞进来”。", "滚进": "语域：“滚”带有驱赶、粗鲁的色彩，与礼貌邀请的语域不符。", "开进": "搭配：“开进”多指车辆驶入，请人步行进屋不说“开进来”。"}, "sentence_index": 0, "correct_answer": "走进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走进了屋顶。", "explanation": "这里应该用〈爬上〉。走进表示从外面到里面，站到屋顶上要用〈爬上〉。"}, {"text": "一条鱼走进了水草中。", "explanation": "这里应该用〈游进〉。走进指步行，鱼在水中移动要用〈游进〉。"}, {"text": "子弹走进了墙里。", "explanation": "这里应该用〈射进〉。走进指人步行从外面到里面去，子弹飞入墙中要用〈射进〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走进", "is_correct": true, "explanation": "正确。“刚才有人走进了我们的房间”表示有人从外面进入房间。"}, {"text": "驶进", "is_correct": false, "explanation": "搭配：“驶”多用于车船，“有人”不能说驶进房间。"}, {"text": "游进", "is_correct": false, "explanation": "语义：“游”是在水中移动，有人不能游进房间。"}, {"text": "漂进", "is_correct": false, "explanation": "语义：“漂”指随水或空气浮动，有人不会漂进房间。"}], "explanations": {"走进": "正确。“刚才有人走进了我们的房间”表示有人从外面进入房间。", "驶进": "搭配：“驶”多用于车船，“有人”不能说驶进房间。", "游进": "语义：“游”是在水中移动，有人不能游进房间。", "漂进": "语义：“漂”指随水或空气浮动，有人不会漂进房间。"}, "sentence_index": 6, "correct_answer": "走进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他走进了台阶。", "explanation": "这里应该用〈走上〉。走进要求进入有边界的空间，站到台阶上要用〈走上〉。"}, {"text": "他走进了被子里。", "explanation": "这里应该用〈钻进〉。走进指步行进入，钻入被子要用〈钻进〉。"}, {"text": "牛奶走进了杯子里。", "explanation": "这里应该用〈倒进〉。走进指人从外面到里面去，液体不能自己行走，倒入杯中要用〈倒进〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从操场走进到那座教学楼。", "corrected_sentence": "我们从操场走进那座教学楼。", "error_description": "补语重复。“走进”已经含有“进”的方向，后面不能再加“到”。正确说法是“走进那座教学楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刚才有位客人走进着我们的房间。", "corrected_sentence": "刚才有位客人走进了我们的房间。", "error_description": "动态助词错误。“走进”表示一次完成的动作，应用“了”，不能用“着”。正确说法是“走进了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
