INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "步行进入某个地方。", "primary_collocate": null, "pronunciation": "zǒu jìn", "ipa": "tsoʊ˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他走进教室。", "target_word": "走进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师走进了教室。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们慢慢走进公园。", "target_word": "走进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗走进了厨房。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她轻轻走进房间，怕吵醒孩子。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面下雨了，我们走进商店躲雨。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人走进餐厅，找了一张桌子。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走进医院，问护士怎么挂号。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们走进电影院，找到了座位。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个男人走进银行，排在最后。", "target_word": "走进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "走进了", "label": "体标（了）"}, {"form": "走进来", "label": "复合"}, {"form": "走进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "用脚步行进入某个场所或空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走进", "is_correct": true, "explanation": "正确。走进表示步行进入某个地方，符合“他走进教室”。"}, {"text": "游进", "is_correct": false, "explanation": "语义：“游”是在水中移动，人走进教室不是游进去。"}, {"text": "飞进", "is_correct": false, "explanation": "语义：“飞”指在空中移动，人不会飞进教室。"}, {"text": "驶进", "is_correct": false, "explanation": "搭配：“驶”多用于车船，人走进教室不说“驶进”。"}], "explanations": {"走进": "正确。走进表示步行进入某个地方，符合“他走进教室”。", "游进": "语义：“游”是在水中移动，人走进教室不是游进去。", "飞进": "语义：“飞”指在空中移动，人不会飞进教室。", "驶进": "搭配：“驶”多用于车船，人走进教室不说“驶进”。"}, "sentence_index": 0, "correct_answer": "走进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他走进了马路。", "explanation": "这里应该用〈走上〉。走进强调进入有边界的空间，走到马路上要用〈走上〉。"}, {"text": "他走进了山顶。", "explanation": "这里应该用〈爬上〉。走进指进入有边界的空间，山顶不是可以步行进入的空间，要用〈爬上〉。"}, {"text": "他走进了桌子旁边。", "explanation": "这里应该用〈走到〉。走进强调进入有边界的空间，停在桌子旁边要用〈走到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走进", "is_correct": true, "explanation": "正确。走进餐厅表示步行进入，符合“客人走进餐厅”。"}, {"text": "开进", "is_correct": false, "explanation": "搭配：“开进”多指车辆驶入，客人步行进入餐厅不说“开进”。"}, {"text": "躺进", "is_correct": false, "explanation": "语义：“躺”指身体平卧，客人平躺着进入餐厅说不通。"}, {"text": "爬进", "is_correct": false, "explanation": "语义：“爬”指四肢着地移动，客人走进餐厅不是爬进去。"}], "explanations": {"走进": "正确。走进餐厅表示步行进入，符合“客人走进餐厅”。", "开进": "搭配：“开进”多指车辆驶入，客人步行进入餐厅不说“开进”。", "躺进": "语义：“躺”指身体平卧，客人平躺着进入餐厅说不通。", "爬进": "语义：“爬”指四肢着地移动，客人走进餐厅不是爬进去。"}, "sentence_index": 6, "correct_answer": "走进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一块石头走进了水里。", "explanation": "这里应该用〈滚进〉。走进指步行进入某个地方，石头不能自己移动，滚入水中要用〈滚进〉。"}, {"text": "一箱苹果走进了仓库。", "explanation": "这里应该用〈搬进〉。走进指人步行进入，货物不能自己行走，搬入仓库要用〈搬进〉。"}, {"text": "蛇走进了洞里。", "explanation": "这里应该用〈爬进〉。走进指步行进入，蛇是爬行，钻入洞中要用〈爬进〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹走进来房间，看了看。", "corrected_sentence": "妹妹走进房间，看了看。", "error_description": "趋向补语位置错误。“来”不能插在“走进”和宾语之间，应去掉“来”，说“走进房间”；如要表示朝说话人方向，应说“走进房间来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我走进在教室，把书放在桌上。", "corrected_sentence": "我走进教室，把书放在桌上。", "error_description": "多余介词。“走进”后直接接处所宾语，不能再加“在”。正确说法是“走进教室”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
