INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有遇上或没有抓住（机会、时间等）。", "primary_collocate": null, "pronunciation": "cuò guò", "ipa": "tsʰuɔ˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他没有好好努力，错过了这次机会。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忙着工作，错过了报名的时间。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好机会只有一次，别错过。", "target_word": "错过", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她来得太晚，错过了最好的时机。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻时错过的机会，以后很难再有。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直没准备好，错过了申请的机会。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天很短，不要错过赏花的好时间。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天加班，错过了和家人在一起的好时光。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犹豫了半天，结果错过了最好的买房时机。", "target_word": "错过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换工作太慢，错过了升职的机会。", "target_word": "错过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错过了", "label": "体标"}], "register": "中性", "sense_fingerprint": "错过：没抓住机会、时机或时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af238286-c549-4cf8-8736-86ca312c2e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争取", "is_correct": false, "explanation": "语义：“争取”要靠主动努力去求得，与“没有好好努力”正相矛盾。"}, {"text": "错过", "is_correct": true, "explanation": "正确：“错过”指没有抓住机会，与“没有好好努力”的语境一致。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多接待遇、生活等，不说“享受机会”。"}, {"text": "把握", "is_correct": false, "explanation": "语义：“把握”表示抓住机会，与“没有好好努力”的语境相悖。"}], "explanations": {"争取": "语义：“争取”要靠主动努力去求得，与“没有好好努力”正相矛盾。", "错过": "正确：“错过”指没有抓住机会，与“没有好好努力”的语境一致。", "享受": "搭配：“享受”多接待遇、生活等，不说“享受机会”。", "把握": "语义：“把握”表示抓住机会，与“没有好好努力”的语境相悖。"}, "sentence_index": 0, "correct_answer": "错过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师错过了他这次迟到，没有批评。", "explanation": "这里应该用〈放过〉。“错过”指没遇上或没抓住，不能表示“不追究”。"}, {"text": "他错过了作业里的一个逗号，被扣了分。", "explanation": "这里应该用〈漏掉〉。“错过”用于机会、时间、活动，不能说“错过一个逗号”。"}, {"text": "我们错过了迎面飞来的石头。", "explanation": "这里应该用〈躲开〉。“错过”指没遇上机会或事件，不能表示“躲避”危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珍惜", "is_correct": false, "explanation": "语义：“珍惜”表示珍视，与“不要”组合后意思与“春天很短”的劝勉相反。"}, {"text": "错过", "is_correct": true, "explanation": "正确：“错过”指没有遇上，句中表示不要让好时光从身边溜走。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”接景物、作品，不接“好时间”这样的时段。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约”表示省下，与“不要”组合后意思与语境的珍惜之意相反。"}], "explanations": {"珍惜": "语义：“珍惜”表示珍视，与“不要”组合后意思与“春天很短”的劝勉相反。", "错过": "正确：“错过”指没有遇上，句中表示不要让好时光从身边溜走。", "欣赏": "搭配：“欣赏”接景物、作品，不接“好时间”这样的时段。", "节约": "语义：“节约”表示省下，与“不要”组合后意思与语境的珍惜之意相反。"}, "sentence_index": 6, "correct_answer": "错过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于错过了困境，松了一口气。", "explanation": "这里应该用〈摆脱〉。“错过”用于机会、时间、活动，不能说“错过困境”。"}, {"text": "她错过了窗户，觉得很冷。", "explanation": "这里应该用〈打开〉。“错过”指没遇上或没抓住机会、时间，不能跟“窗户”这类物体搭配。"}, {"text": "他们错过了这份快乐，玩得很开心。", "explanation": "这里应该用〈分享〉。“错过”表示没抓住，与后半句“玩得很开心”自相矛盾；想说一起享受快乐，应说“分享快乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为犹豫，错过过这次机会。", "corrected_sentence": "他因为犹豫，错过了这次机会。", "error_description": "错在体标：“过”表示过去的经历，不能用来说“这次机会”这样具体、已完成的一件事。应用“了”，说“错过了这次机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她因为临时出差，错过着这个难得的机会。", "corrected_sentence": "她因为临时出差，错过了这个难得的机会。", "error_description": "“错过”后面不能接“着”表示持续，这里说的是已经发生的事，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开通是把原来不通的路或线弄通,让人可以用。", "primary_collocate": null, "pronunciation": "kāi tōng", "ipa": "kʰaɪ˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这条新路下个月开通。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把山里的路开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁三号线昨天开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里修了一条新路，终于开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想开通一条去海边的路。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水堵住了,大家把水路开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥开通以后,过河很方便。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路开通以后,卖菜的人多起来了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老家终于开通了去县城的公路。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路的人把断了的路开通了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开通了", "label": "体标"}, {"form": "开通过", "label": "体标"}, {"form": "開通", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把不通的路或线弄通,让人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开通", "is_correct": true, "explanation": "开通指路线可以开始使用，符合“下个月开通”的句意。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：关闭是停止使用，与新路刚建成、准备使用的句意相反。"}, {"text": "消失", "is_correct": false, "explanation": "语义：新路不会在下个月消失。"}, {"text": "堵塞", "is_correct": false, "explanation": "搭配：“堵塞”说的是已经有的路被挡住，与“新路下个月”不搭配。"}], "explanations": {"开通": "开通指路线可以开始使用，符合“下个月开通”的句意。", "关闭": "语义：关闭是停止使用，与新路刚建成、准备使用的句意相反。", "消失": "语义：新路不会在下个月消失。", "堵塞": "搭配：“堵塞”说的是已经有的路被挡住，与“新路下个月”不搭配。"}, "sentence_index": 0, "correct_answer": "开通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个景区去年终于开通了，游客很多。", "explanation": "这里应该用〈开放〉。景区、公园要说“开放”，“开通”多用于路、线、服务。"}, {"text": "工人们终于开通了山里的那座铁矿。", "explanation": "这里应该用〈开采〉。矿产、资源要说“开采”，“开通”指把路或线弄通，多用于路、线、服务。"}, {"text": "工厂的机器终于开通了，大家都很高兴。", "explanation": "这里应该用〈启动〉。机器要说“启动”，“开通”多用于路、线、服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开通", "is_correct": true, "explanation": "开通指桥可以开始通行，“开通以后，过河很方便”符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：桥被拆除后，过河不会方便。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：桥损坏后，过河会更不方便。"}, {"text": "封住", "is_correct": false, "explanation": "搭配：“封住”多用于门窗、出口，不用来说桥的通行状态。"}], "explanations": {"开通": "开通指桥可以开始通行，“开通以后，过河很方便”符合句意。", "拆除": "语义：桥被拆除后，过河不会方便。", "损坏": "语义：桥损坏后，过河会更不方便。", "封住": "搭配：“封住”多用于门窗、出口，不用来说桥的通行状态。"}, "sentence_index": 6, "correct_answer": "开通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司决定开通海外市场。", "explanation": "这里应该用〈开发〉。市场、资源要说“开发”，“开通”多用于路、线、服务。"}, {"text": "他轻轻开通了门，走了进去。", "explanation": "这里应该用〈打开〉。门要说“打开”，“开通”不用于门。"}, {"text": "他们开通了一家新店。", "explanation": "这里应该用〈开设〉。店铺、公司要说“开设”，“开通”多用于路、线、服务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们把这座桥开通。", "corrected_sentence": "工人们把这座桥开通了。", "error_description": "把字句要有“了”或其他补充成分才完整：“把这座桥开通”不完整，应说“把这座桥开通了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥明天就会开通着。", "corrected_sentence": "这座桥明天就会开通。", "error_description": "“着”表示动作或状态正在持续，不能与将来的“明天就会”一起用，应直接说“就会开通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
