INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94444, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94444, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始启用某项服务，使其可以使用。", "primary_collocate": null, "pronunciation": "kāi tōng", "ipa": "kʰaɪ˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我开通了微信支付。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈帮我开通了流量包。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行已经给你开通了网上银行。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问怎么开通会员?", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行今年开通了手机转账服务。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给爷爷开通手机上网。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会员开通以后,你就可以看所有的电影了。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把网络开通了,马上给家人打电话。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为客人开通了免费的网络。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚到国外，就开通了国际漫游。", "target_word": "开通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开通了", "label": "体标"}, {"form": "开通过", "label": "体标"}, {"form": "開通", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开始启用某项服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开通", "is_correct": true, "explanation": "开通指开始启用某项服务，“我开通了微信支付”符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，不能是支付服务。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或环境，不能用于支付服务。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮的是食物，与支付服务不合。"}], "explanations": {"开通": "开通指开始启用某项服务，“我开通了微信支付”符合句意。", "吃": "语义：吃的对象是食物，不能是支付服务。", "打扫": "搭配：“打扫”的对象是场所或环境，不能用于支付服务。", "煮": "语义：煮的是食物，与支付服务不合。"}, "sentence_index": 0, "correct_answer": "开通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校开通了一个新的兴趣班。", "explanation": "这里应该用〈开办〉。班级、学校要说“开办”，“开通”多用于服务、线路。"}, {"text": "他按下按钮，开通了电脑。", "explanation": "这里应该用〈启动〉。电脑、机器要说“启动”，“开通”多用于服务、线路。"}, {"text": "他开通了文件，开始修改内容。", "explanation": "这里应该用〈打开〉。文件要说“打开”，“开通”多用于服务、线路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开通", "is_correct": true, "explanation": "开通是会员开始生效，“会员开通以后，你就可以看电影了”符合句意。"}, {"text": "取消", "is_correct": false, "explanation": "语义：会员取消后就不能看电影了，与句意相反。"}, {"text": "结束", "is_correct": false, "explanation": "语义：会员结束以后就不能看电影了，与句意相反。"}, {"text": "过期", "is_correct": false, "explanation": "语义：会员过期以后同样不能看电影，与句意相反。"}], "explanations": {"开通": "开通是会员开始生效，“会员开通以后，你就可以看电影了”符合句意。", "取消": "语义：会员取消后就不能看电影了，与句意相反。", "结束": "语义：会员结束以后就不能看电影了，与句意相反。", "过期": "语义：会员过期以后同样不能看电影，与句意相反。"}, "sentence_index": 6, "correct_answer": "开通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议开通了新的篇章。", "explanation": "这里应该用〈开启〉。“篇章”要说“开启”，“开通”多用于服务、线路。"}, {"text": "学校开通了新的活动。", "explanation": "这里应该用〈开展〉。活动要说“开展”，“开通”多用于服务、线路。"}, {"text": "这家超市下个月开通，欢迎大家来。", "explanation": "这里应该用〈开业〉。商店、超市要说“开业”，“开通”不用于商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把会员开通。", "corrected_sentence": "我已经把会员开通了。", "error_description": "把字句缺少补语“了”：“把”字句的谓语后面要有补语或“了”等成分，句子才完整。应说“我已经把会员开通了”，不能只说“我已经把会员开通”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下周就会开通着宽带。", "corrected_sentence": "我下周就会开通宽带。", "error_description": "“着”表示动作或状态正在持续，不能与将来的“下周就会”一起用，这里应直接说“会开通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
