INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风景是一个地方看起来很美的山、水、树和花。", "primary_collocate": null, "pronunciation": "fēng jǐng", "ipa": "fɤŋ˥ tɕiŋ˨˩", "syllable_count": 2, "sentences": [{"text": "这里的风景真漂亮。", "target_word": "风景", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的风景很美。", "target_word": "风景", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "从窗户可以看到海边的风景。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐在河边看风景。", "target_word": "风景", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋天的公园里，风景最好看。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方有山有水，风景很好。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢拍下路上的风景。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车开得很慢，我们看够了路上的风景。", "target_word": "风景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的风景，让我想起了老家。", "target_word": "风景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，山上的花和树都成了美丽的风景。", "target_word": "风景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "风景区", "label": "复合"}, {"form": "风景画", "label": "复合"}, {"form": "風景", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个地方看起来很美的山水花木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风景", "is_correct": true, "explanation": "风景指可以观赏的山水景象，与“真漂亮”相符，正确。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不能用“漂亮”来形容，句意不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：人口指人数，不能与“真漂亮”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道说的是口感，与“真漂亮”不协调。"}], "explanations": {"风景": "风景指可以观赏的山水景象，与“真漂亮”相符，正确。", "价格": "语义：价格是钱数，不能用“漂亮”来形容，句意不通。", "人口": "搭配：人口指人数，不能与“真漂亮”搭配。", "味道": "语义：味道说的是口感，与“真漂亮”不协调。"}, "sentence_index": 0, "correct_answer": "风景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们住的风景很干净。", "explanation": "这里应该用〈宿舍〉。风景指看得见的自然景象，不能指住的地方，住的地方要说宿舍。"}, {"text": "他的风景很漂亮。", "explanation": "这里应该用〈相貌〉。风景指自然景物，不能用来形容人的外貌。"}, {"text": "他这次投资的风景很大。", "explanation": "这里应该用〈风险〉。风景指看到的自然景象，不能说投资的危险程度，那要说风险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风景", "is_correct": true, "explanation": "风景是可以拍下来欣赏的景象，与“路上”相符，正确。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是消费清单，不是可以拍下来欣赏的景物。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能被“拍下”，也不是可以欣赏的景象，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄不能被“拍下”，与“路上的”搭配不通。"}], "explanations": {"风景": "风景是可以拍下来欣赏的景象，与“路上”相符，正确。", "账单": "语义：账单是消费清单，不是可以拍下来欣赏的景物。", "声音": "语义：声音不能被“拍下”，也不是可以欣赏的景象，句意不通。", "年龄": "搭配：年龄不能被“拍下”，与“路上的”搭配不通。"}, "sentence_index": 6, "correct_answer": "风景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的风景很美好。", "explanation": "这里应该用〈生活〉。风景只指看得见的自然景象，不能用来说人的日子。"}, {"text": "他的风景很高。", "explanation": "这里应该用〈收入〉。风景不能说高低，收入才可以说很高。"}, {"text": "他有很高的风景。", "explanation": "这里应该用〈天赋〉。风景是自然景象，不能说有很高的风景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湖的一只风景很美。", "corrected_sentence": "这片湖的风景很美。", "error_description": "错误形式：一只风景；正确形式：风景（或一片风景）。“风景”是景色，量词应用“片”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一路都看着一只风景，很开心。", "corrected_sentence": "我们一路都看着风景，很开心。", "error_description": "错误形式：看着一只风景；正确形式：看着风景（或看着一片风景）。“风景”是景色，量词应用“片”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
