INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94447, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "惊喜是想不到的好事，让你又吃惊又高兴。", "primary_collocate": null, "pronunciation": "jīng xǐ", "ipa": "tɕiŋ˥ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "生日那天，朋友给了我一个大惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想给妈妈一个惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开门，里面有一个惊喜等着我。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物是老师送给大家的惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提前回家，想给家人一个惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行有很多惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我准备了一个惊喜，你猜是什么？", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日派对上，最大的惊喜是爸爸也来了。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没告诉他，因为这是个惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他结婚那天，朋友们给他带来了一个惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个惊喜", "label": "量词"}, {"form": "驚喜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想不到的好事、好意外（可以送给别人的一件事或礼物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94447, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惊喜", "is_correct": true, "explanation": "正确：惊喜（jīng xǐ）指意外的好事，即本词。"}, {"text": "惊醒", "is_correct": false, "explanation": "xǐng 比 xǐ 多了韵尾 ng，意思是突然醒来，与“惊喜”的韵母不同。"}, {"text": "精细", "is_correct": false, "explanation": "“细”xì 与“喜”xǐ 声调不同（第四声与第三声），意思是精密、细致。"}, {"text": "惊起", "is_correct": false, "explanation": "“起”qǐ 与“喜”xǐ 声母不同（q 与 x），意思是受惊后突然站起或飞起。"}], "explanations": {"惊喜": "正确：惊喜（jīng xǐ）指意外的好事，即本词。", "惊醒": "xǐng 比 xǐ 多了韵尾 ng，意思是突然醒来，与“惊喜”的韵母不同。", "精细": "“细”xì 与“喜”xǐ 声调不同（第四声与第三声），意思是精密、细致。", "惊起": "“起”qǐ 与“喜”xǐ 声母不同（q 与 x），意思是受惊后突然站起或飞起。"}, "sentence_index": null, "correct_answer": "惊喜"}, "level_3": {"options": [{"text": "惊喜", "is_correct": true, "explanation": "正确：惊喜指意外的好事，与生日那天朋友送的意外之事相符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”不能用“给了我一个大……”来表达，而且生病也不是朋友送的。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”指严重的不幸，与生日的欢乐语境冲突。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是令人紧张的事，不是意外的好事，与生日的惊喜语境不符。"}], "explanations": {"惊喜": "正确：惊喜指意外的好事，与生日那天朋友送的意外之事相符。", "感冒": "搭配：“感冒”不能用“给了我一个大……”来表达，而且生病也不是朋友送的。", "灾难": "语义：“灾难”指严重的不幸，与生日的欢乐语境冲突。", "考试": "语义：“考试”是令人紧张的事，不是意外的好事，与生日的惊喜语境不符。"}, "sentence_index": 0, "correct_answer": "惊喜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友给了我一个惊喜，我的钱包被偷了。", "explanation": "语义：惊喜是让人高兴的意外好事，钱包被偷是坏事，不能叫惊喜。"}, {"text": "老师给我们准备了一个惊喜：明天加考三门课。", "explanation": "语义：加考是让人不高兴的事，不是惊喜。"}, {"text": "他想给妈妈一个惊喜，就把她的花瓶打碎了。", "explanation": "语义：惊喜是好事，打碎花瓶是坏事，不能说是给人的惊喜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惊喜", "is_correct": true, "explanation": "正确：惊喜指给人准备的意外好事，与“准备了一个”和“你猜是什么”相符。"}, {"text": "噩梦", "is_correct": false, "explanation": "语义：“噩梦”是可怕的梦，与“准备”和“你猜是什么”的轻松语气不符。"}, {"text": "事故", "is_correct": false, "explanation": "搭配：“准备”后不能接“事故”，事故是突然发生的，不能预先准备。"}, {"text": "误会", "is_correct": false, "explanation": "语义：“误会”指彼此理解错误，不能作为准备好要送出的东西。"}], "explanations": {"惊喜": "正确：惊喜指给人准备的意外好事，与“准备了一个”和“你猜是什么”相符。", "噩梦": "语义：“噩梦”是可怕的梦，与“准备”和“你猜是什么”的轻松语气不符。", "事故": "搭配：“准备”后不能接“事故”，事故是突然发生的，不能预先准备。", "误会": "语义：“误会”指彼此理解错误，不能作为准备好要送出的东西。"}, "sentence_index": 6, "correct_answer": "惊喜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这个惊喜吃了下去。", "explanation": "语义：惊喜指意外的好事或礼物，不是食物，不能用“吃”。"}, {"text": "看到他摔倒，大家惊喜地围了过来。", "explanation": "这里应该用〈惊奇〉。摔倒是不好的事，惊喜表示好的意外，应用惊奇。"}, {"text": "看到窗外的闪电，她惊喜地捂住了耳朵。", "explanation": "这里应该用〈惊恐〉。闪电让人害怕，惊喜表示高兴，应用惊恐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的生日快到了，我想给她一只惊喜。", "corrected_sentence": "妈妈的生日快到了，我想给她一个惊喜。", "error_description": "量词错误：“惊喜”作礼物或事件时应用“个”，写成“一只惊喜”是错误的，“只”多用于动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们为她准备了一个很惊喜。", "corrected_sentence": "我们为她准备了一个惊喜。", "error_description": "副词错误：“惊喜”作名词时，“一个惊喜”前不能加“很”，应去掉“很”，写作“一个惊喜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
