INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "意外的高兴；出乎意料的喜悦。", "primary_collocate": null, "pronunciation": "jīng xǐ", "ipa": "tɕiŋ˥ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "看到成绩，他的脸上满是惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼睛里充满了惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到礼物时，孩子的惊喜写在脸上。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个好消息，大家又是惊喜又是激动。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他掩不住心中的惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脸上带着惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他难以掩饰自己的惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一刻，我心里只有惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着新家，妈妈的惊喜变成了感动。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下了一夜，早上孩子们满心惊喜。", "target_word": "惊喜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驚喜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里或脸上出现的意外喜悦的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94448, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "惊喜", "is_correct": true, "explanation": "正确：惊喜（jīng xǐ）指心里意外的喜悦，即本词。"}, {"text": "惊醒", "is_correct": false, "explanation": "xǐng 比 xǐ 多了韵尾 ng，意思是突然醒来，与“惊喜”的韵母不同。"}, {"text": "精细", "is_correct": false, "explanation": "“细”xì 与“喜”xǐ 声调不同（第四声与第三声），意思是精密、细致。"}, {"text": "惊起", "is_correct": false, "explanation": "“起”qǐ 与“喜”xǐ 声母不同（q 与 x），意思是受惊后突然站起或飞起。"}], "explanations": {"惊喜": "正确：惊喜（jīng xǐ）指心里意外的喜悦，即本词。", "惊醒": "xǐng 比 xǐ 多了韵尾 ng，意思是突然醒来，与“惊喜”的韵母不同。", "精细": "“细”xì 与“喜”xǐ 声调不同（第四声与第三声），意思是精密、细致。", "惊起": "“起”qǐ 与“喜”xǐ 声母不同（q 与 x），意思是受惊后突然站起或飞起。"}, "sentence_index": null, "correct_answer": "惊喜"}, "level_3": {"options": [{"text": "惊喜", "is_correct": true, "explanation": "正确：惊喜表示意外的高兴，与看到成绩后脸上的表情相符。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“脸上满是”后面不能接“礼物”，礼物不能出现在脸上。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”不是可以写在脸上的感受，与“满是”的搭配不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“脸上满是”后面不能接具体的物品，冰箱不能出现在脸上。"}], "explanations": {"惊喜": "正确：惊喜表示意外的高兴，与看到成绩后脸上的表情相符。", "礼物": "搭配：“脸上满是”后面不能接“礼物”，礼物不能出现在脸上。", "灾难": "语义：“灾难”不是可以写在脸上的感受，与“满是”的搭配不通。", "冰箱": "搭配：“脸上满是”后面不能接具体的物品，冰箱不能出现在脸上。"}, "sentence_index": 0, "correct_answer": "惊喜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火灾突然发生，大家一片惊喜。", "explanation": "这里应该用〈惊慌〉。惊喜表示意外的高兴，火灾时应用惊慌。"}, {"text": "看到屋里突然窜出一条蛇，她惊喜地后退了几步。", "explanation": "这里应该用〈惊吓〉。惊喜表示意外的高兴，蛇突然窜出应是害怕，不能用惊喜。"}, {"text": "看到窗外的闪电，大家惊喜地捂住了耳朵。", "explanation": "这里应该用〈惊恐〉。闪电让人害怕，惊喜表示高兴，应用惊恐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惊喜", "is_correct": true, "explanation": "正确：惊喜表示心里的喜悦，可以被掩饰，与“难以掩饰自己的”相符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“掩饰”的对象应是情绪，不能是房子这样的具体事物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的内心感受，与“掩饰自己的”的意思不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“掩饰”的对象应是情绪，石头不能被掩饰。"}], "explanations": {"惊喜": "正确：惊喜表示心里的喜悦，可以被掩饰，与“难以掩饰自己的”相符。", "房子": "搭配：“掩饰”的对象应是情绪，不能是房子这样的具体事物。", "天气": "语义：天气不是人的内心感受，与“掩饰自己的”的意思不符。", "石头": "搭配：“掩饰”的对象应是情绪，石头不能被掩饰。"}, "sentence_index": 6, "correct_answer": "惊喜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他惊喜地看着被撞坏的汽车，说不出话来。", "explanation": "这里应该用〈惊讶〉。惊喜表示意外的高兴，车被撞坏时不能高兴，应用惊讶。"}, {"text": "听到老人去世的消息，大家惊喜地愣在原地。", "explanation": "这里应该用〈惊愕〉。惊喜表示高兴，听到噩耗时应是惊愕，不能用惊喜。"}, {"text": "深夜里听到门外有人敲门，他惊喜地抄起了棍子。", "explanation": "这里应该用〈害怕〉。惊喜表示高兴，深夜敲门应是害怕，不能用惊喜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈听到这个消息，心里涌起一只惊喜。", "corrected_sentence": "妈妈听到这个消息，心里涌起一阵惊喜。", "error_description": "量词错误：表示心里涌起的情绪应用“阵”，写成“只”是错误的，“只”多用于动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到结果后，他的脸上闪过一丝很惊喜。", "corrected_sentence": "听到结果后，他的脸上闪过一丝惊喜。", "error_description": "副词错误：“惊喜”作名词时，“一丝惊喜”前不能加“很”，应去掉“很”，写作“一丝惊喜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
