INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "体内是身体的里面。", "primary_collocate": null, "pronunciation": "tǐ nèi", "ipa": "tʰi˨˩ nei̯˥˩", "syllable_count": 2, "sentences": [{"text": "药进入体内以后，要过一会儿才有用。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动时，体内会产生很多热量。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他体内缺少铁。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水在体内帮助食物变成能量。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天喝一杯热茶，体内很快就暖了。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种细菌一旦进入体内，就会让人发烧。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肝脏会把体内的酒精慢慢分解掉。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长身体，体内需要很多钙。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，他觉得体内有一股力量。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蛇的体内有毒。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体的里面，进入或存在于身体之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "正确。药要进入身体里面才能起作用，“体内”与“进入”相符。"}, {"text": "体外", "is_correct": false, "explanation": "语义：“体外”指身体之外，药不能“进入体外”，与“进入”矛盾。"}, {"text": "桌面", "is_correct": false, "explanation": "语义：“桌面”不是身体的一部分，药不会“进入桌面”后再起作用。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“进入”一般接身体、容器或具体空间，不说“进入空气”。"}], "explanations": {"体内": "正确。药要进入身体里面才能起作用，“体内”与“进入”相符。", "体外": "语义：“体外”指身体之外，药不能“进入体外”，与“进入”矛盾。", "桌面": "语义：“桌面”不是身体的一部分，药不会“进入桌面”后再起作用。", "空气": "搭配：“进入”一般接身体、容器或具体空间，不说“进入空气”。"}, "sentence_index": 0, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的体内很干净。", "explanation": "这里应该用〈内部〉。体内只指人或动物身体的里面，机器的里面要说内部。"}, {"text": "这个箱子的体内放着很多书。", "explanation": "这里应该用〈里面〉。体内不用于箱子等物体，箱子的里面应说里面。"}, {"text": "他的体内很平静，不慌不忙。", "explanation": "这里应该用〈内心〉。体内指身体里面，说人的心境应说内心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "正确。肝脏分解的是身体里的酒精，“体内”与句意相符。"}, {"text": "杯中", "is_correct": false, "explanation": "语义：肝脏只能分解身体里的物质，“杯中的酒精”不在体内，句意不通。"}, {"text": "瓶里", "is_correct": false, "explanation": "搭配：“瓶里”是容器，不能说肝脏把瓶里的酒精分解掉。"}, {"text": "外界", "is_correct": false, "explanation": "语义：“外界”指身体以外的环境，肝脏无法分解外界的酒精。"}], "explanations": {"体内": "正确。肝脏分解的是身体里的酒精，“体内”与句意相符。", "杯中": "语义：肝脏只能分解身体里的物质，“杯中的酒精”不在体内，句意不通。", "瓶里": "搭配：“瓶里”是容器，不能说肝脏把瓶里的酒精分解掉。", "外界": "语义：“外界”指身体以外的环境，肝脏无法分解外界的酒精。"}, "sentence_index": 6, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木头的体内很光滑。", "explanation": "这里应该用〈表面〉。木头没有身体，说光滑的部位应是表面。"}, {"text": "这间屋子的体内很暖和。", "explanation": "这里应该用〈室内〉。体内只指人或动物身体里面，不用来指房间里面。"}, {"text": "这片森林的体内很暗。", "explanation": "这里应该用〈深处〉。体内不用于森林等地方，森林的深处才是这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃下的药已经进入体内里。", "corrected_sentence": "他吃下的药已经进入体内。", "error_description": "错误在于“体内”后面多加了“里”。“体内”本身已表示身体的里面，不能再加方位词“里”，应说“进入体内”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些营养物质被吸收后，会在体内里慢慢分解。", "corrected_sentence": "这些营养物质被吸收后，会在体内慢慢分解。", "error_description": "错误在于“体内”后面多加了“里”。“体内”已表示身体里面，不能再加方位词“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
