INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体内部。", "primary_collocate": null, "pronunciation": "tǐ nèi", "ipa": "tʰi˨˩ nei̯˥˩", "syllable_count": 2, "sentences": [{"text": "医生用机器检查他的体内。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体内的水太少，人会觉得口渴。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒在体内待了好几天才发作。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体检时，医生看到他体内有一块小石头。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们体内的血液一直在流动。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体温很高，医生说是体内有炎症。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她体内的糖太多，要少吃甜的。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了不干净的东西，体内的毒要排出去。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些细小的东西会留在体内很多年。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动能让体内的血流得更快。", "target_word": "体内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体内部，多用于检查、健康和生理状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "正确。医生用机器检查的是身体内部，“体内”与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：医生检查的是人体，“汽车”不是身体，与“医生”的对象矛盾。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“检查”搭配的是身体或器官，机器检查不了心情。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“检查”不搭配“天气”，天气是观测的对象，不是检查的对象。"}], "explanations": {"体内": "正确。医生用机器检查的是身体内部，“体内”与句意相符。", "汽车": "语义：医生检查的是人体，“汽车”不是身体，与“医生”的对象矛盾。", "心情": "搭配：“检查”搭配的是身体或器官，机器检查不了心情。", "天气": "搭配：“检查”不搭配“天气”，天气是观测的对象，不是检查的对象。"}, "sentence_index": 0, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼的体内很潮湿。", "explanation": "这里应该用〈内部〉。体内只指人或动物身体里面，建筑物的里面要说内部。"}, {"text": "这个包的体内藏着一把钥匙。", "explanation": "这里应该用〈里面〉。体内不用于包等物体，包的里面应说里面。"}, {"text": "他的体内很不安，整夜睡不着。", "explanation": "这里应该用〈内心〉。体内指身体里面，说人的心境不安应说内心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体内", "is_correct": true, "explanation": "正确。糖太多是指身体里的糖，“体内”与句意相符。"}, {"text": "体外", "is_correct": false, "explanation": "语义：“体外”指身体之外，不能说身体外的糖太多，与“要少吃甜的”的理由不符。"}, {"text": "脑子", "is_correct": false, "explanation": "搭配：“糖”不说在“脑子”里多，“脑子的糖”不能这样搭配。"}, {"text": "外界", "is_correct": false, "explanation": "语义：“外界”的糖与她的饮食和身体状况无关，不能作为要少吃甜的理由。"}], "explanations": {"体内": "正确。糖太多是指身体里的糖，“体内”与句意相符。", "体外": "语义：“体外”指身体之外，不能说身体外的糖太多，与“要少吃甜的”的理由不符。", "脑子": "搭配：“糖”不说在“脑子”里多，“脑子的糖”不能这样搭配。", "外界": "语义：“外界”的糖与她的饮食和身体状况无关，不能作为要少吃甜的理由。"}, "sentence_index": 6, "correct_answer": "体内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的体内很深。", "explanation": "这里应该用〈底部〉。体内不用于河流，河的深处应说底部。"}, {"text": "礼堂的体内坐满了人。", "explanation": "这里应该用〈里头〉。体内只指身体里面，不用来指建筑的里头，应说礼堂里头。"}, {"text": "他的体内藏着一个秘密。", "explanation": "这里应该用〈心底〉。体内指身体里面，说藏在心里的秘密应说心底。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种细菌已经在体内里住了很久。", "corrected_sentence": "这种细菌已经在体内住了很久。", "error_description": "错误在于“体内”后面多加了“里”。“体内”已表示身体里面，不能再加方位词“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "检查结果说，他的体内里脂肪偏高。", "corrected_sentence": "检查结果说，他的体内脂肪偏高。", "error_description": "错误在于“体内”后面多加了“里”。“体内”已表示身体里面，不能再加方位词“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
