INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特别能吸引人的力量。", "primary_collocate": null, "pronunciation": "mèi lì", "ipa": "meɪ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "中国茶的魅力让很多外国人爱上了它。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小岛有一种说不出的魅力。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书的魅力在于可以认识新世界。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的魅力不在外表，而在性格。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "京剧的魅力吸引了很多年轻人。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚有自己的魅力。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种语言的魅力，学了才知道。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的魅力打动了所有人。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球为什么有这么大的魅力？", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城的魅力让游客不想离开。", "target_word": "魅力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个人魅力", "label": "复合"}, {"form": "魅力四射", "label": "复合"}], "register": "中性", "sense_fingerprint": "魅力：特别能吸引人的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "魅力", "is_correct": true, "explanation": "mèi lì 指特别能吸引人的力量，是本题的正确答案。"}, {"text": "美丽", "is_correct": false, "explanation": "měilì 第一个音节为第三声，与 mèi 的第四声不同，意思是好看。"}, {"text": "内力", "is_correct": false, "explanation": "nèilì 声母为 n，与 mèi 的 m 不同，意思是体内的力量或内功。"}, {"text": "卖力", "is_correct": false, "explanation": "mài 与 mèi 韵母不同（ài 与 èi），意思是出力、尽力。"}, {"text": "费力", "is_correct": false, "explanation": "fèi 声母为 f，与 mèi 的 m 不同，意思是耗费力气、吃力。"}], "explanations": {"魅力": "mèi lì 指特别能吸引人的力量，是本题的正确答案。", "美丽": "měilì 第一个音节为第三声，与 mèi 的第四声不同，意思是好看。", "内力": "nèilì 声母为 n，与 mèi 的 m 不同，意思是体内的力量或内功。", "卖力": "mài 与 mèi 韵母不同（ài 与 èi），意思是出力、尽力。", "费力": "fèi 声母为 f，与 mèi 的 m 不同，意思是耗费力气、吃力。"}, "sentence_index": null, "correct_answer": "魅力"}, "level_3": {"options": [{"text": "魅力", "is_correct": true, "explanation": "正确：茶有让人爱上的吸引力。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”属于人或动物，不能用来说茶。"}, {"text": "门牌", "is_correct": false, "explanation": "语义：门牌不能让人爱上，与茶无关。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与茶无关，不能让外国人爱上。"}], "explanations": {"魅力": "正确：茶有让人爱上的吸引力。", "体重": "搭配：“体重”属于人或动物，不能用来说茶。", "门牌": "语义：门牌不能让人爱上，与茶无关。", "手机": "语义：手机与茶无关，不能让外国人爱上。"}, "sentence_index": 0, "correct_answer": "魅力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魔术师的魅力能把一块铁板劈成两半。", "explanation": "这里应该用〈魔力〉。“魔力”指神奇的力量，“魅力”指让人喜欢的吸引力，不能把铁板劈开。"}, {"text": "这次任务让他肩上的魅力很大，压得他喘不过气。", "explanation": "这里应该用〈压力〉。“压力”指让人感到负担的力，“魅力”指让人喜欢的吸引力。"}, {"text": "这块吸铁石的魅力很强，一下子就把钉子吸过来了。", "explanation": "这里应该用〈吸力〉。“吸力”指把东西吸过来的力，“魅力”不能用来形容吸铁石。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魅力", "is_correct": true, "explanation": "正确：学了才能体会这种语言吸引人的地方。"}, {"text": "重量", "is_correct": false, "explanation": "语义：语言没有重量，与“学了才知道”的描述不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是学了语言才知道的东西。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“门票”是进场的凭证，不能说学了才知道。"}], "explanations": {"魅力": "正确：学了才能体会这种语言吸引人的地方。", "重量": "语义：语言没有重量，与“学了才知道”的描述不合。", "天气": "语义：天气不是学了语言才知道的东西。", "门票": "搭配：“门票”是进场的凭证，不能说学了才知道。"}, "sentence_index": 6, "correct_answer": "魅力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的魅力很强，一场比赛就打败了所有对手。", "explanation": "这里应该用〈实力〉。“实力”指真实的本领，“魅力”指让人喜欢的吸引力，不能用来决定比赛胜负。"}, {"text": "他的魅力很大，一拳就打碎了那块石头。", "explanation": "这里应该用〈力气〉。“力气”指身体的力量，“魅力”不能用来形容打碎石头的力。"}, {"text": "这枚导弹的魅力很大，一下子炸毁了整座楼。", "explanation": "这里应该用〈威力〉。“威力”指破坏力，“魅力”不能用来形容导弹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古城魅力了很多游客。", "corrected_sentence": "这座古城吸引了很多游客。", "error_description": "“魅力”是名词，不能当动词用。表示“吸引”这一动作应说“吸引”，所以“魅力了很多游客”要改为“吸引了很多游客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家有一个很特别的魅力。", "corrected_sentence": "这位画家有一种很特别的魅力。", "error_description": "“魅力”前应用量词“种”，不能用“个”。“一个魅力”是错误的，应说“一种魅力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "“清楚”与“不明”为反义，指身份清楚、情况已知。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境，与“身份”无关，不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”形容性格，与“身份不明”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”说价格，与“身份”无关，不是“不明”的反义词。"}], "correct_answer": "清楚", "explanations": {"清楚": "“清楚”与“不明”为反义，指身份清楚、情况已知。", "安静": "“安静”形容声音或环境，与“身份”无关，不构成反义。", "勇敢": "“勇敢”形容性格，与“身份不明”没有反义关系。", "便宜": "“便宜”说价格，与“身份”无关，不是“不明”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "“清楚”与“不明”为反义，指来源、情况已知。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”形容声音大，与声音是否清楚无反义关系。"}, {"text": "温柔", "is_correct": false, "explanation": "“温柔”形容性格或语气，与“不明”无反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度，与声音清楚与否无关。"}], "correct_answer": "清楚", "explanations": {"清楚": "“清楚”与“不明”为反义，指来源、情况已知。", "响亮": "“响亮”形容声音大，与声音是否清楚无反义关系。", "温柔": "“温柔”形容性格或语气，与“不明”无反义关系。", "迅速": "“迅速”形容速度，与声音清楚与否无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不明是不清楚，不知道是什么。", "primary_collocate": null, "pronunciation": "bù míng", "ipa": "pu˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "天上出现了一个来历不明的东西。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱的来源不明，警察在查。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边发现了一个来历不明的箱子。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有一个身份不明的人跟着她。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他得了一种原因不明的病。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里漂来一个不明物体。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事真相不明，大家别乱说。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收到了一封发信人不明的信。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口停着一辆车主不明的车。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里传来不明的声音，孩子很害怕。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不明飞行物", "label": "复合"}, {"form": "来历不明", "label": "复合"}], "register": "书面语", "sense_fingerprint": "来历、身份等不清楚，不知道是什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不明", "is_correct": true, "explanation": "正确答案：不明 bù míng，意思是不清楚、不知道是什么。"}, {"text": "不平", "is_correct": false, "explanation": "bù píng 与 bù míng 声母不同（p 与 m），意思是不公平。"}, {"text": "不停", "is_correct": false, "explanation": "tíng 与 míng 声母不同（t 与 m），意思是不停止。"}, {"text": "不行", "is_correct": false, "explanation": "xíng 与 míng 声母不同（x 与 m），意思是不可以。"}, {"text": "不灵", "is_correct": false, "explanation": "líng 与 míng 声母不同（l 与 m），意思是没有效果。"}], "explanations": {"不明": "正确答案：不明 bù míng，意思是不清楚、不知道是什么。", "不平": "bù píng 与 bù míng 声母不同（p 与 m），意思是不公平。", "不停": "tíng 与 míng 声母不同（t 与 m），意思是不停止。", "不行": "xíng 与 míng 声母不同（x 与 m），意思是不可以。", "不灵": "líng 与 míng 声母不同（l 与 m），意思是没有效果。"}, "sentence_index": null, "correct_answer": "不明"}, "level_3": {"options": [{"text": "不明", "is_correct": true, "explanation": "“来历不明”表示不知道是从哪里来的，句子通顺。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“来历”不说可爱，句子不通。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”说价格，不能形容来历。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说卫生，与来历无关。"}], "explanations": {"不明": "“来历不明”表示不知道是从哪里来的，句子通顺。", "可爱": "搭配：“来历”不说可爱，句子不通。", "便宜": "语义：“便宜”说价格，不能形容来历。", "干净": "语义：“干净”说卫生，与来历无关。"}, "sentence_index": 0, "correct_answer": "不明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对老师的解释很不明，只好又问了一遍。", "explanation": "这里应该用〈不明白〉。“不明”说事情本身不清楚；人听不懂某个解释，要用“不明白”。"}, {"text": "这次期末考试的成绩很不明，老师已经都公布了。", "explanation": "这里“不明”被误用为〈不明确〉的意思。“不明”只用于来历、原因、下落等不知道的事；成绩已经公布，结果是确定的，不能说不明。"}, {"text": "这条路我天天走，它的路线很不明。", "explanation": "这里应该用〈复杂〉。“不明”说来历、原因、下落等不知道；路线绕来绕去要说〈复杂〉，而句中“天天走”说明路线是熟悉的，不能说不明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不明", "is_correct": true, "explanation": "“不明”说真相不清楚，与“大家别乱说”的语境相符。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，不能形容真相，句子不通。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“真相”不说高，不能说真相高。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味觉，与“真相”无关，句子不通。"}], "explanations": {"不明": "“不明”说真相不清楚，与“大家别乱说”的语境相符。", "圆": "语义：“圆”形容形状，不能形容真相，句子不通。", "高": "搭配：“真相”不说高，不能说真相高。", "甜": "语义：“甜”是味觉，与“真相”无关，句子不通。"}, "sentence_index": 6, "correct_answer": "不明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的变化很不明，要仔细看才行。", "explanation": "这里应该用〈不明显〉。“不明”说来历、原因不清楚；变化的清晰程度要用〈不明显〉。"}, {"text": "他的心情很不明，我一看就知道他很高兴。", "explanation": "这里应该用〈难以捉摸〉。“不明”说来历、原因等不知道；心情让人猜不透要说〈难以捉摸〉，而句中“一看就知道”说明心情是清楚的，不能用不明。"}, {"text": "我的名字写得很不明，老师每次都叫对了。", "explanation": "这里应该用〈模糊〉。“不明”说来历、原因不清楚；字迹看不清要说〈模糊〉，名字是确定的，不能说不明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个寄件人不明地包裹，我们不敢开。", "corrected_sentence": "这是一个寄件人不明的包裹，我们不敢开。", "error_description": "错误：“不明”修饰名词“包裹”，中间要用“的”，不能用“地”；“地”用于修饰动词。应说“寄件人不明的包裹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口站着一个身份不明地男人，没人认识他。", "corrected_sentence": "门口站着一个身份不明的男人，没人认识他。", "error_description": "“不明”修饰名词“男人”，中间要用“的”，不能用“地”；“地”用于修饰动词。应说“身份不明的男人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清楚", "is_correct": true, "explanation": "“清楚”与“不明”为反义，指去向清楚、已知。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人态度，与“去向”无关，不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或状态，与去向是否清楚无反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“去向不明”没有反义关系。"}], "correct_answer": "清楚", "explanations": {"清楚": "“清楚”与“不明”为反义，指去向清楚、已知。", "热情": "“热情”形容待人态度，与“去向”无关，不构成反义。", "轻松": "“轻松”形容心情或状态，与去向是否清楚无反义关系。", "聪明": "“聪明”形容智力，与“去向不明”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明确", "is_correct": true, "explanation": "“明确”与“不明”为反义，指去向清楚、已确定。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面，与去向是否清楚无关，不构成反义。"}, {"text": "大方", "is_correct": false, "explanation": "“大方”形容态度或举止，与“不明”没有反义关系。"}, {"text": "聪慧", "is_correct": false, "explanation": "“聪慧”形容人的智力，与去向不明无反义关系。"}], "correct_answer": "明确", "explanations": {"明确": "“明确”与“不明”为反义，指去向清楚、已确定。", "热闹": "“热闹”形容场面，与去向是否清楚无关，不构成反义。", "大方": "“大方”形容态度或举止，与“不明”没有反义关系。", "聪慧": "“聪慧”形容人的智力，与去向不明无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不清楚，不明白。", "primary_collocate": null, "pronunciation": "bù míng", "ipa": "pu˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的下落不明，家人很着急。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话的意思不明，请再说一次。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来这儿的目的不明。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小狗走丢了，去向不明。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同上的价格不明，我不能签字。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事原因不明，老师还在了解。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身份不明，门口的人没让他进。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结果不明，我们还要再查。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的路线不明，我们走错了路。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去了哪里，至今不明。", "target_word": "不明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下落不明", "label": "复合"}, {"form": "原因不明", "label": "复合"}], "register": "书面语", "sense_fingerprint": "下落、原因、目的等不清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不明", "is_correct": true, "explanation": "正确答案：不明 bù míng，意思是不清楚、不知道。"}, {"text": "不平", "is_correct": false, "explanation": "bù píng 与 bù míng 声母不同（p 与 m），意思是不公平。"}, {"text": "不停", "is_correct": false, "explanation": "tíng 与 míng 声母不同（t 与 m），意思是不停止。"}, {"text": "不行", "is_correct": false, "explanation": "xíng 与 míng 声母不同（x 与 m），意思是不可以。"}, {"text": "不灵", "is_correct": false, "explanation": "líng 与 míng 声母不同（l 与 m），意思是没有效果。"}], "explanations": {"不明": "正确答案：不明 bù míng，意思是不清楚、不知道。", "不平": "bù píng 与 bù míng 声母不同（p 与 m），意思是不公平。", "不停": "tíng 与 míng 声母不同（t 与 m），意思是不停止。", "不行": "xíng 与 míng 声母不同（x 与 m），意思是不可以。", "不灵": "líng 与 míng 声母不同（l 与 m），意思是没有效果。"}, "sentence_index": null, "correct_answer": "不明"}, "level_3": {"options": [{"text": "不明", "is_correct": true, "explanation": "“不明”作谓语，说明“下落”不清楚，句子通顺。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与“下落”无关，句子不通。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”说空间，不能用来形容下落。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”不修饰“下落”，不说下落厚。"}], "explanations": {"不明": "“不明”作谓语，说明“下落”不清楚，句子通顺。", "清脆": "语义：“清脆”形容声音，与“下落”无关，句子不通。", "窄": "语义：“窄”说空间，不能用来形容下落。", "厚": "搭配：“厚”不修饰“下落”，不说下落厚。"}, "sentence_index": 0, "correct_answer": "不明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗面很不明，没有味道。", "explanation": "这里应该用〈淡〉。“不明”说情况不清楚，不能形容味道；味道淡要说〈淡〉。"}, {"text": "全班的成绩表已经贴出来了，成绩很不明。", "explanation": "这里“不明”被误用为〈不确定〉的意思。成绩已经贴出来，结果是确定的，不能说不明；“不明”只用于来历、下落等不知道的事。"}, {"text": "我家的电话号码很不明，每个人都记得。", "explanation": "这里应该用〈难记〉。“不明”说情况不清楚；号码难记要说〈难记〉，而“每个人都记得”说明号码是清楚的，不能用不明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不明", "is_correct": true, "explanation": "“不明”说身份不清楚，与“门口的人没让他进”相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味觉，不能形容身份，句子不通。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“身份”不说软，不能修饰身份。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，与身份无关，句子不通。"}], "explanations": {"不明": "“不明”说身份不清楚，与“门口的人没让他进”相符。", "甜": "语义：“甜”是味觉，不能形容身份，句子不通。", "软": "搭配：“身份”不说软，不能修饰身份。", "圆": "语义：“圆”形容形状，与身份无关，句子不通。"}, "sentence_index": 6, "correct_answer": "不明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间很不明，太吵了，我根本睡不着。", "explanation": "这里应该用〈吵闹〉。“不明”说情况不清楚，不能形容声音大；房间里声音很大要说〈吵闹〉。"}, {"text": "这道菜很不明，我们都吃不下去。", "explanation": "这里应该用〈难吃〉。“不明”说情况不清楚，不能形容味道；菜不好吃要说〈难吃〉。"}, {"text": "他的年龄很不明，老师一看就知道他十岁。", "explanation": "这里应该用〈难以判断〉。“不明”说来历、原因不清楚；年龄难以判断要说〈难以判断〉，而“一看就知道”说明年龄是清楚的，不能用不明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他留下了一份联系方式不明地纸条，我们联系不上他。", "corrected_sentence": "他留下了一份联系方式不明的纸条，我们联系不上他。", "error_description": "错误：“不明”修饰名词“纸条”，中间要用“的”，不能用“地”；“地”用于修饰动词。应说“联系方式不明的纸条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口站着一个身份不明地男人，没人认识他。", "corrected_sentence": "门口站着一个身份不明的男人，没人认识他。", "error_description": "“不明”修饰名词“男人”，中间要用“的”，不能用“地”。应说“身份不明的男人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不算是不能算在里面，或者不到那个样子。", "primary_collocate": null, "pronunciation": "bù suàn", "ipa": "pu˥˩ suan˥˩", "syllable_count": 2, "sentences": [{"text": "鲸不算鱼，它是哺乳动物。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们刚认识，还不算朋友。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这点钱不算贵，我可以买。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只会几句英语，不算会说英语。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天二十度，对冬天来说不算冷。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，我的字写得还不算太差。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的小毛病不算大问题。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这里住了三个月，不算新来的了。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人不算好人，他经常骗别人。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去那儿只要五分钟，不算远。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不能归入某一类，或不属于某种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不算", "is_correct": true, "explanation": "正确。“不算”表示不能归入某一类，这里说鲸不归入鱼类。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”是归入某一类，与后半句“它是哺乳动物”的判断相反。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”是把东西放在某个范围里，说“鲸包括鱼”与句子意思矛盾。"}, {"text": "比作", "is_correct": false, "explanation": "搭配：“比作”要用在打比方的句子里，不能直接用来判断鲸是不是鱼。"}], "explanations": {"不算": "正确。“不算”表示不能归入某一类，这里说鲸不归入鱼类。", "属于": "语义：“属于”是归入某一类，与后半句“它是哺乳动物”的判断相反。", "包括": "语义：“包括”是把东西放在某个范围里，说“鲸包括鱼”与句子意思矛盾。", "比作": "搭配：“比作”要用在打比方的句子里，不能直接用来判断鲸是不是鱼。"}, "sentence_index": 0, "correct_answer": "不算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课的时候请不算说话。", "explanation": "这里应该用〈不要〉。“不算”表示不归入或达不到，不能用来表示禁止。"}, {"text": "这件衣服不算那件高，我们换一件。", "explanation": "这里应该用〈不如〉。“不算”表示不归入某一类或不到某个样子，不用于比较高矮或好坏。"}, {"text": "明天不算会下雨，你不用带伞。", "explanation": "这里应该用〈不会〉。“不算”表示不归入或达不到，不能用来预测天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不算", "is_correct": true, "explanation": "正确。“不算”表示达不到大问题的程度，这里说小毛病不算大问题。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”接的是人的不满，不能说“抱怨大问题”。"}, {"text": "分析", "is_correct": false, "explanation": "语义：“分析”需要人来做，“小毛病分析大问题”主语不能发出这个动作，句子不通。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指否定已有的结论，与“小毛病”的轻微程度不符。"}], "explanations": {"不算": "正确。“不算”表示达不到大问题的程度，这里说小毛病不算大问题。", "抱怨": "搭配：“抱怨”接的是人的不满，不能说“抱怨大问题”。", "分析": "语义：“分析”需要人来做，“小毛病分析大问题”主语不能发出这个动作，句子不通。", "推翻": "语义：“推翻”指否定已有的结论，与“小毛病”的轻微程度不符。"}, "sentence_index": 6, "correct_answer": "不算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些钱不算买车，还差很多。", "explanation": "这里应该用〈不够〉。“不算”表示不归入或达不到，不能用来说钱够不够买车。"}, {"text": "这本书不算十块钱，买它太贵了。", "explanation": "这里应该用〈不值〉。“不算十块钱”说明价格低，与后句“太贵”相矛盾。"}, {"text": "他很不算高兴，一直看着窗外。", "explanation": "这里应该用〈不太〉。“不算”前不能加程度副词“很”，“很不算”不通，应说“不太高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们还不不算熟，只见过两次。", "corrected_sentence": "我们还不算熟，只见过两次。", "error_description": "多加了一个“不”：“不不算熟”重复否定，不通，应说“不算熟”，表示还达不到“熟”的程度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩不算了差，但是进步很快。", "corrected_sentence": "他的成绩不算差，但是进步很快。", "error_description": "多加了“了”：“不算”是否定形式，中间不能插入“了”，应说“不算差”，表示成绩还不到差的程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
