INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94456, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不能计入；够不上某种程度。", "primary_collocate": null, "pronunciation": "bù suàn", "ipa": "pu˥˩ suan˥˩", "syllable_count": 2, "sentences": [{"text": "迟到一两分钟不算迟到。", "target_word": "不算", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试没写名字，成绩不算。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只来了一次，不算老顾客。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百块钱对他来说不算多。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一次投篮没进，这个球不算。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点小事不算什么，别放在心上。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语不算好，但是够用了。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了截止时间，交的作业不算分。", "target_word": "不算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是看了一眼，不算真正读过这本书。", "target_word": "不算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间屋子才十平米，不算大。", "target_word": "不算", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不计入数；达不到某种程度，算不上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不算", "is_correct": true, "explanation": "正确。“不算”表示不能计入，“一两分钟”这么少，不能算迟到。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“迟到一两分钟喜欢迟到”主语和动词不搭配，句意不通。"}, {"text": "扣", "is_correct": false, "explanation": "搭配：“扣”接的是分数、工资之类，不能说“扣迟到”。"}, {"text": "追究", "is_correct": false, "explanation": "语义：“追究”指深究责任，与“一两分钟”的轻微程度相冲突。"}], "explanations": {"不算": "正确。“不算”表示不能计入，“一两分钟”这么少，不能算迟到。", "喜欢": "语义：“迟到一两分钟喜欢迟到”主语和动词不搭配，句意不通。", "扣": "搭配：“扣”接的是分数、工资之类，不能说“扣迟到”。", "追究": "语义：“追究”指深究责任，与“一两分钟”的轻微程度相冲突。"}, "sentence_index": 0, "correct_answer": "不算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑不算那台的好，我们买那台吧。", "explanation": "这里应该用〈不如〉。“不算”表示不计入或够不上某种程度，不能拿两样东西比较优劣。"}, {"text": "这件衣服不算那件便宜，我们别买了。", "explanation": "这里应该用〈不如〉。“不算”不用于比较两件东西的价格高低，比较时要用“不如”。"}, {"text": "他想去医院，却不算去成了。", "explanation": "这里应该用〈没能〉。“不算”表示不计入或达不到，不能表示因为某种原因而没有做成某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不算", "is_correct": true, "explanation": "正确。“不算”表示达不到某种程度，“够用”说明汉语不是很好，但还能用。"}, {"text": "考虑", "is_correct": false, "explanation": "搭配：“考虑”后面接的是问题或想法，不能说“汉语考虑好”。"}, {"text": "夸", "is_correct": false, "explanation": "搭配：“夸”是称赞别人，不能直接接“汉语好”这样的结果。"}, {"text": "挑", "is_correct": false, "explanation": "搭配：“挑”接的是东西或毛病，不能说“汉语挑好”。"}], "explanations": {"不算": "正确。“不算”表示达不到某种程度，“够用”说明汉语不是很好，但还能用。", "考虑": "搭配：“考虑”后面接的是问题或想法，不能说“汉语考虑好”。", "夸": "搭配：“夸”是称赞别人，不能直接接“汉语好”这样的结果。", "挑": "搭配：“挑”接的是东西或毛病，不能说“汉语挑好”。"}, "sentence_index": 6, "correct_answer": "不算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请不算在这里停车，谢谢。", "explanation": "这里应该用〈不要〉。“不算”表示不归入或达不到，不能用来表示禁止。"}, {"text": "这首歌不算了好听，但是我还是喜欢。", "explanation": "这里应该用〈不太〉。“不算”后面不能插入“了”，应说“不太好听”或“不算好听”。"}, {"text": "这间屋子不算十平米，大得很。", "explanation": "这里应该用〈有〉。“不算十平米”表示不到十平米，与“大得很”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛只跑了一半，不算了完赛。", "corrected_sentence": "这次比赛只跑了一半，不算完赛。", "error_description": "「不算」后面直接接宾语「完赛」，中间不能插入「了」，应去掉「了」，写作「不算完赛」，表示没有达到完赛的标准，不计入成绩。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的口语很不算流利，但是够用了。", "corrected_sentence": "他的口语不算流利，但是够用了。", "error_description": "「不算」前不能加程度副词「很」，应去掉「很」，写作「不算流利」，表示达不到流利的程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
