INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时候；某个时间点或阶段。", "primary_collocate": null, "pronunciation": "zhī jì", "ipa": "ʈʂɻ̩˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "新年之际，祝大家身体健康。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业之际，同学们互相写了留言。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节之际，很多人坐火车回家。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国庆之际，大街上挂满了红旗。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在公司成立十周年之际，老板发了礼物。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离开家乡之际，他回头看了一眼。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在春天来临之际，公园里开满了花。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开学之际，商店里的书包卖得很快。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束之际，大家都站了起来。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在新旧年交替之际，城市里放起了烟花。", "target_word": "之际", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "之际：用在时间词后，指某个时间点或阶段（新年之际）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af238286-c549-4cf8-8736-86ca312c2e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之际", "is_correct": true, "explanation": "正确：之际 zhījì（第一、第四声）指某个时间点或阶段，如“新年之际”。"}, {"text": "知己", "is_correct": false, "explanation": "zhījǐ（第三声）与 zhījì（第四声）第二个音节声调不同，意思是知心的朋友。"}, {"text": "制剂", "is_correct": false, "explanation": "制剂 zhìjì（第四声、第四声）与 zhījì 仅第一个音节声调不同，意思是按配方制成的药品。"}, {"text": "织机", "is_correct": false, "explanation": "织机 zhījī（第一声、第一声）与 zhījì 仅第二个音节声调不同，意思是纺织用的机器。"}], "explanations": {"之际": "正确：之际 zhījì（第一、第四声）指某个时间点或阶段，如“新年之际”。", "知己": "zhījǐ（第三声）与 zhījì（第四声）第二个音节声调不同，意思是知心的朋友。", "制剂": "制剂 zhìjì（第四声、第四声）与 zhījì 仅第一个音节声调不同，意思是按配方制成的药品。", "织机": "织机 zhījī（第一声、第一声）与 zhījì 仅第二个音节声调不同，意思是纺织用的机器。"}, "sentence_index": null, "correct_answer": "之际"}, "level_3": {"options": [{"text": "之地", "is_correct": false, "explanation": "语义：“之地”指地点，与“新年”这个时间不合。"}, {"text": "之际", "is_correct": true, "explanation": "正确：“之际”指某个时间点或阶段，与“新年”搭配自然。"}, {"text": "之下", "is_correct": false, "explanation": "语义：“之下”表示在…底下，与“新年”这个时间不合。"}, {"text": "之处", "is_correct": false, "explanation": "语义：“之处”指地点或部分，不表示时间点，与“新年”不合。"}], "explanations": {"之地": "语义：“之地”指地点，与“新年”这个时间不合。", "之际": "正确：“之际”指某个时间点或阶段，与“新年”搭配自然。", "之下": "语义：“之下”表示在…底下，与“新年”这个时间不合。", "之处": "语义：“之处”指地点或部分，不表示时间点，与“新年”不合。"}, "sentence_index": 0, "correct_answer": "之际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一周之际，他读完了这本书。", "explanation": "这里应该用〈之内〉。“之际”指时间点或阶段，不能表示一段时间的范围。"}, {"text": "他明天之际去北京出差。", "explanation": "这里应该用〈那天〉。“之际”指某件大事或特定时刻，不能用于一个普通的日子。"}, {"text": "教室之际，大家都安静下来。", "explanation": "“之际”只用于时间，不用于地点，不能指教室这样的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之际", "is_correct": true, "explanation": "正确：之际 zhījì（第一、第四声）指某个时间点或阶段，如“春天来临之际”。"}, {"text": "智计", "is_correct": false, "explanation": "智计 zhìjì（第四声、第四声）与 zhījì 仅第一个音节声调不同，意思是智谋计策。"}, {"text": "直击", "is_correct": false, "explanation": "直击 zhíjī（第二声、第一声）与 zhījì 声母韵母相同，声调不同，意思是直接打击或亲眼看到。"}, {"text": "职级", "is_correct": false, "explanation": "职级 zhíjí（第二声、第二声）与 zhījì 声母韵母相同，声调不同，意思是职务的等级。"}], "explanations": {"之际": "正确：之际 zhījì（第一、第四声）指某个时间点或阶段，如“春天来临之际”。", "智计": "智计 zhìjì（第四声、第四声）与 zhījì 仅第一个音节声调不同，意思是智谋计策。", "直击": "直击 zhíjī（第二声、第一声）与 zhījì 声母韵母相同，声调不同，意思是直接打击或亲眼看到。", "职级": "职级 zhíjí（第二声、第二声）与 zhījì 声母韵母相同，声调不同，意思是职务的等级。"}, "sentence_index": null, "correct_answer": "之际"}, "level_3": {"options": [{"text": "之中", "is_correct": false, "explanation": "语义：“之中”表示在某个范围之内，不表示时间点，与“春天来临”不合。"}, {"text": "之际", "is_correct": true, "explanation": "正确：“之际”指某个时间点，与“春天来临”搭配自然。"}, {"text": "之外", "is_correct": false, "explanation": "搭配：“之外”表示范围以外，不接“春天来临”这样的时间事件。"}, {"text": "之间", "is_correct": false, "explanation": "配价：“之间”要求两方或多方，“春天来临之间”缺少对象。"}], "explanations": {"之中": "语义：“之中”表示在某个范围之内，不表示时间点，与“春天来临”不合。", "之际": "正确：“之际”指某个时间点，与“春天来临”搭配自然。", "之外": "搭配：“之外”表示范围以外，不接“春天来临”这样的时间事件。", "之间": "配价：“之间”要求两方或多方，“春天来临之间”缺少对象。"}, "sentence_index": 6, "correct_answer": "之际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子之际，放着一本书。", "explanation": "这里应该用〈之上〉。“之际”指时间点，不能表示物体的位置。"}, {"text": "他跟朋友之际很快乐。", "explanation": "这里应该用〈交往〉。“之际”只表示时间，不能用来描述与人交往的过程。"}, {"text": "这个包之际装着三本书。", "explanation": "这里应该用〈之中〉。“之际”是时间意义，不指物体内部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "假期的之际，我们一家去了海边。", "corrected_sentence": "假期之际，我们一家去了海边。", "error_description": "“之际”前面不能加“的”，应直接说“假期之际”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放假之际的，学校门口很热闹。", "corrected_sentence": "放假之际，学校门口很热闹。", "error_description": "“之际”后面不能加“的”，它不是名词修饰语，应直接接逗号。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天上", "is_correct": true, "explanation": "天上：指天空或神仙居住的上界，与“人间”构成对立，是这一义项的反义词。"}, {"text": "书桌", "is_correct": false, "explanation": "与“人间”无反义关系，是家具名词，与这一义项不对立。"}, {"text": "河流", "is_correct": false, "explanation": "与“人间”无反义关系，是自然地理名词，不与“人间”的世界义相对。"}, {"text": "草地", "is_correct": false, "explanation": "与“人间”无反义关系，是地面的一种景物，不构成对立。"}], "correct_answer": "天上", "explanations": {"天上": "天上：指天空或神仙居住的上界，与“人间”构成对立，是这一义项的反义词。", "书桌": "与“人间”无反义关系，是家具名词，与这一义项不对立。", "河流": "与“人间”无反义关系，是自然地理名词，不与“人间”的世界义相对。", "草地": "与“人间”无反义关系，是地面的一种景物，不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天上", "is_correct": true, "explanation": "天上：指天空或神仙居住的上界，与“人间”构成对立，是这一义项的反义词。"}, {"text": "教室", "is_correct": false, "explanation": "与“人间”无反义关系，是学校的场所，与这一义项不对立。"}, {"text": "花园", "is_correct": false, "explanation": "与“人间”无反义关系，是种植花草的场所，不构成对立。"}, {"text": "火车", "is_correct": false, "explanation": "与“人间”无反义关系，是交通工具，与这一义项不对立。"}], "correct_answer": "天上", "explanations": {"天上": "天上：指天空或神仙居住的上界，与“人间”构成对立，是这一义项的反义词。", "教室": "与“人间”无反义关系，是学校的场所，与这一义项不对立。", "花园": "与“人间”无反义关系，是种植花草的场所，不构成对立。", "火车": "与“人间”无反义关系，是交通工具，与这一义项不对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人间是人们生活的这个世界。", "primary_collocate": null, "pronunciation": "rén jiān", "ipa": "ʐən˧˥ tɕjɛn˥˥", "syllable_count": 2, "sentences": [{"text": "传说天上的仙女来到了人间。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神仙看着人间的春天，也很羡慕。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，月亮离人间太远了。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的龙王从海里回到了人间。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小仙女第一次来人间，什么都觉得新鲜。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳每天照着人间，给大家带来光。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里，天上一天，人间一年。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙女从天上往下看，人间到处是花。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，人死以后就离开人间了。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙悟空大闹天宫以后，又去了人间。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人间天堂", "label": "复合"}], "register": "书面", "sense_fingerprint": "人间·rén jiān·人们生活的世界（相对天上）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：仙女不会“来到”冰箱这类家用电器，句意荒谬。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“来到了”要接地点或处所，不能接学科名“数学”。"}, {"text": "人间", "is_correct": true, "explanation": "人间：人们生活的世界，与天上相对，此句说仙女从天上来到人间。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不是仙女可以来到的地方。"}], "explanations": {"冰箱": "语义：仙女不会“来到”冰箱这类家用电器，句意荒谬。", "数学": "搭配：“来到了”要接地点或处所，不能接学科名“数学”。", "人间": "人间：人们生活的世界，与天上相对，此句说仙女从天上来到人间。", "字典": "语义：字典是工具书，不是仙女可以来到的地方。"}, "sentence_index": 0, "correct_answer": "人间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小仙女从一位人间飞下来，落在我们的村子里。", "explanation": "量词用错：这里不应用〈位〉。“位”用于人，“人间”指世界，不能用“一位”计量。"}, {"text": "那个人间很爱笑，大家都喜欢他。", "explanation": "这里应该用〈人〉。“人间”是抽象的世界概念，不指人，不能用“那个”指代一个人。"}, {"text": "小鸟用人间筑了一个巢。", "explanation": "这里应该用〈树枝〉。“人间”指人们生活的世界，不是可以用来筑巢的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是学习用品，不能与“天上一天、人间一年”构成时间对比，句意荒谬。"}, {"text": "人间", "is_correct": true, "explanation": "人间：与天上相对的人们生活的世界，神话中两界时间流速不同。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能与“天上一天”形成时间上的对比。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“天上一天，……一年”要求对比的对象是与天上相对的世界，“地铁”不能与之搭配。"}], "explanations": {"书包": "语义：书包是学习用品，不能与“天上一天、人间一年”构成时间对比，句意荒谬。", "人间": "人间：与天上相对的人们生活的世界，神话中两界时间流速不同。", "花瓶": "语义：花瓶是器物，不能与“天上一天”形成时间上的对比。", "地铁": "搭配：“天上一天，……一年”要求对比的对象是与天上相对的世界，“地铁”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "人间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宇航员在人间漂浮，很有趣。", "explanation": "这里应该用〈太空〉。“人间”指人们生活的世界，不指宇宙空间，宇航员漂浮的环境不能说人间。"}, {"text": "他们给人间浇了水，让它长得更大。", "explanation": "这里应该用〈树〉。“人间”指人们生活的世界，不是可以浇水的植物。"}, {"text": "飞机的人间很快，一小时就到了。", "explanation": "这里应该用〈速度〉。“人间”是世界概念，不能用来描述飞机的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多仙女都人间生活过。", "corrected_sentence": "很多仙女都在人间生活过。", "error_description": "错误形式：都人间生活过；正确形式：都在人间生活过。“生活”作不及物动词，表示处所要用介词“在”引出“人间”，不能直接接处所名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天来了，人间里的果子都熟了。", "corrected_sentence": "秋天来了，人间的果子都熟了。", "error_description": "错误形式：人间里；正确形式：人间。“人间”本身是处所名词，后面不再加方位词“里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
