INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类社会；世间。", "primary_collocate": null, "pronunciation": "rén jiān", "ipa": "ʐən˧˥ tɕjɛn˥˥", "syllable_count": 2, "sentences": [{"text": "母亲的爱是人间最温暖的感情。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生用爱心给人间带来了温暖。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在为人间的和平努力。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人间有苦也有甜，我们要好好生活。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌写的是人间的真情。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人间的事，没有一件是容易的。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了很多人间的故事。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得朋友之间的帮助是人间最美好的东西。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们看过人间的痛苦，所以更懂得感谢。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诗人写了许多关于人间的诗。", "target_word": "人间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人间天堂", "label": "复合"}], "register": "书面", "sense_fingerprint": "人间·rén jiān·人类社会、世间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是具体的场所，不能作为“最温暖的感情”的范围，句意不通。"}, {"text": "人间", "is_correct": true, "explanation": "人间：指人类社会、世间，此处说母亲的爱是世间最温暖的感情。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空指自然界的天空，与“母亲的爱”所指的人类情感无关。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：“最温暖的感情”要指向人与人之间的情感，“夏天”这类时令词不能充当它的范围。"}], "explanations": {"厨房": "语义：厨房是具体的场所，不能作为“最温暖的感情”的范围，句意不通。", "人间": "人间：指人类社会、世间，此处说母亲的爱是世间最温暖的感情。", "天空": "语义：天空指自然界的天空，与“母亲的爱”所指的人类情感无关。", "夏天": "搭配：“最温暖的感情”要指向人与人之间的情感，“夏天”这类时令词不能充当它的范围。"}, "sentence_index": 0, "correct_answer": "人间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把人间放进了包里，带去了学校。", "explanation": "这里应该用〈书〉。“人间”是抽象概念，不能放进包里带走。"}, {"text": "车站里的人间很多，我们挤了很久才出去。", "explanation": "这里应该用〈人群〉。“人间”是抽象概念，不指一群具体的人，不能被“很多”修饰。"}, {"text": "这块人间很硬，敲起来有声音。", "explanation": "量词用错：这里不应用〈块〉。“块”多用于有形的物体，“人间”是抽象名词，不能与“块”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温差", "is_correct": false, "explanation": "语义：温差指温度的高低差异，不能作为书中讲述的故事内容，句意荒谬。"}, {"text": "人间", "is_correct": true, "explanation": "人间：指人类社会、世间，此处指书中讲述的人间故事。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指光的强弱，不能作为书中讲述的故事内容，句意荒谬。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：厚度指物体的厚薄，不能作为书中讲述的故事内容，句意荒谬。"}], "explanations": {"温差": "语义：温差指温度的高低差异，不能作为书中讲述的故事内容，句意荒谬。", "人间": "人间：指人类社会、世间，此处指书中讲述的人间故事。", "亮度": "语义：亮度指光的强弱，不能作为书中讲述的故事内容，句意荒谬。", "厚度": "语义：厚度指物体的厚薄，不能作为书中讲述的故事内容，句意荒谬。"}, "sentence_index": 6, "correct_answer": "人间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座人间很大，我们走了一天也没有走完。", "explanation": "量词用错：这里不应用〈座〉。“座”多用于山、楼等大型具体物体，“人间”是抽象名词，不与“座”搭配。"}, {"text": "他人间了一个小时，才等到车。", "explanation": "这里应该用〈等〉。“人间”是名词，不能作动词，也不表示等待。"}, {"text": "这顿饭的人间很好吃，大家都吃光了。", "explanation": "这里应该用〈味道〉。“人间”指世间或人类社会，不能用来评价食物的好吃与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在人间里生活了很多年。", "corrected_sentence": "他在人间生活了很多年。", "error_description": "错误形式：人间里；正确形式：人间。“人间”本身是处所名词，后面不再加方位词“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影讲的是人间们的冷暖。", "corrected_sentence": "这部电影讲的是人间的冷暖。", "error_description": "错误形式：人间们；正确形式：人间。“人间”指世间，不是指人的名词，后面不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
