INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "十进制数中最右边的一位。", "primary_collocate": null, "pronunciation": "gè wèi", "ipa": "kɤ˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "十进制数的个位只能是零到九。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "五十八的个位是八，不是五。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在十进制里，个位满十就要进到十位。", "target_word": "个位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算加法时，要先从个位开始算。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个数的个位都是三。", "target_word": "个位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "个位是二、四、六、八或零的数是双数。", "target_word": "个位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十九加一以后，个位变成了零。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "个位旁边的那一位叫十位。", "target_word": "个位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把个位上的八看成了三。", "target_word": "个位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算出结果后，我要检查个位有没有写错。", "target_word": "个位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个位数", "label": "复合"}, {"form": "個位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "十进制数中最右边的一位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个位", "is_correct": true, "explanation": "个位是十进制数最右边的一位，只能是零到九，符合句意。"}, {"text": "进位", "is_correct": false, "explanation": "语义：进位是运算时进到高位的动作，不是数位本身，不能只是零到九。"}, {"text": "次数", "is_correct": false, "explanation": "语义：次数指重复的回数，与数字的取值范围无关。"}, {"text": "偶数", "is_correct": false, "explanation": "语义：偶数是能被二整除的一类数，不是数位，不能说“十进制数的偶数只能是零到九”。"}], "explanations": {"个位": "个位是十进制数最右边的一位，只能是零到九，符合句意。", "进位": "语义：进位是运算时进到高位的动作，不是数位本身，不能只是零到九。", "次数": "语义：次数指重复的回数，与数字的取值范围无关。", "偶数": "语义：偶数是能被二整除的一类数，不是数位，不能说“十进制数的偶数只能是零到九”。"}, "sentence_index": 0, "correct_answer": "个位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个位在这家公司很高。", "explanation": "这里应该用〈地位〉。个位指数字的位置，身份高低要用“地位”。"}, {"text": "个位朋友，欢迎你们来到这里。", "explanation": "这里应该用〈各位〉。个位指数字的位置，称呼众人要用“各位”，二者同音却不能混用。"}, {"text": "这件事应该由个位负责。", "explanation": "这里应该用〈个人〉。个位指数字的位置，指由单独的人负责要用“个人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个位", "is_correct": true, "explanation": "十九加一以后，个位从九变成了零，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是数字，不可能变成零。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是数位，不能变成零。"}, {"text": "进位", "is_correct": false, "explanation": "搭配：进位是进到高位的动作，不能说“进位变成了零”。"}], "explanations": {"个位": "十九加一以后，个位从九变成了零，符合句意。", "颜色": "语义：颜色不是数字，不可能变成零。", "时间": "语义：时间不是数位，不能变成零。", "进位": "搭配：进位是进到高位的动作，不能说“进位变成了零”。"}, "sentence_index": 6, "correct_answer": "个位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个会场的个位都坐满了。", "explanation": "这里应该用〈座位〉。个位指数字的位置，指可以坐的位子要用“座位”。"}, {"text": "他在个位上睡着了。", "explanation": "这里应该用〈床〉。个位指数字的位置，不是可以躺下睡觉的地方，睡觉要用“床”。"}, {"text": "个位同学请先检查计算过程。", "explanation": "这里应该用〈各位〉。个位指数字的位置，称呼大家要用“各位”，二者同音却不能混用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做减法的时候，我们也要先个位减起。", "corrected_sentence": "做减法的时候，我们也要先从个位减起。", "error_description": "错误形式：“先个位减起”；正确形式：“先从个位减起”。表示从哪一位开始算，“个位”前要加介词“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我检查了个位上地数字。", "corrected_sentence": "我检查了个位上的数字。", "error_description": "错误形式：“个位上地数字”；正确形式：“个位上的数字”。修饰名词“数字”要用“的”，用“地”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分外", "is_correct": true, "explanation": "正确：「分外」指超出本分的，与「分内」相对。"}, {"text": "普通", "is_correct": false, "explanation": "「普通」指一般、不特别，与「分内」没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "「简单」指不复杂，与「分内」没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "「复杂」指头绪多、难理解，与「分内」没有反义关系。"}], "correct_answer": "分外", "explanations": {"分外": "正确：「分外」指超出本分的，与「分内」相对。", "普通": "「普通」指一般、不特别，与「分内」没有反义关系。", "简单": "「简单」指不复杂，与「分内」没有反义关系。", "复杂": "「复杂」指头绪多、难理解，与「分内」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
