INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本分以内的，应当做的。", "primary_collocate": null, "pronunciation": "fèn nèi", "ipa": "fən˥˩ nei˥˩", "syllable_count": 2, "sentences": [{"text": "照顾好病人是护士分内的工作。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些都是我分内的事，不用谢。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做好作业是学生分内的事。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只做分内的工作，从来不多管闲事。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫办公室是清洁工分内的责任。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助客人是服务员分内的事。", "target_word": "分内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，认真上课是你们分内的事。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把分内的工作做完，才下班回家。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护公园的花草是管理员分内的工作。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不是我分内的事，你去问经理吧。", "target_word": "分内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分内事", "label": "复合"}, {"form": "分内之事", "label": "复合"}], "register": "中性", "sense_fingerprint": "属于本分，应当做的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分内", "is_correct": true, "explanation": "正确：「分内」指属于本分、应当做的，照顾病人正是护士的本分。"}, {"text": "业余", "is_correct": false, "explanation": "语义：「业余」与「护士」的职业身份矛盾，照顾病人不是业余的工作。"}, {"text": "违法", "is_correct": false, "explanation": "语义：照顾病人是合法的职业工作，不能说违法的工作。"}, {"text": "圆形", "is_correct": false, "explanation": "搭配：「圆形」描述形状，不能修饰「工作」。"}], "explanations": {"分内": "正确：「分内」指属于本分、应当做的，照顾病人正是护士的本分。", "业余": "语义：「业余」与「护士」的职业身份矛盾，照顾病人不是业余的工作。", "违法": "语义：照顾病人是合法的职业工作，不能说违法的工作。", "圆形": "搭配：「圆形」描述形状，不能修饰「工作」。"}, "sentence_index": 0, "correct_answer": "分内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为人很分内，从不说谎。", "explanation": "这里应该用〈老实〉。分内只说事情或职责是否属于本分，不用来形容人的品性。"}, {"text": "这首歌很分内，听了很舒服。", "explanation": "这里应该用〈动听〉。分内只修饰事情，不用来形容歌曲的好听程度。"}, {"text": "他是个分内的人。", "explanation": "这里应该用〈本分〉。本分可以修饰人，分内只修饰事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分内", "is_correct": true, "explanation": "正确：「分内」指属于本分、应当做的，认真上课正是学生的本分。"}, {"text": "无关", "is_correct": false, "explanation": "语义：「无关」与「认真上课是你们的事」相矛盾。"}, {"text": "蓝色", "is_correct": false, "explanation": "搭配：「蓝色」是颜色，不能修饰「事」。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：上课是学生熟悉的事，用「陌生」与句意不符。"}], "explanations": {"分内": "正确：「分内」指属于本分、应当做的，认真上课正是学生的本分。", "无关": "语义：「无关」与「认真上课是你们的事」相矛盾。", "蓝色": "搭配：「蓝色」是颜色，不能修饰「事」。", "陌生": "语义：上课是学生熟悉的事，用「陌生」与句意不符。"}, "sentence_index": 6, "correct_answer": "分内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对客人很分内，主动帮忙。", "explanation": "这里应该用〈热情〉。分内只修饰事情，待人的态度要用热情。"}, {"text": "这把椅子很分内，坐着很舒服。", "explanation": "这里应该用〈舒适〉。分内只修饰事情，不用来形容物品，坐着的感受要用舒适。"}, {"text": "他做事分内，每件事都做好。", "explanation": "这里应该用〈认真〉。分内不用来形容一个人做事的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些工作都是我分内了的，别担心。", "corrected_sentence": "这些工作都是我分内的，别担心。", "error_description": "「分内」修饰名词时只用「的」，不能加「了」，应说「分内的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她完成了很分内的任务，就回家了。", "corrected_sentence": "她完成了分内的任务，就回家了。", "error_description": "「分内」作定语前不能加「很」，应说「分内的任务」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
