INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "制服是同一个学校或单位的人穿的一样的衣服。", "primary_collocate": null, "pronunciation": "zhì fú", "ipa": "ʈʂɻ̩⁵¹ fu³⁵", "syllable_count": 2, "sentences": [{"text": "我们学校的制服是蓝色的。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着新制服去上班。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个服务员都要穿制服。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿今天忘了带制服。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套制服太小了，我不能穿。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把制服洗干净了。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的制服上有学校的名字。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察穿着制服站在门口。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们公司的制服是什么颜色？", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上学的时候，我们每天都穿制服。", "target_word": "制服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套制服", "label": "量词"}, {"form": "一身制服", "label": "量词"}], "register": "中性", "sense_fingerprint": "同一学校或单位的人穿的相同衣服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制服", "is_correct": true, "explanation": "正确答案。制服是同一学校或单位的人穿的一样的衣服。"}, {"text": "致富", "is_correct": false, "explanation": "zhì fù 与 zhì fú 只有末字声调不同（fù 第四声，fú 第二声），“致富”意思是使自己变得富有。"}, {"text": "字符", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），“字符”意思是文字、数字等符号。"}, {"text": "支付", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，fù（第四声）与 fú（第二声）声调也不同，“支付”意思是付钱。"}], "explanations": {"制服": "正确答案。制服是同一学校或单位的人穿的一样的衣服。", "致富": "zhì fù 与 zhì fú 只有末字声调不同（fù 第四声，fú 第二声），“致富”意思是使自己变得富有。", "字符": "zì 与 zhì 声母不同（z 与 zh），“字符”意思是文字、数字等符号。", "支付": "zhī（第一声）与 zhì（第四声）声调不同，fù（第四声）与 fú（第二声）声调也不同，“支付”意思是付钱。"}, "sentence_index": null, "correct_answer": "制服"}, "level_3": {"options": [{"text": "制服", "is_correct": true, "explanation": "正确答案。“制服”指学校统一规定的服装，可以是蓝色的。"}, {"text": "校长", "is_correct": false, "explanation": "语义：校长是人，不能说“是蓝色的”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是有颜色的东西，不能说“是蓝色的”。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“蓝色的”一般不修饰“成绩”，这样说不符合搭配习惯。"}], "explanations": {"制服": "正确答案。“制服”指学校统一规定的服装，可以是蓝色的。", "校长": "语义：校长是人，不能说“是蓝色的”。", "考试": "语义：考试不是有颜色的东西，不能说“是蓝色的”。", "成绩": "搭配：“蓝色的”一般不修饰“成绩”，这样说不符合搭配习惯。"}, "sentence_index": 0, "correct_answer": "制服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次去爬山，我特意买了一套制服。", "explanation": "这里应该用〈登山服〉。制服是统一规定式样的服装，爬山要穿登山服，不用“制服”。"}, {"text": "下大雨了，他穿上制服，身上一点也没湿。", "explanation": "这里应该用〈雨衣〉。制服是学校或单位统一的衣服，不能挡雨；下雨时穿的是雨衣。"}, {"text": "他周末去打篮球，特意穿了一套制服。", "explanation": "这里应该用〈运动服〉。打篮球要穿运动服，制服是统一规定式样的服装，不用于运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制服", "is_correct": true, "explanation": "正确答案。“制服”是统一式样的服装，可以写上学校的名字。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，不能在上面写学校的名字。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气上”不是可以写字的表面，“天气”与“上有……名字”不搭配。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是可以写字的物体，不能说“数学上有学校的名字”。"}], "explanations": {"制服": "正确答案。“制服”是统一式样的服装，可以写上学校的名字。", "声音": "语义：声音看不见，不能在上面写学校的名字。", "天气": "搭配：“天气上”不是可以写字的表面，“天气”与“上有……名字”不搭配。", "数学": "语义：数学是一门学科，不是可以写字的物体，不能说“数学上有学校的名字”。"}, "sentence_index": 6, "correct_answer": "制服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都穿着制服睡觉。", "explanation": "这里应该用〈睡衣〉。制服是统一规定式样的服装，睡觉时穿的衣服不用“制服”。"}, {"text": "他周末去跳舞，一直穿着制服。", "explanation": "这里应该用〈舞衣〉。跳舞要穿舞衣，制服是统一规定式样的服装，不用于跳舞。"}, {"text": "夏天我们去海边都穿着制服游泳。", "explanation": "这里应该用〈泳衣〉。游泳要穿泳衣，不能穿制服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他戴着一套制服去开会。", "corrected_sentence": "他穿着一套制服去开会。", "error_description": "动词搭配错误：穿制服应说“穿”，“戴”用于帽子、眼镜等，不能说“戴制服”。应改为“他穿着一套制服去开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天上班都穿着一把制服。", "corrected_sentence": "他每天上班都穿着一套制服。", "error_description": "量词错误：“制服”要用“套”或“身”，不能用“把”（“把”用于有柄的东西等）。应改为“一套制服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
