INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94469, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "受看是看起来很舒服，很好看。", "primary_collocate": null, "pronunciation": "shòu kàn", "ipa": "ʂoʊ˥˩ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他的脸不算帅，可是越看越受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的样子很受看，我买了两个。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上摆了几朵白花，看着很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套家具不贵，但是挺受看的。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发梳得整整齐齐，显得很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新刷的墙是浅黄色，看上去很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍得很受看，我想发给家人。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶做的点心摆得很受看，大家都舍不得吃。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小房子白墙红瓦，十分受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得很大方，很受看。", "target_word": "受看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不受看", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "看起来舒服，很好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受看", "is_correct": true, "explanation": "正确：“越看越受看”指看得越久越觉得好看，与前文的转折相符。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地，不能用来形容脸的样子。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格，不能说“越看越贵”来形容脸。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与脸的样子无关。"}], "explanations": {"受看": "正确：“越看越受看”指看得越久越觉得好看，与前文的转折相符。", "硬": "语义：“硬”指质地，不能用来形容脸的样子。", "贵": "搭配：“贵”说价格，不能说“越看越贵”来形容脸。", "咸": "语义：“咸”指味道，与脸的样子无关。"}, "sentence_index": 0, "correct_answer": "受看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种新饮料在夏天很受看，很多人都在买。", "explanation": "这里应该用〈受欢迎〉。受看说样子好看，说饮料被大家喜爱、大家都在买要用受欢迎。"}, {"text": "这个部门在公司里很受看，领导经常过问它的工作。", "explanation": "这里应该用〈受重视〉。受看只形容外表，不能表示部门被领导重视。"}, {"text": "这家书店的服务很受看，读者都很满意。", "explanation": "这里应该用〈受好评〉。服务的质量好要说受好评，受看只形容样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受看", "is_correct": true, "explanation": "正确：“拍得很受看”指照片拍得好看，与“想发给家人”相符。"}, {"text": "难看", "is_correct": false, "explanation": "语义：“难看”与后面的“想发给家人”相矛盾。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”指味道，不能用来形容照片。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”说温度，不能用来说照片拍得怎样。"}], "explanations": {"受看": "正确：“拍得很受看”指照片拍得好看，与“想发给家人”相符。", "难看": "语义：“难看”与后面的“想发给家人”相矛盾。", "酸": "语义：“酸”指味道，不能用来形容照片。", "烫": "搭配：“烫”说温度，不能用来说照片拍得怎样。"}, "sentence_index": 6, "correct_answer": "受看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个话题最近很受看，网上讨论的人很多。", "explanation": "这里应该用〈受关注〉。受看说外表好看，话题引起很多人讨论要用受关注。"}, {"text": "这项新政策很受看，市民都很支持。", "explanation": "这里应该用〈受拥护〉。受看只形容样子好看，政策得到大家支持要用受拥护。"}, {"text": "这首新歌很受看，年轻人都抢着听。", "explanation": "这里应该用〈受追捧〉。歌是听的，受看只形容外表，被热烈喜爱要用受追捧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张桌子样式简单，摆在屋里比受看。", "corrected_sentence": "这张桌子样式简单，摆在屋里很受看。", "error_description": "错误：「比受看」。正确：「很受看」。「比」表示比较，需要比较对象；这里表示程度，应用程度副词「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套衣服穿很受看，店员都夸它。", "corrected_sentence": "这套衣服穿得很受看，店员都夸它。", "error_description": "错误：“穿很受看”，缺少补语标记“得”。正确：“穿得很受看”。动词后接表示状态的补语时，中间要加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
