INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好看，耐看，看着舒服。", "primary_collocate": null, "pronunciation": "shòu kàn", "ipa": "ʂoʊ˥˩ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服颜色简单，穿起来很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子收拾得整齐，看上去很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她长得不算漂亮，可是很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画虽然简单，但是挺受看的。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新做的窗帘颜色很淡，十分受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上这身西装，特别受看。", "target_word": "受看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些花摆在桌上，真受看。", "target_word": "受看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裙子样子普通，却很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的字写得整齐，看起来很受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的街道不大，却干净受看。", "target_word": "受看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不受看", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "样子耐看，看着舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受看", "is_correct": true, "explanation": "正确：“受看”指样子耐看、看着舒服，可以用来描述“穿起来”的样子。"}, {"text": "花哨", "is_correct": false, "explanation": "语义：“花哨”指颜色、图案繁多，与前文“颜色简单”相矛盾。"}, {"text": "苦", "is_correct": false, "explanation": "语义：「苦」指味道，不能用来形容衣服穿起来的样子。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”说声音，不能用来形容衣服。"}], "explanations": {"受看": "正确：“受看”指样子耐看、看着舒服，可以用来描述“穿起来”的样子。", "花哨": "语义：“花哨”指颜色、图案繁多，与前文“颜色简单”相矛盾。", "苦": "语义：「苦」指味道，不能用来形容衣服穿起来的样子。", "吵": "语义：“吵”说声音，不能用来形容衣服。"}, "sentence_index": 0, "correct_answer": "受看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手在年轻人中很受看，演唱会的票很快就卖光了。", "explanation": "这里应该用〈受欢迎〉。受看只说样子好看，说一个人或事物被大家喜爱要用受欢迎。"}, {"text": "这个方案在公司里很受看，领导也很看重。", "explanation": "这里应该用〈受重视〉。受看说外表，不能用来表示被领导看重。"}, {"text": "这家餐厅的服务很受看，顾客都很满意。", "explanation": "这里应该用〈受好评〉。服务的好坏要说受好评，受看只形容样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受看", "is_correct": true, "explanation": "正确：“受看”指样子耐看，与“真”搭配，用来评价摆在桌上的花。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，不能用来形容花的样子。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”一般说味道，不能用来形容摆在桌上的花。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地，与花好看与否无关。"}], "explanations": {"受看": "正确：“受看”指样子耐看，与“真”搭配，用来评价摆在桌上的花。", "苦": "语义：“苦”指味道，不能用来形容花的样子。", "辣": "搭配：“辣”一般说味道，不能用来形容摆在桌上的花。", "硬": "语义：“硬”指质地，与花好看与否无关。"}, "sentence_index": 6, "correct_answer": "受看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题最近很受看，讨论的人越来越多。", "explanation": "这里应该用〈受关注〉。受看只说样子好看，表示问题引起大家注意要用受关注。"}, {"text": "这家医院的医生很受看，病人都愿意找他们看病。", "explanation": "这里应该用〈受信任〉。受看只说样子耐看，病人相信医生要用受信任。"}, {"text": "这个说法在网上很受看，很多人都在转发。", "explanation": "这里应该用〈受追捧〉。说法不是看外表的东西，被大家热烈喜爱、转发要用受追捧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间小屋布置得简单，看上去比受看。", "corrected_sentence": "这间小屋布置得简单，看上去很受看。", "error_description": "错误：「比受看」。正确：「很受看」。「比」表示比较，需要比较对象；这里表示程度，应用程度副词「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这束花插很受看，放在窗台上。", "corrected_sentence": "这束花插得很受看，放在窗台上。", "error_description": "错误：“插很受看”，缺少补语标记“得”。正确：“插得很受看”。动词后接表示状态的补语时，中间要加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
