INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94471, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "同情是看到别人难过，自己心里也很难过，想去帮他。", "primary_collocate": null, "pronunciation": "tóng qíng", "ipa": "tʰʊŋ˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我很同情他，所以想帮他找工作。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到小女孩在雨里卖花，大家都同情她。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她同情那些没有家的小狗，常给它们送吃的。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一个人住，邻居们都很同情他。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同情她的遭遇，就借给她一些钱。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很同情穷人，每年都捐钱帮助他们。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈同情那个卖菜的老奶奶，多给了她钱。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家同情他丢了工作，都想帮他。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们同情他生病，轮流给他送饭。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同情这些孩子，想给他们买新书包。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同情心", "label": "复合"}, {"form": "同情过", "label": "体标"}], "register": "中性", "sense_fingerprint": "看到别人难过，心里难过并想帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94471, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同情", "is_correct": true, "explanation": "tóng qíng，意思是看到别人难过，自己心里也难过。"}, {"text": "铜青", "is_correct": false, "explanation": "tóngqīng：qīng（第一声）与 qíng（第二声）声调不同，意思是铜锈。"}, {"text": "同庆", "is_correct": false, "explanation": "qìng（第四声）与 qíng（第二声）声调不同，意思是共同庆祝。"}, {"text": "通情", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，意思是通晓情理。"}], "explanations": {"同情": "tóng qíng，意思是看到别人难过，自己心里也难过。", "铜青": "tóngqīng：qīng（第一声）与 qíng（第二声）声调不同，意思是铜锈。", "同庆": "qìng（第四声）与 qíng（第二声）声调不同，意思是共同庆祝。", "通情": "tōng（第一声）与 tóng（第二声）声调不同，意思是通晓情理。"}, "sentence_index": null, "correct_answer": "同情"}, "level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌表示厌恶，与后句“想帮他找工作”矛盾。"}, {"text": "同情", "is_correct": true, "explanation": "同情：对他的处境感到难过，所以想帮他，与后句的因果关系吻合。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：怀疑是不信任，不会促使人去帮他找工作。"}, {"text": "等待", "is_correct": false, "explanation": "搭配：“很”一般不修饰“等待”这类动作动词，且“很等待他”与后句的帮助意图接不上。"}], "explanations": {"讨厌": "语义：讨厌表示厌恶，与后句“想帮他找工作”矛盾。", "同情": "同情：对他的处境感到难过，所以想帮他，与后句的因果关系吻合。", "怀疑": "语义：怀疑是不信任，不会促使人去帮他找工作。", "等待": "搭配：“很”一般不修饰“等待”这类动作动词，且“很等待他”与后句的帮助意图接不上。"}, "sentence_index": 0, "correct_answer": "同情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "邻居们每天都来同情老人，给他做饭。", "explanation": "这里应该用〈照顾〉。同情只表示内心的共鸣，不表示实际的照料。"}, {"text": "你的办法很好，我完全同情。", "explanation": "这里应该用〈赞成〉。同情是对别人不幸的感受，不表示同意别人的办法。"}, {"text": "老人没有子女，邻居们轮流同情他。", "explanation": "这里应该用〈陪伴〉。同情是心里的感受，不能指轮流去陪着他。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94471, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同情", "is_correct": true, "explanation": "tóng qíng，意思是看到别人难过，自己心里也难过。"}, {"text": "铜钱", "is_correct": false, "explanation": "tóngqián：qián 与 qíng 韵母不同，意思是铜制的钱币。"}, {"text": "动情", "is_correct": false, "explanation": "dòng 与 tóng 声母不同（d 与 t），意思是情感被触动。"}, {"text": "通勤", "is_correct": false, "explanation": "tōngqín：tōng（第一声）与 tóng（第二声）声调不同，qín 与 qíng 韵尾不同，意思是上下班往返。"}], "explanations": {"同情": "tóng qíng，意思是看到别人难过，自己心里也难过。", "铜钱": "tóngqián：qián 与 qíng 韵母不同，意思是铜制的钱币。", "动情": "dòng 与 tóng 声母不同（d 与 t），意思是情感被触动。", "通勤": "tōngqín：tōng（第一声）与 tóng（第二声）声调不同，qín 与 qíng 韵尾不同，意思是上下班往返。"}, "sentence_index": null, "correct_answer": "同情"}, "level_3": {"options": [{"text": "嫌弃", "is_correct": false, "explanation": "语义：嫌弃表示厌烦、看不上，与“多给了她钱”矛盾。"}, {"text": "同情", "is_correct": true, "explanation": "同情：对卖菜老奶奶的处境感到怜悯，所以多给她钱，与后句吻合。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”是不满地责备，与“多给了她钱”的善意举动不协调。"}, {"text": "呵斥", "is_correct": false, "explanation": "语义：呵斥是大声责骂，与“多给了她钱”的善意举动矛盾。"}], "explanations": {"嫌弃": "语义：嫌弃表示厌烦、看不上，与“多给了她钱”矛盾。", "同情": "同情：对卖菜老奶奶的处境感到怜悯，所以多给她钱，与后句吻合。", "抱怨": "语义：“抱怨”是不满地责备，与“多给了她钱”的善意举动不协调。", "呵斥": "语义：呵斥是大声责骂，与“多给了她钱”的善意举动矛盾。"}, "sentence_index": 6, "correct_answer": "同情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师经常同情他的努力。", "explanation": "这里应该用〈表扬〉。同情是对他人不幸遭遇的共鸣，不能用来肯定别人的努力。"}, {"text": "妈妈总是同情我勇敢地尝试新东西。", "explanation": "这里应该用〈鼓励〉。同情表示对别人遭遇的感受，不表示给予勇气和支持。"}, {"text": "这个计划很有道理，我很同情它。", "explanation": "这里应该用〈赞同〉。同情表示对他人不幸遭遇的共鸣，不表示对计划的赞同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从心里同情得这个小男孩。", "corrected_sentence": "我从心里同情这个小男孩。", "error_description": "错误：“同情”后多加了结构助词“得”，写成“同情得这个小男孩”。正确：“同情”直接带宾语，说“同情这个小男孩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把同情那个孩子。", "corrected_sentence": "我同情那个孩子。", "error_description": "错误：“同情”是及物动词，不用“把”字句提前宾语，多加了“把”。正确：应说“我同情那个孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
