INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人的不幸遭遇在感情上发生共鸣。", "primary_collocate": null, "pronunciation": "tóng qíng", "ipa": "tʰʊŋ˧˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "听了他的故事，我心里很同情他。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子很可怜，谁看了都会同情。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同情她的不幸，也为她难过。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这样的人，我真的同情不起来。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着灾区的孩子，谁都会深深地同情他们。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很同情那位失去工作的父亲。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的遭遇让所有人都同情。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同情这位受了伤的运动员。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个坏消息，我们都十分同情他。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了亲人，朋友们都同情他的不幸。", "target_word": "同情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同情心", "label": "复合"}, {"form": "同情过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对别人的不幸在感情上产生共鸣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94472, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同情", "is_correct": true, "explanation": "tóng qíng，意思是对别人的不幸在感情上产生共鸣。"}, {"text": "铜青", "is_correct": false, "explanation": "tóngqīng：qīng（第一声）与 qíng（第二声）声调不同，意思是铜锈。"}, {"text": "同庆", "is_correct": false, "explanation": "qìng（第四声）与 qíng（第二声）声调不同，意思是共同庆祝。"}, {"text": "通情", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，意思是通晓情理。"}], "explanations": {"同情": "tóng qíng，意思是对别人的不幸在感情上产生共鸣。", "铜青": "tóngqīng：qīng（第一声）与 qíng（第二声）声调不同，意思是铜锈。", "同庆": "qìng（第四声）与 qíng（第二声）声调不同，意思是共同庆祝。", "通情": "tōng（第一声）与 tóng（第二声）声调不同，意思是通晓情理。"}, "sentence_index": null, "correct_answer": "同情"}, "level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑，与“听了他的故事”后心里的感受不符。"}, {"text": "同情", "is_correct": true, "explanation": "同情：听了他的故事后心里产生共鸣，与“我心里很”的感受吻合。"}, {"text": "等待", "is_correct": false, "explanation": "搭配：“很”一般不修饰“等待”这类动作动词，“心里很等待他”不成立。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：欺负指欺压，与“我心里很”的感受不符。"}], "explanations": {"嘲笑": "语义：嘲笑是取笑，与“听了他的故事”后心里的感受不符。", "同情": "同情：听了他的故事后心里产生共鸣，与“我心里很”的感受吻合。", "等待": "搭配：“很”一般不修饰“等待”这类动作动词，“心里很等待他”不成立。", "欺负": "语义：欺负指欺压，与“我心里很”的感受不符。"}, "sentence_index": 0, "correct_answer": "同情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "士兵必须同情上级的命令。", "explanation": "这里应该用〈服从〉。同情用于对人遭遇的感受，不能用于遵守命令。"}, {"text": "这首歌很好听，我很同情它，每天都听。", "explanation": "这里应该用〈欣赏〉。同情表示对不幸遭遇的共鸣，不能表示对作品的喜爱或欣赏。"}, {"text": "我同情了他的道歉。", "explanation": "这里应该用〈接受〉。同情不能表示接受别人的道歉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94472, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同情", "is_correct": true, "explanation": "tóng qíng，意思是对别人的不幸在感情上产生共鸣。"}, {"text": "铜钱", "is_correct": false, "explanation": "tóngqián：qián 与 qíng 韵母不同，意思是铜制的钱币。"}, {"text": "动情", "is_correct": false, "explanation": "dòng 与 tóng 声母不同（d 与 t），意思是情感被触动。"}, {"text": "通勤", "is_correct": false, "explanation": "tōngqín：tōng（第一声）与 tóng（第二声）声调不同，qín 与 qíng 韵尾不同，意思是上下班往返。"}], "explanations": {"同情": "tóng qíng，意思是对别人的不幸在感情上产生共鸣。", "铜钱": "tóngqián：qián 与 qíng 韵母不同，意思是铜制的钱币。", "动情": "dòng 与 tóng 声母不同（d 与 t），意思是情感被触动。", "通勤": "tōngqín：tōng（第一声）与 tóng（第二声）声调不同，qín 与 qíng 韵尾不同，意思是上下班往返。"}, "sentence_index": null, "correct_answer": "同情"}, "level_3": {"options": [{"text": "痛恨", "is_correct": false, "explanation": "语义：痛恨表示强烈憎恶，与“她的遭遇”引起的反应不符。"}, {"text": "同情", "is_correct": true, "explanation": "同情：对她的遭遇感到共鸣，与“让所有人都”的语境吻合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，而“她的遭遇”是不幸，不值得赞美，与“让所有人都”的语境不合。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：怀疑是不信任，与“她的遭遇”引发的反应不合。"}], "explanations": {"痛恨": "语义：痛恨表示强烈憎恶，与“她的遭遇”引起的反应不符。", "同情": "同情：对她的遭遇感到共鸣，与“让所有人都”的语境吻合。", "赞美": "语义：“赞美”是称赞，而“她的遭遇”是不幸，不值得赞美，与“让所有人都”的语境不合。", "怀疑": "语义：怀疑是不信任，与“她的遭遇”引发的反应不合。"}, "sentence_index": 6, "correct_answer": "同情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考上了名牌大学，朋友们都同情他。", "explanation": "这里应该用〈祝贺〉。同情表示对不幸遭遇的共鸣，不能用来为别人的喜事道贺。"}, {"text": "他帮我们搬完了东西，我们都同情他。", "explanation": "这里应该用〈感谢〉。同情表示对不幸遭遇的共鸣，不表示对别人帮助的感激。"}, {"text": "他弄丢了朋友的书，朋友们都同情他。", "explanation": "这里应该用〈原谅〉。同情表示对不幸遭遇的共鸣，不表示宽恕别人的过错。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很同情了这些流浪的人。", "corrected_sentence": "我很同情这些流浪的人。", "error_description": "错误：“很”修饰“同情”时，句中又加了“了”，写成“很同情了这些流浪的人”。正确：“很”不能修饰带“了”的动作，应说“我很同情这些流浪的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家同情的看着他。", "corrected_sentence": "大家同情地看着他。", "error_description": "错误：修饰动词“看”时用了“的”，写成“同情的看着他”。正确：应用“地”，说“同情地看着他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
