INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94473, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94473, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "名字是某某，用来介绍人或事物的名字。", "primary_collocate": null, "pronunciation": "míng jiào", "ipa": "miŋ˧˥ tɕjɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我有一个朋友名叫小王。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小狗名叫豆豆，很爱玩。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妹妹名叫小美，今年八岁。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板名叫李明。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有个女生名叫安安。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个名叫大卫的外国人来找你。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她养了一只名叫咪咪的小猫。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一个名叫花园的小村子。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位医生名叫王华，人很好。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的孩子名叫小明，很可爱。", "target_word": "名叫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名字是某某，用来介绍人或事物的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54747f1c-7f82-48a2-943c-930173304b61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名叫", "is_correct": true, "explanation": "“我有一个朋友名叫小王”，“名叫”引出朋友的名字，正确。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示变为，朋友不能变成小王。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的对象是东西，不能用来搬人。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”用于拆房屋、信件等，不能用来拆人。"}], "explanations": {"名叫": "“我有一个朋友名叫小王”，“名叫”引出朋友的名字，正确。", "变成": "语义：“变成”表示变为，朋友不能变成小王。", "搬": "搭配：“搬”的对象是东西，不能用来搬人。", "拆": "搭配：“拆”用于拆房屋、信件等，不能用来拆人。"}, "sentence_index": 0, "correct_answer": "名叫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的小狗名叫非常可爱，很好玩。", "explanation": "“名叫”后只接名字，不能接形容词短语。描述性质时直接说“我的小狗非常可爱”。"}, {"text": "我们的老板名叫李。", "explanation": "这里应该用〈姓〉。“名叫”后面要接完整的名字，不能只说姓。"}, {"text": "他名叫我的朋友。", "explanation": "这里应该用〈是〉。“名叫”用来说出名字，不能用来说人的身份关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名叫", "is_correct": true, "explanation": "“一只名叫咪咪的小猫”，“名叫”引出小猫的名字，正确。"}, {"text": "姓", "is_correct": false, "explanation": "搭配：“姓”用于人的姓氏，小猫不能姓咪咪。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”的对象是帽子、眼镜等，咪咪不能被戴。"}, {"text": "吃", "is_correct": false, "explanation": "语义：小猫不会吃“咪咪”，这个说法与句子语境不符。"}], "explanations": {"名叫": "“一只名叫咪咪的小猫”，“名叫”引出小猫的名字，正确。", "姓": "搭配：“姓”用于人的姓氏，小猫不能姓咪咪。", "戴": "搭配：“戴”的对象是帽子、眼镜等，咪咪不能被戴。", "吃": "语义：小猫不会吃“咪咪”，这个说法与句子语境不符。"}, "sentence_index": 6, "correct_answer": "名叫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的孩子名叫跑来跑去，很可爱。", "explanation": "这里应该用〈喜欢〉。“名叫”后只接名字，“跑来跑去”是动作，不能作孩子的名字。"}, {"text": "他们名叫一个很可爱的孩子。", "explanation": "这里应该用〈有〉。“名叫”后面接的是名字，不能接“一个很可爱的孩子”这类描写性短语。"}, {"text": "他们的孩子名叫很多，很可爱。", "explanation": "这里应该用〈有〉。“很多”是数量短语，不能作人名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只小猫，名叫了咪咪。", "corrected_sentence": "我有一只小猫，名叫咪咪。", "error_description": "错误：“名叫了咪咪”；正确：“名叫咪咪”。“名叫”引出名字，表示一种已存在的状态，不带“了”；句中并没有完成某个动作，加“了”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家的狗名叫的豆豆。", "corrected_sentence": "我们家的狗名叫豆豆。", "error_description": "“名叫”后面直接接名字，中间不能加“的”。应说“名叫豆豆”，写成“名叫的豆豆”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
