INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94475, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吐（tǔ）是把嘴里的东西弄出来。", "primary_collocate": null, "pronunciation": "tǔ", "ipa": "tʰu˨˩˦", "syllable_count": 1, "sentences": [{"text": "吃鱼的时候，要把刺吐出来。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把嘴里的西瓜子吐在纸上。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在地上吐口水。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩觉得药太苦，马上吐了出来。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边吃葡萄，一边把皮吐在桌上。", "target_word": "吐", "complexity_tier": "T3", "furigana": "tā yìbiān chī pútao, yìbiān bǎ pí tǔ zài zhuō shang.", "sentence_source": "generated"}, {"text": "漱完口，把水吐在水池里。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完樱桃，他把核吐进了小碗里。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把口香糖吐在地上。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把嘴里的茶叶吐了出来。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人坐在门口，吐着瓜子皮。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吐了", "label": "体标"}, {"form": "吐过", "label": "体标"}, {"form": "吐着", "label": "体标"}], "register": "口语", "sense_fingerprint": "吐·tǔ·把嘴里的东西弄出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 漱 (Zipf 2.43)']::text[], 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。吐（tǔ，第三声）是把嘴里的东西弄出来。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tǔ（第三声）声调不同，意思是兔子。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 tǔ 声调不同，意思是图画。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tǔ 声调不同，意思是突然。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ 与 tǔ 只差声母（d 与 t），意思是堵塞。"}], "explanations": {"吐": "正确。吐（tǔ，第三声）是把嘴里的东西弄出来。", "兔": "tù（第四声）与 tǔ（第三声）声调不同，意思是兔子。", "图": "tú（第二声）与 tǔ 声调不同，意思是图画。", "突": "tū（第一声）与 tǔ 声调不同，意思是突然。", "堵": "dǔ 与 tǔ 只差声母（d 与 t），意思是堵塞。"}, "sentence_index": null, "correct_answer": "吐"}, "level_3": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。“吐出来”表示从嘴里把刺弄出来。"}, {"text": "咽", "is_correct": false, "explanation": "语义：“咽”是把东西咽下去，与“出来”的方向相反。"}, {"text": "嚼", "is_correct": false, "explanation": "搭配：“嚼”不能与“把刺……出来”搭配，刺不是嚼出来的。"}, {"text": "舔", "is_correct": false, "explanation": "搭配：“舔”是用舌头碰东西，不能说“把刺舔出来”。"}], "explanations": {"吐": "正确。“吐出来”表示从嘴里把刺弄出来。", "咽": "语义：“咽”是把东西咽下去，与“出来”的方向相反。", "嚼": "搭配：“嚼”不能与“把刺……出来”搭配，刺不是嚼出来的。", "舔": "搭配：“舔”是用舌头碰东西，不能说“把刺舔出来”。"}, "sentence_index": 0, "correct_answer": "吐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把垃圾吐进了桶里。", "explanation": "这里应该用〈扔〉。吐是把嘴里的东西弄出来，垃圾不是从嘴里出来的，要用扔。"}, {"text": "他把墨水吐在了纸上。", "explanation": "这里应该用〈滴〉。吐是把嘴里的东西弄出来，墨水要用滴或洒。"}, {"text": "他把名字吐在了纸上。", "explanation": "这里应该用〈写〉。吐不能用来表示把字写在纸上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94475, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。吐（tǔ，第三声）是把嘴里的东西弄出来。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tǔ 声调不同，意思是没有头发。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ 与 tǔ 声母不同（d 与 t），意思是打赌。"}, {"text": "涂", "is_correct": false, "explanation": "tú（第二声）与 tǔ 声调不同，意思是涂抹。"}], "explanations": {"吐": "正确。吐（tǔ，第三声）是把嘴里的东西弄出来。", "秃": "tū（第一声）与 tǔ 声调不同，意思是没有头发。", "赌": "dǔ 与 tǔ 声母不同（d 与 t），意思是打赌。", "涂": "tú（第二声）与 tǔ 声调不同，意思是涂抹。"}, "sentence_index": null, "correct_answer": "吐"}, "level_3": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。“吐进小碗里”表示把嘴里的核弄出来放进碗里。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿切断东西，不能把核咬进碗里。"}, {"text": "吸", "is_correct": false, "explanation": "搭配：“吸”后面接“进小碗里”不通，核不是被吸进去的。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”是发出咳嗽的声音，不能把核咳进碗里。"}], "explanations": {"吐": "正确。“吐进小碗里”表示把嘴里的核弄出来放进碗里。", "咬": "语义：“咬”是用牙齿切断东西，不能把核咬进碗里。", "吸": "搭配：“吸”后面接“进小碗里”不通，核不是被吸进去的。", "咳": "语义：“咳”是发出咳嗽的声音，不能把核咳进碗里。"}, "sentence_index": 6, "correct_answer": "吐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙吐进了抽屉里。", "explanation": "这里应该用〈放〉。吐是把嘴里的东西弄出来，钥匙不是从嘴里出来的，要用放。"}, {"text": "他把行李吐上了车。", "explanation": "这里应该用〈搬〉。吐是把嘴里的东西弄出来，行李不是从嘴里出来的，要用搬。"}, {"text": "他把车钥匙吐给了朋友。", "explanation": "这里应该用〈交〉。吐是把嘴里的东西弄出来，把东西交给别人要用交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把瓜子皮吐了在地上。", "corrected_sentence": "他把瓜子皮吐在了地上。", "error_description": "“了”的位置错误：完成标记“了”应放在“在”的后面，说“吐在了地上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃完橘子，他把果皮吐出了来。", "corrected_sentence": "吃完橘子，他把果皮吐了出来。", "error_description": "“了”位置错误：“了”不能插在补语“出来”中间，应说“吐了出来”或“吐出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
