INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "呕吐：胃里的东西从嘴里涌出来。", "primary_collocate": null, "pronunciation": "tù", "ipa": "tʰu˥˩", "syllable_count": 1, "sentences": [{"text": "他坐船坐久了，吐得很厉害。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃多了，晚上吐了两次。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一闻到那个味道就想吐。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天喝了太多酒，他一直在吐。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发烧了，吃什么都吐。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得太快，弟弟吐了一路。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了坏东西，我又吐又拉肚子。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问她吐过几次。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吐得脸都白了。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐过山车以后，好几个人都吐了。", "target_word": "吐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吐了", "label": "体标"}, {"form": "吐过", "label": "体标"}, {"form": "呕吐", "label": "复合"}], "register": "口语", "sense_fingerprint": "吐·tù·呕吐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。吐（tù，第四声）是呕吐的意思。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 tù 声调不同，意思是泥土。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tù 声调不同，意思是突然。"}, {"text": "图", "is_correct": false, "explanation": "tú（第二声）与 tù 声调不同，意思是图画。"}], "explanations": {"吐": "正确。吐（tù，第四声）是呕吐的意思。", "土": "tǔ（第三声）与 tù 声调不同，意思是泥土。", "突": "tū（第一声）与 tù 声调不同，意思是突然。", "图": "tú（第二声）与 tù 声调不同，意思是图画。"}, "sentence_index": null, "correct_answer": "吐"}, "level_3": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。“吐得很厉害”说的是坐船后呕吐得厉害。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是歌唱，与坐船后的身体不适无关。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写得很厉害”说的是写字，不能用来描述身体反应。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”是在水里活动，句子说的是坐船后的不适，不能说“游得很厉害”。"}], "explanations": {"吐": "正确。“吐得很厉害”说的是坐船后呕吐得厉害。", "唱": "语义：“唱”是歌唱，与坐船后的身体不适无关。", "写": "搭配：“写得很厉害”说的是写字，不能用来描述身体反应。", "游": "语义：“游”是在水里活动，句子说的是坐船后的不适，不能说“游得很厉害”。"}, "sentence_index": 0, "correct_answer": "吐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吐了两声，喉咙很痛。", "explanation": "这里应该用〈咳〉。吐指呕吐或把东西弄出来，不能用来表示发出咳嗽的声音。"}, {"text": "他热得直吐汗。", "explanation": "这里应该用〈流〉。汗是从皮肤流出来的，不能说吐汗。"}, {"text": "他把书吐在了桌子上。", "explanation": "这里应该用〈放〉。吐指呕吐或把嘴里的东西弄出来，书不是从嘴里出来的，要用放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。吐（tù，第四声）是呕吐的意思。"}, {"text": "度", "is_correct": false, "explanation": "dù 与 tù 声母不同（d 与 t），意思是程度。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tù 声调不同，意思是没有头发。"}, {"text": "涂", "is_correct": false, "explanation": "tú（第二声）与 tù 声调不同，意思是涂抹。"}], "explanations": {"吐": "正确。吐（tù，第四声）是呕吐的意思。", "度": "dù 与 tù 声母不同（d 与 t），意思是程度。", "秃": "tū（第一声）与 tù 声调不同，意思是没有头发。", "涂": "tú（第二声）与 tù 声调不同，意思是涂抹。"}, "sentence_index": null, "correct_answer": "吐"}, "level_3": {"options": [{"text": "吐", "is_correct": true, "explanation": "正确。“又吐又拉肚子”描述的是吃了坏东西后的呕吐和腹泻。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”与拉肚子不搭，这里描述的是身体不适。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备别人，与吃坏东西后的症状无关。"}, {"text": "数", "is_correct": false, "explanation": "搭配：“又数又拉肚子”不通，“数”不能描述身体的症状。"}], "explanations": {"吐": "正确。“又吐又拉肚子”描述的是吃了坏东西后的呕吐和腹泻。", "笑": "语义：“笑”与拉肚子不搭，这里描述的是身体不适。", "骂": "语义：“骂”是责备别人，与吃坏东西后的症状无关。", "数": "搭配：“又数又拉肚子”不通，“数”不能描述身体的症状。"}, "sentence_index": 6, "correct_answer": "吐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他难过得吐了很多眼泪。", "explanation": "这里应该用〈流〉。“吐”指呕吐，眼泪是从眼睛里流出来的，要说“流眼泪”。"}, {"text": "秋天到了，树叶吐了一地。", "explanation": "这里应该用〈落〉。“吐”指呕吐，树叶从树上掉下来要说“落”。"}, {"text": "他把一百块钱吐给了老板。", "explanation": "这里应该用〈付〉。“吐”指呕吐或把嘴里的东西弄出来，付钱要用付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她发烧了，吐很厉害。", "corrected_sentence": "她发烧了，吐得很厉害。", "error_description": "补语缺少“得”：说“吐得很厉害”时必须用“得”把补语接在动词后面，直接说“吐很厉害”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝醉以后吐了过两次。", "corrected_sentence": "他喝醉以后吐过两次。", "error_description": "体标顺序错误：“吐过”的“过”表示经历，“了”与“过”不能同时出现在动词后，应说“吐过两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "向前是朝着前面的方向走。", "primary_collocate": null, "pronunciation": "xiàng qián", "ipa": "ɕjɑŋ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "请大家向前走三步。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向前走了几步，路上一个人也没有。", "target_word": "向前", "complexity_tier": "T3", "furigana": "tā xiàng qián zǒu le jǐ bù, lù shàng yí gè rén yě méi yǒu.", "sentence_source": "generated"}, {"text": "队伍慢慢向前走着。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机说，请向前走，不要停。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们向前跑，想先到河边。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开了，他向前迈了一步。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪很大，我们还是向前走。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让第一排的同学向前站。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向前走了几步，看见一座桥。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一亮，大家就向前走。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向前走", "label": "复合"}], "register": "中性", "sense_fingerprint": "向前·xiàng qián·朝着前面的方向走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久持续，与“走三步”这种有限的动作不合。"}, {"text": "突然", "is_correct": false, "explanation": "搭配：“突然”表示意外发生，不能与“请大家……走三步”这类指令搭配。"}, {"text": "向前", "is_correct": true, "explanation": "向前：表示朝前方走，与“走三步”搭配，是指示大家朝前走的动作。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“请大家”的要求不合。"}], "explanations": {"永远": "语义：“永远”表示长久持续，与“走三步”这种有限的动作不合。", "突然": "搭配：“突然”表示意外发生，不能与“请大家……走三步”这类指令搭配。", "向前": "向前：表示朝前方走，与“走三步”搭配，是指示大家朝前走的动作。", "偶尔": "语义：“偶尔”表示不常发生，与“请大家”的要求不合。"}, "sentence_index": 0, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向前在屋里坐了一下午。", "explanation": "这里不应用〈向前〉。“向前”只表示朝前方的移动，不表示动作的持续；动作持续要说〈一直〉。"}, {"text": "这个问题我向前想了很久。", "explanation": "这里不应用〈向前〉。“向前”表示空间方向，思考没有位移；想问题的程度要说〈认真〉或〈反复〉。"}, {"text": "他向前退了两步，挡在门口。", "explanation": "这里应该用〈向后〉。“退”是向后移动，与“向前”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“还是”表示仍然相悖。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱，与“还是”的陈述语气不合。"}, {"text": "向前", "is_correct": true, "explanation": "向前：朝前方走，与“我们还是……走”搭配，表示雪大仍然朝前走。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突发，与“还是”表示持续的语气不搭配。"}], "explanations": {"已经": "语义：“已经”表示已完成，与“还是”表示仍然相悖。", "千万": "语义：“千万”多用于叮嘱，与“还是”的陈述语气不合。", "向前": "向前：朝前方走，与“我们还是……走”搭配，表示雪大仍然朝前走。", "忽然": "搭配：“忽然”表示突发，与“还是”表示持续的语气不搭配。"}, "sentence_index": 6, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师向前布置了作业。", "explanation": "这里应该用〈提前〉。“向前”只表示空间上朝前，不表示时间上的提前；布置作业的早晚要说〈提前〉。"}, {"text": "我们向前再说吧。", "explanation": "这里应该用〈以后〉。“向前”只表示朝前方的空间方向，不表示将来的时间；“再说”的时间要说〈以后〉。"}, {"text": "这次比赛他向前拿到了冠军。", "explanation": "这里不应用〈向前〉。“向前”只表示空间方向，表示名次要说“第一”或“名列前茅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他慢慢向前了走，没有回头。", "corrected_sentence": "他慢慢向前走，没有回头。", "error_description": "多加了“了”：“向前”后面直接接动词“走”，中间不能插入“了”，应说“向前走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人慢慢了向前走，手里拿着拐杖。", "corrected_sentence": "老人慢慢向前走，手里拿着拐杖。", "error_description": "“了”位置错误：“了”不能插在“慢慢”和“向前”之间，此处不需要“了”，应说“老人慢慢向前走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "朝前方；往前进。", "primary_collocate": null, "pronunciation": "xiàng qián", "ipa": "ɕjɑŋ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "车慢慢向前开，路上有点堵。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾很大，他探身向前看，慢慢找路。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在大风里一直向前行。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力向前推，门终于开了。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们互相帮助，一步一步向前。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时，身体要向前倾一点。", "target_word": "向前", "complexity_tier": "T3", "furigana": "pǎo bù shí, shēn tǐ yào xiàng qián qīng yì diǎn.", "sentence_source": "generated"}, {"text": "她向前伸出手，想拉住孩子。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，大家都向前冲。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面是一条直路，他们只管向前走，不能停在原地。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车向前开动，站台越来越远。", "target_word": "向前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "向前·xiàng qián·朝前方、往前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e011f187-76b3-48e8-ab44-08a69ff0748e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“慢慢”的持续缓慢相矛盾。"}, {"text": "向前", "is_correct": true, "explanation": "向前：表示朝前方行进，与“车慢慢开”搭配，描述车朝前慢行。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”表示瞬间完成，不能与“慢慢”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与车持续慢开、路上堵车的情景不合。"}], "explanations": {"突然": "语义：“突然”表示事情忽然发生，与“慢慢”的持续缓慢相矛盾。", "向前": "向前：表示朝前方行进，与“车慢慢开”搭配，描述车朝前慢行。", "一下子": "搭配：“一下子”表示瞬间完成，不能与“慢慢”搭配。", "偶尔": "语义：“偶尔”表示不常发生，与车持续慢开、路上堵车的情景不合。"}, "sentence_index": 0, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向前睡觉，一直睡到中午。", "explanation": "这里不应用〈向前〉。“向前”只表示朝前方的空间移动，睡觉不涉及位移，也不表示先后；动作在先要说〈先〉。"}, {"text": "我向前喜欢这首歌，每天都听。", "explanation": "这里应该用〈很〉。“向前”只表示朝前的空间方向，不表示喜欢的程度；表示喜欢的程度要用〈很〉。"}, {"text": "他向前拒绝了这份工作。", "explanation": "这里不应用〈向前〉。“向前”只表示朝前方的空间移动，不能修饰“拒绝”这类与位移无关的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求多个主体共同行动，“她”单独一人不能“一起伸出手”。"}, {"text": "向前", "is_correct": true, "explanation": "向前：表示朝前方伸出，与“想拉住孩子”的动作一致。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”多用于叮嘱或劝阻，与叙述“伸出手”这一动作不合。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久持续，与“伸出手”这一次性动作不合。"}], "explanations": {"一起": "搭配：“一起”要求多个主体共同行动，“她”单独一人不能“一起伸出手”。", "向前": "向前：表示朝前方伸出，与“想拉住孩子”的动作一致。", "千万": "语义：“千万”多用于叮嘱或劝阻，与叙述“伸出手”这一动作不合。", "永远": "语义：“永远”表示长久持续，与“伸出手”这一次性动作不合。"}, "sentence_index": 6, "correct_answer": "向前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向前在北京工作过，后来才调走。", "explanation": "这里应该用〈以前〉。“向前”只表示空间上朝前，不表示过去的时间；过去的经历要说〈以前〉。"}, {"text": "他向前退了一步，差点撞到墙上。", "explanation": "这里应该用〈向后〉。“退”是向后移动，与“向前”的方向相反，两者不能搭配。"}, {"text": "这次考试他向前拿了第一名。", "explanation": "这里不应用〈向前〉。“向前”只表示空间方向，表示名次靠前要说“第一”或“名列前茅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她向前了走两步，停了下来。", "corrected_sentence": "她向前走了两步，停了下来。", "error_description": "错误形式：向前了走；正确形式：向前走了。“了”应放在动词之后，表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他往向前走了几步，又回头看了看。", "corrected_sentence": "他向前走了几步，又回头看了看。", "error_description": "错误形式：往向前；正确形式：向前。“向前”里的“向”已经表示方向，前面不能再加“往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58355301-d70f-4fdf-bf64-699f495e0be9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通知，使人知道。", "primary_collocate": null, "pronunciation": "gào zhī", "ipa": "kɑʊ˥˩ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "学校告知家长下周开会。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行已经告知客户账户有变化。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请提前告知我们你的到达时间。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司告知员工明天放假一天。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮件里告知了面试的地点。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店告知客人电梯正在修理。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院告知病人家属明早来签字。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有提前告知我们会议改期。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板告知大家下午三点开会。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请及时告知我你的决定。", "target_word": "告知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "告知了", "label": "完成体"}, {"form": "告知过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "告知：正式通知，使人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '590f9f2d-b44f-4d77-b101-cbb4ab4e1ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "配价：散步是不及物动词，不能带“家长”作宾语。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：不能“打扫”家长，句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：不能“煮”家长，句意荒谬。"}, {"text": "告知", "is_correct": true, "explanation": "正确：“告知”表示正式通知别人，与“学校告知家长下周开会”相符。"}], "explanations": {"散步": "配价：散步是不及物动词，不能带“家长”作宾语。", "打扫": "语义：不能“打扫”家长，句意不通。", "煮": "语义：不能“煮”家长，句意荒谬。", "告知": "正确：“告知”表示正式通知别人，与“学校告知家长下周开会”相符。"}, "sentence_index": 0, "correct_answer": "告知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师告知感谢。", "explanation": "这里应该用〈表示〉。告知是把事情说给别人听，感谢是情感，不能告知。"}, {"text": "他告知了眼泪。", "explanation": "这里应该用〈流〉。告知是把事情说给别人听，眼泪不能告知。"}, {"text": "她告知了一个鬼脸。", "explanation": "这里应该用〈做〉。告知是把事情说给别人听，鬼脸是动作，不能告知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观风景名胜，不能“游览病人家属”，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与签字的通知内容无关，句意荒谬。"}, {"text": "缝", "is_correct": false, "explanation": "语义：不能“缝”病人家属，句意不通。"}, {"text": "告知", "is_correct": true, "explanation": "正确：“告知”表示通知别人，与“医院告知病人家属明早来签字”相符。"}], "explanations": {"游览": "语义：“游览”指参观风景名胜，不能“游览病人家属”，句意不通。", "唱": "语义：唱歌与签字的通知内容无关，句意荒谬。", "缝": "语义：不能“缝”病人家属，句意不通。", "告知": "正确：“告知”表示通知别人，与“医院告知病人家属明早来签字”相符。"}, "sentence_index": 6, "correct_answer": "告知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每晚给我告知一顿饭。", "explanation": "这里应该用〈做〉。做饭要用〈做〉，“告知”只能用于事情和消息。"}, {"text": "妹妹在纸上告知了一只猫。", "explanation": "这里应该用〈画〉。画画要用〈画〉，“告知”不能用来描述绘画。"}, {"text": "他告知了一首诗给我。", "explanation": "这里应该用〈写〉。写诗要用〈写〉，“告知”只能用于事情和消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师告知学生了考试时间。", "corrected_sentence": "老师告知学生考试时间。", "error_description": "多余的“了”：“学生了考试时间”中“了”插在宾语“学生”与“考试时间”之间，不符合汉语语序；删去该“了”即为“老师告知学生考试时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校从没告知了我们这件事。", "corrected_sentence": "学校从没告知过我们这件事。", "error_description": "体标误用：“从没”表示从未有过这种经历，应用经历体“过”（告知过），不能用完成体“了”（告知了）。正确形式是“学校从没告知过我们这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4adb33db-8a63-4b0c-a2fa-998542fc2e35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
