INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94481, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "和美是一家人在一起很好，很开心。", "primary_collocate": null, "pronunciation": "hé měi", "ipa": "xɤ˧˥ meɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们一家人过得很和美，笑声不断。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的日子过得和美，孩子们每天都笑个不停。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷奶奶住在一起，生活很和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个和美的小家庭。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末全家一起吃饭，气氛特别和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望自己有一个和美的家。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家里总是笑声不断，十分和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都回来了，一家人和美地过年。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着和美的一家人，我也很羡慕。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居一家的日子十分和美，笑语盈门。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和和美美", "label": "重叠"}], "register": "书面", "sense_fingerprint": "一家人在一起相处很好、很开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤单", "is_correct": false, "explanation": "语义：“孤单”与“笑声不断”的描写相反，家里笑声不断时不会过得孤单。"}, {"text": "和美", "is_correct": true, "explanation": "和美：一家人相处和睦、开心，与“过得很”的语境相合。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的体型，不能用来形容日子过得怎样。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”形容性情暴烈，与和睦的家庭生活不符。"}], "explanations": {"孤单": "语义：“孤单”与“笑声不断”的描写相反，家里笑声不断时不会过得孤单。", "和美": "和美：一家人相处和睦、开心，与“过得很”的语境相合。", "高大": "搭配：“高大”形容人或物的体型，不能用来形容日子过得怎样。", "凶狠": "语义：“凶狠”形容性情暴烈，与和睦的家庭生活不符。"}, "sentence_index": 0, "correct_answer": "和美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末的商场很和美，人来人往。", "explanation": "这里应该用〈热闹〉。和美形容家人相处和睦，不能用来形容商场。"}, {"text": "他说话很和美，大家都喜欢他。", "explanation": "这里应该用〈和气〉。和美形容家庭关系融洽，不形容说话的语气。"}, {"text": "她长得很和美。", "explanation": "这里应该用〈漂亮〉。和美形容家庭的和睦，不用于形容人的外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没有人声、冷冷清清，与“笑声不断”矛盾。"}, {"text": "和美", "is_correct": true, "explanation": "和美：家人相处融洽，与“笑声不断”的描述相合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材，不能形容家里的气氛。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”指孤单无人陪伴，与“笑声不断”矛盾。"}], "explanations": {"冷清": "语义：“冷清”指没有人声、冷冷清清，与“笑声不断”矛盾。", "和美": "和美：家人相处融洽，与“笑声不断”的描述相合。", "高大": "体貌：“高大”形容人或物的身材，不能形容家里的气氛。", "寂寞": "语义：“寂寞”指孤单无人陪伴，与“笑声不断”矛盾。"}, "sentence_index": 6, "correct_answer": "和美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆里非常和美，大家都在看书。", "explanation": "这里应该用〈安静〉。和美形容家人的和睦，不用来形容图书馆的环境。"}, {"text": "房间收拾得很和美，地板都亮了。", "explanation": "这里应该用〈干净〉。和美不能用来形容房间是否整洁。"}, {"text": "他学习很和美，每天都很用功。", "explanation": "这里应该用〈认真〉。和美形容家庭关系，不用于描述学习的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这对老夫妻生活的很和美。", "corrected_sentence": "这对老夫妻生活得很和美。", "error_description": "错误：补语前的“得”写成了“的”，写成“生活的很和美”。正确：应用“得”，说“生活得很和美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一家人和美的吃晚饭。", "corrected_sentence": "一家人和美地吃晚饭。", "error_description": "错误：“和美”修饰动词“吃”时用了“的”，写成“和美的吃晚饭”。正确：应用“地”，说“和美地吃晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
