INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94482, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "和睦美满。", "primary_collocate": null, "pronunciation": "hé měi", "ipa": "xɤ˧˥ meɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们夫妻感情很好，婚后生活和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你们新婚快乐，婚姻和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老两口相爱几十年，日子过得和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个和美的家庭，需要大家互相理解。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的婚姻十分和美，让人羡慕。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻和美幸福，从不吵架。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭和美，工作才能顺利。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和丈夫生活和美，孩子也很听话。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里最和美的一家就是他们家。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最大的愿望是父母永远和美。", "target_word": "和美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和和美美", "label": "重叠"}], "register": "书面", "sense_fingerprint": "家庭、婚姻和睦美满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指感情疏远，与“夫妻感情很好”矛盾。"}, {"text": "和美", "is_correct": true, "explanation": "和美：夫妻感情好，家庭和睦美满，与“婚后生活”的描述吻合。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或建筑，不能说“生活高大”。"}, {"text": "破碎", "is_correct": false, "explanation": "语义：“破碎”指婚姻或家庭破裂，与“感情很好”矛盾。"}], "explanations": {"冷淡": "语义：“冷淡”指感情疏远，与“夫妻感情很好”矛盾。", "和美": "和美：夫妻感情好，家庭和睦美满，与“婚后生活”的描述吻合。", "高大": "搭配：“高大”形容体型或建筑，不能说“生活高大”。", "破碎": "语义：“破碎”指婚姻或家庭破裂，与“感情很好”矛盾。"}, "sentence_index": 0, "correct_answer": "和美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身体很和美，从来不生病。", "explanation": "这里应该用〈健康〉。和美说的是家庭和睦，不能用来形容身体状况。"}, {"text": "他跑得很和美，第一个到了终点。", "explanation": "这里应该用〈快〉。和美不形容速度，跑得快要说“快”。"}, {"text": "老师对学生的要求很和美。", "explanation": "这里应该用〈严格〉。和美形容家庭关系，不能用来描述要求的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动荡", "is_correct": false, "explanation": "语义：“动荡”指不安定，与“工作才能顺利”的前提相反。"}, {"text": "和美", "is_correct": true, "explanation": "和美：家庭和睦美满，才能让人安心工作，与后句吻合。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容家庭。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”与“家庭和美”的意思相反，也不能支撑“工作才能顺利”。"}], "explanations": {"动荡": "语义：“动荡”指不安定，与“工作才能顺利”的前提相反。", "和美": "和美：家庭和睦美满，才能让人安心工作，与后句吻合。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容家庭。", "吵闹": "语义：“吵闹”与“家庭和美”的意思相反，也不能支撑“工作才能顺利”。"}, "sentence_index": 6, "correct_answer": "和美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很和美，晚上走也放心。", "explanation": "这里应该用〈安全〉。和美形容家庭的和睦，不能用来形容道路。"}, {"text": "这件衣服很和美，才五十块钱。", "explanation": "这里应该用〈便宜〉。和美形容家庭和睦，不能用来形容衣服的价格。"}, {"text": "这张桌子很和美，四条腿都很结实。", "explanation": "这里应该用〈稳固〉。和美形容家庭的和睦，不能用来形容家具是否牢固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们结婚以后，家里一直很的和美。", "corrected_sentence": "他们结婚以后，家里一直很和美。", "error_description": "错误：“很”和“和美”之间多了“的”，写成“很的和美”。正确：“很”直接修饰“和美”，应说“很和美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们有一个很和美家庭。", "corrected_sentence": "他们有一个很和美的家庭。", "error_description": "错误：“很和美”修饰名词“家庭”时漏了“的”。正确：应说“很和美的家庭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
