INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种极小的长度单位，等于十的负十次方米（即十分之一纳米），用于量原子、波长等极小的距离。", "primary_collocate": null, "pronunciation": "āi", "ipa": "ai̯˥", "syllable_count": 1, "sentences": [{"text": "一埃等于十分之一纳米。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氢原子的直径大约是一埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种光的波长只有几千埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用埃来量原子之间的距离。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个原子相隔约两埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个晶体里，原子的间距是三埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一埃非常短，眼睛根本看不到。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水分子的大小只有几埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，一米等于一百亿埃。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写道：一埃是十的负十次方米。", "target_word": "埃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "长度单位埃，用于量原子、波长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bf16998-b680-4925-b347-7ab93e7d58ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃（āi，第一声）是本条目所教的长度单位。"}, {"text": "矮", "is_correct": false, "explanation": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是喜欢。"}, {"text": "挨", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是靠近或遭受。"}], "explanations": {"埃": "埃（āi，第一声）是本条目所教的长度单位。", "矮": "ǎi（第三声）与 āi（第一声）声调不同，意思是个子低。", "爱": "ài（第四声）与 āi（第一声）声调不同，意思是喜欢。", "挨": "ái（第二声）与 āi（第一声）声调不同，意思是靠近或遭受。"}, "sentence_index": null, "correct_answer": "埃"}, "level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃是长度单位，约为十分之一纳米，与句中的换算关系一致，正确。"}, {"text": "米", "is_correct": false, "explanation": "语义：米比纳米大十亿倍，“一米等于十分之一纳米”与事实不符，句意不通。"}, {"text": "毫米", "is_correct": false, "explanation": "语义：毫米远大于埃，一毫米不可能只等于十分之一纳米。"}, {"text": "纳米", "is_correct": false, "explanation": "搭配：句末已用纳米作比较标准，前面再用纳米自比，“一纳米等于十分之一纳米”没有意义。"}], "explanations": {"埃": "埃是长度单位，约为十分之一纳米，与句中的换算关系一致，正确。", "米": "语义：米比纳米大十亿倍，“一米等于十分之一纳米”与事实不符，句意不通。", "毫米": "语义：毫米远大于埃，一毫米不可能只等于十分之一纳米。", "纳米": "搭配：句末已用纳米作比较标准，前面再用纳米自比，“一纳米等于十分之一纳米”没有意义。"}, "sentence_index": 0, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高是一百七十埃。", "explanation": "这里应该用〈厘米〉。埃是极小的长度单位，只用于原子、波长等微观距离，人的身高要用厘米。"}, {"text": "这袋大米重五埃。", "explanation": "这里应该用〈千克〉。埃是长度单位，只用于原子、波长等极小的长度，不能表示重量。"}, {"text": "我们等了五埃才上车。", "explanation": "这里应该用〈分钟〉。埃是长度单位，不能用来计算时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃（āi，第一声）是本条目所教的长度单位。"}, {"text": "艾", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。"}, {"text": "癌", "is_correct": false, "explanation": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。"}, {"text": "碍", "is_correct": false, "explanation": "ài（第四声）与 āi（第一声）声调不同，意思是妨碍。"}], "explanations": {"埃": "埃（āi，第一声）是本条目所教的长度单位。", "艾": "ài（第四声）与 āi（第一声）声调不同，意思是艾草。", "癌": "ái（第二声）与 āi（第一声）声调不同，意思是癌症。", "碍": "ài（第四声）与 āi（第一声）声调不同，意思是妨碍。"}, "sentence_index": null, "correct_answer": "埃"}, "level_3": {"options": [{"text": "埃", "is_correct": true, "explanation": "埃是极小的长度单位，与“非常短，眼睛根本看不到”相符，正确。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里远比埃长，与“非常短”矛盾，也不符合“眼睛根本看不到”。"}, {"text": "千米", "is_correct": false, "explanation": "语义：千米同样是很长的距离，与“非常短”矛盾。"}, {"text": "光年", "is_correct": false, "explanation": "搭配：光年是天文距离单位，用来形容极远的距离，与句中“非常短”冲突。"}], "explanations": {"埃": "埃是极小的长度单位，与“非常短，眼睛根本看不到”相符，正确。", "公里": "语义：公里远比埃长，与“非常短”矛盾，也不符合“眼睛根本看不到”。", "千米": "语义：千米同样是很长的距离，与“非常短”矛盾。", "光年": "搭配：光年是天文距离单位，用来形容极远的距离，与句中“非常短”冲突。"}, "sentence_index": 6, "correct_answer": "埃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的电费是五十埃。", "explanation": "这里应该用〈元〉。埃是长度单位，不能用来表示钱款，电费的数目要用元来计。"}, {"text": "这间房的面积是五十埃。", "explanation": "这里应该用〈平方米〉。埃是长度单位，不能直接表示面积。"}, {"text": "这辆车每小时跑三埃。", "explanation": "这里应该用〈千米〉。埃是极小的长度单位，只用于原子、波长等微观距离，汽车行驶的距离要用千米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这层膜的厚度大约是五十个埃。", "corrected_sentence": "这层膜的厚度大约是五十埃。", "error_description": "错误形式：五十个埃；正确形式：五十埃。埃是长度单位，数词后直接接埃，不能再加量词个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种晶体的间距约为埃五。", "corrected_sentence": "这种晶体的间距约为五埃。", "error_description": "错误形式：埃五；正确形式：五埃。数词应放在单位之前，埃是长度单位，要说五埃。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b74ddc-589e-4756-9db3-19db7f16a2ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
