INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "场合是在什么时间、什么地方做事。", "primary_collocate": null, "pronunciation": "chǎng hé", "ipa": "ʈʂʰaŋ˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "你要看时间和场合再说话。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "什么场合穿什么衣服，要想清楚。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的场合不能玩手机。", "target_word": "场合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在图书馆这个场合，大家都要小声说话。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会看场合，从不乱开玩笑。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在面试的场合，穿得太随便不好。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "葬礼是很严肃的场合，不能大笑。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总在不对的场合说不对的话。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家在餐厅这样的场合，可以轻松地聊天。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在课堂这种场合，学生要认真听。", "target_word": "场合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共场合", "label": "复合"}, {"form": "場合", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事、说话所处的时间和地点，要看场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec13897d-af07-46b2-a20a-db12a5ed8bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场合", "is_correct": true, "explanation": "场合：指做事、说话所处的时间和地点，“看时间和场合”是常见说法。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”不是说话前要注意的情况，句子不通。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“看时间和…”后要接情境类的词，“电线”与之不搭配。"}, {"text": "天平", "is_correct": false, "explanation": "语义：“天平”是称重的器具，不是说话时要看的情况。"}], "explanations": {"场合": "场合：指做事、说话所处的时间和地点，“看时间和场合”是常见说法。", "钥匙": "语义：“钥匙”不是说话前要注意的情况，句子不通。", "电线": "搭配：“看时间和…”后要接情境类的词，“电线”与之不搭配。", "天平": "语义：“天平”是称重的器具，不是说话时要看的情况。"}, "sentence_index": 0, "correct_answer": "场合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的场合定在北京。", "explanation": "这里应该用〈地点〉。场合指时间、地点和情况的整体，不能直接作为会议的所在地。"}, {"text": "两队对抗时，场合非常壮观。", "explanation": "这里应该用〈场面〉。场面指眼前的情景，可以说“壮观”；场合指时间、地点和情况，不能说“场合非常壮观”。"}, {"text": "场合里没有人，很安静。", "explanation": "这里应该用〈教室〉。场合不指房间，不能说“场合里没有人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场合", "is_correct": true, "explanation": "场合：指特定的时间、地点和情况，“严肃的场合”是常见说法。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”不是情境，“很严肃的玩具”句子不通。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“严肃的”修饰情境或态度，不修饰“食品”。"}, {"text": "床铺", "is_correct": false, "explanation": "语义：“床铺”是具体的物件，不能说成“很严肃的床铺”。"}], "explanations": {"场合": "场合：指特定的时间、地点和情况，“严肃的场合”是常见说法。", "玩具": "语义：“玩具”不是情境，“很严肃的玩具”句子不通。", "食品": "搭配：“严肃的”修饰情境或态度，不修饰“食品”。", "床铺": "语义：“床铺”是具体的物件，不能说成“很严肃的床铺”。"}, "sentence_index": 6, "correct_answer": "场合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的场合很干净，每天都有人打扫。", "explanation": "这里应该用〈宿舍〉。场合指时间、地点和情况，不是可以打扫的具体住处，不能说“我的场合很干净”。"}, {"text": "场合里人很多，很拥挤。", "explanation": "这里应该用〈车站〉。场合不指可以拥挤的场所，不能说“场合里人很多”。"}, {"text": "这首歌的场合很好听。", "explanation": "这里应该用〈旋律〉。场合指时间、地点和情况，不能用来形容歌曲好听与否，应说“旋律很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每场合都要注意礼貌。", "corrected_sentence": "每个场合都要注意礼貌。", "error_description": "错误：“每场合”。“每”后面接名词要加量词，应说“每个场合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只场合，大家都要守规矩。", "corrected_sentence": "这种场合，大家都要守规矩。", "error_description": "错误：“这只场合”。“只”用于动物等，不能修饰“场合”。应说“这种场合”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
