INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "寄是把信或东西送到别的地方去。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "我想寄一封信。", "target_word": "寄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给我寄了一个包裹。", "target_word": "寄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月都寄钱回家。", "target_word": "寄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书我昨天寄给你了。", "target_word": "寄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这些照片寄到北京。", "target_word": "寄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我寄过很多明信片给朋友。", "target_word": "寄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在邮局寄东西，排了很长的队。", "target_word": "寄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快递员说包裹明天才能寄到。", "target_word": "寄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶从老家寄来了很多水果。", "target_word": "寄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的信我已经寄出去了。", "target_word": "寄", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "寄了", "label": "体标（了）"}, {"form": "寄过", "label": "体标（过）"}, {"form": "寄给", "label": "复合"}], "register": "中性", "sense_fingerprint": "把信件、包裹、钱等通过邮局或快递送到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e17f9927-b1fd-4582-ab98-2acb8fc73a68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94491, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寄", "is_correct": true, "explanation": "正确。寄是把信或东西送到别处去。"}, {"text": "几", "is_correct": false, "explanation": "几（jǐ，第三声）与寄（jì，第四声）声调不同，意思是“几个”。"}, {"text": "机", "is_correct": false, "explanation": "机（jī，第一声）与寄（jì，第四声）声调不同，意思是“机器”。"}, {"text": "集", "is_correct": false, "explanation": "集（jí，第二声）与寄（jì，第四声）声调不同，意思是“集合”。"}, {"text": "气", "is_correct": false, "explanation": "气（qì）与寄（jì）声母不同，q 与 j 不同，意思是“空气”。"}, {"text": "系", "is_correct": false, "explanation": "系（xì）与寄（jì）声母不同，x 与 j 不同，意思是“联系”。"}], "explanations": {"寄": "正确。寄是把信或东西送到别处去。", "几": "几（jǐ，第三声）与寄（jì，第四声）声调不同，意思是“几个”。", "机": "机（jī，第一声）与寄（jì，第四声）声调不同，意思是“机器”。", "集": "集（jí，第二声）与寄（jì，第四声）声调不同，意思是“集合”。", "气": "气（qì）与寄（jì）声母不同，q 与 j 不同，意思是“空气”。", "系": "系（xì）与寄（jì）声母不同，x 与 j 不同，意思是“联系”。"}, "sentence_index": null, "correct_answer": "寄"}, "level_3": {"options": [{"text": "寄", "is_correct": true, "explanation": "正确。寄是把信送出去，符合“我想寄一封信”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，信不能吃。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声演唱，信不能用来唱。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语多是商品，“一封信”不是用来买的东西。"}], "explanations": {"寄": "正确。寄是把信送出去，符合“我想寄一封信”。", "吃": "语义：“吃”指把食物咽下去，信不能吃。", "唱": "语义：“唱”是发声演唱，信不能用来唱。", "买": "搭配：“买”的宾语多是商品，“一封信”不是用来买的东西。"}, "sentence_index": 0, "correct_answer": "寄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天给你寄了一条短信。", "explanation": "这里应该用〈发〉。寄用于信件、包裹等实物，短信是电子消息，要用〈发〉。"}, {"text": "我下班后把钥匙寄进了书包里。", "explanation": "这里应该用〈装〉。寄指通过邮局或快递送到别处，把钥匙放入书包要用〈装〉。"}, {"text": "我每天寄孩子去公园。", "explanation": "这里应该用〈带〉。寄用于信件、包裹等物品，带孩子去公园要用〈带〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94491, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "寄", "is_correct": true, "explanation": "正确。寄是把信或东西送到别处去。"}, {"text": "鸡", "is_correct": false, "explanation": "鸡（jī，第一声）与寄（jì，第四声）声调不同，意思是“鸡”。"}, {"text": "及", "is_correct": false, "explanation": "及（jí，第二声）与寄（jì，第四声）声调不同，意思是“及时”。"}, {"text": "戏", "is_correct": false, "explanation": "戏（xì）与寄（jì）声母不同，x 与 j 不同，意思是“戏剧”。"}, {"text": "积", "is_correct": false, "explanation": "积（jī，第一声）与寄（jì，第四声）声调不同，意思是“积累”。"}], "explanations": {"寄": "正确。寄是把信或东西送到别处去。", "鸡": "鸡（jī，第一声）与寄（jì，第四声）声调不同，意思是“鸡”。", "及": "及（jí，第二声）与寄（jì，第四声）声调不同，意思是“及时”。", "戏": "戏（xì）与寄（jì）声母不同，x 与 j 不同，意思是“戏剧”。", "积": "积（jī，第一声）与寄（jì，第四声）声调不同，意思是“积累”。"}, "sentence_index": null, "correct_answer": "寄"}, "level_3": {"options": [{"text": "寄", "is_correct": true, "explanation": "正确。寄是通过邮局把东西送出去，符合“在邮局寄东西”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，邮局里不会煮东西，与场景冲突。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理坏掉的东西，与在邮局寄东西的场景不合。"}, {"text": "抽", "is_correct": false, "explanation": "搭配：“抽”常接“烟”“奖”“签”，不说“抽东西”。"}], "explanations": {"寄": "正确。寄是通过邮局把东西送出去，符合“在邮局寄东西”。", "煮": "语义：“煮”是烹饪动作，邮局里不会煮东西，与场景冲突。", "修": "语义：“修”指修理坏掉的东西，与在邮局寄东西的场景不合。", "抽": "搭配：“抽”常接“烟”“奖”“签”，不说“抽东西”。"}, "sentence_index": 6, "correct_answer": "寄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把垃圾寄进了垃圾桶。", "explanation": "这里应该用〈扔〉。寄要通过邮局或快递送到别处，丢弃垃圾要用〈扔〉。"}, {"text": "我寄到了一个电话。", "explanation": "这里应该用〈接〉。寄只能用于把信件、包裹等送出去，接到电话是接收，要用〈接〉。"}, {"text": "我把书寄在桌子上。", "explanation": "这里应该用〈放〉。“寄在”表示托付给某人或某处照管，把书摆在桌上只是放置，要用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我寄到妈妈一个包裹。", "corrected_sentence": "我寄给妈妈一个包裹。", "error_description": "介词错误。“寄”后接收件人要用“给”，“到”后接的是地点，不能接“妈妈”这样的人。正确说法是“寄给妈妈一个包裹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包裹我已经寄给上海了。", "corrected_sentence": "这个包裹我已经寄到上海了。", "error_description": "补语错误。表示送达地点要用“寄到”。“寄给”后面应接收件人，不能接地点“上海”。正确说法是“寄到上海”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6fa019c-3f6b-494d-966b-1cded1fc773c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
