INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94497, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "干什么是问别人在做什么，或者打算做什么。", "primary_collocate": null, "pronunciation": "gàn shén me", "ipa": "kan˥˩ ʂən˧˥ mɤ", "syllable_count": 3, "sentences": [{"text": "你在干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你一个人在房间里干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们站在门口干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈在厨房里干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太晚了，你还不睡觉，干什么呢？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在做作业，你呢，在干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着地图，是要干什么？", "target_word": "干什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们一大早去公园干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们围在一起干什么呢？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你周末一般干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "幹什麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语中询问对方正在做什么或打算做什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec13897d-af07-46b2-a20a-db12a5ed8bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干什么", "is_correct": true, "explanation": "干什么：询问对方在做什么，此处语义和语境都吻合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：句子问的是对方在做的事，“谁”问的是人，句意不通。"}, {"text": "怎么", "is_correct": false, "explanation": "搭配：“你在”后不能直接接“怎么”作宾语，句子不成立。"}, {"text": "这样", "is_correct": false, "explanation": "搭配：“你在”后接“这样”不成句。"}], "explanations": {"干什么": "干什么：询问对方在做什么，此处语义和语境都吻合。", "谁": "语义：句子问的是对方在做的事，“谁”问的是人，句意不通。", "怎么": "搭配：“你在”后不能直接接“怎么”作宾语，句子不成立。", "这样": "搭配：“你在”后接“这样”不成句。"}, "sentence_index": 0, "correct_answer": "干什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你喜欢干什么颜色？", "explanation": "这里应该用〈哪种〉。干什么只用于问做什么或为什么，不能修饰“颜色”，应说“你喜欢哪种颜色”。"}, {"text": "这是干什么牌子的手机？", "explanation": "这里应该用〈哪个〉。干什么不能修饰“牌子”，应说“这是哪个牌子的手机”。"}, {"text": "我们往干什么方向走？", "explanation": "这里应该用〈哪个〉。干什么不能修饰“方向”，应说“我们往哪个方向走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干什么", "is_correct": true, "explanation": "干什么：询问目的或行为，此处语义和语境都吻合。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：句子问的是目的，“哪儿”问的是地点，句意不通。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“是要”后不能接“这么”作宾语。"}, {"text": "几时", "is_correct": false, "explanation": "搭配：“是要”后接“几时”不成句。"}], "explanations": {"干什么": "干什么：询问目的或行为，此处语义和语境都吻合。", "哪儿": "语义：句子问的是目的，“哪儿”问的是地点，句意不通。", "这么": "搭配：“是要”后不能接“这么”作宾语。", "几时": "搭配：“是要”后接“几时”不成句。"}, "sentence_index": 6, "correct_answer": "干什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是干什么国家的人？", "explanation": "这里应该用〈哪国〉。干什么不能修饰“国家”，应说“这是哪国的人”。"}, {"text": "他是干什么专业的学生？", "explanation": "这里应该用〈什么〉。干什么不能修饰“专业”，应说“他是什么专业的学生”。"}, {"text": "他是干什么民族的人？", "explanation": "这里应该用〈哪个民族〉。干什么不能修饰“民族”，应说“他是哪个民族的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你们要干什么吗？", "corrected_sentence": "你们要干什么？", "error_description": "错误：句末多用了「吗」。「干什么」已是疑问代词，句末不能再加「吗」。正确：「你们要干什么？」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他到底是要干什么吗？", "corrected_sentence": "他到底是要干什么呢？", "error_description": "错误：句末用了“吗”。“干什么”已是疑问代词，句末不能再用“吗”，应改为“呢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
