INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "询问做什么事情或为什么这样做。", "primary_collocate": null, "pronunciation": "gàn shén me", "ipa": "kan˥˩ ʂən˧˥ mɤ", "syllable_count": 3, "sentences": [{"text": "你找我干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "都十点了，你还出去干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么晚打电话来，是想干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着刀站在门口，到底要干什么？", "target_word": "干什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下这么大的雨，你出去干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你整天不上课，到底都干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你站在那里不动，干什么呢？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没钱还买这么贵的包，干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我又没做错事，你骂我干什么？", "target_word": "干什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都在笑，你哭干什么？", "target_word": "干什么", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "幹什麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语中询问目的或原因，带有不解或不满的语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec13897d-af07-46b2-a20a-db12a5ed8bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干什么", "is_correct": true, "explanation": "干什么：询问目的或原因，此处语义和语境都吻合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：句子问的是找我的目的，“谁”问的是人，句意不通。"}, {"text": "这样", "is_correct": false, "explanation": "搭配：“找我”后接“这样”不成句。"}, {"text": "天平", "is_correct": false, "explanation": "语义：“天平”是称重的器具，不能作为“找我”的对象，句子不通。"}], "explanations": {"干什么": "干什么：询问目的或原因，此处语义和语境都吻合。", "谁": "语义：句子问的是找我的目的，“谁”问的是人，句意不通。", "这样": "搭配：“找我”后接“这样”不成句。", "天平": "语义：“天平”是称重的器具，不能作为“找我”的对象，句子不通。"}, "sentence_index": 0, "correct_answer": "干什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喜欢干什么类型的电影？", "explanation": "这里应该用〈哪种〉。干什么不能修饰“类型”，应说“他喜欢哪种类型的电影”。"}, {"text": "这东西要放在干什么位置？", "explanation": "这里应该用〈哪个〉。干什么不表示位置，应说“这东西要放在哪个位置”。"}, {"text": "我们班是干什么年级的？", "explanation": "这里应该用〈哪个〉。干什么不能修饰“年级”，应说“我们班是哪个年级的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干什么", "is_correct": true, "explanation": "干什么：询问原因，带有不满的语气，此处语义和语境都吻合。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：句子问的是原因，“哪儿”问的是地点，句意不通。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问的是数量，句子问的是为什么不动。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“不动，”后接“这么呢”不成句。"}], "explanations": {"干什么": "干什么：询问原因，带有不满的语气，此处语义和语境都吻合。", "哪儿": "语义：句子问的是原因，“哪儿”问的是地点，句意不通。", "多少": "语义：“多少”问的是数量，句子问的是为什么不动。", "这么": "搭配：“不动，”后接“这么呢”不成句。"}, "sentence_index": 6, "correct_answer": "干什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是干什么品牌的包？", "explanation": "这里应该用〈什么〉。干什么不能修饰“品牌”，应说“这是什么品牌的包”。"}, {"text": "我们应该向干什么方向出发？", "explanation": "这里应该用〈哪边〉。干什么不能修饰“方向”，应说“我们应该向哪边出发”。"}, {"text": "他是干什么学校的老师？", "explanation": "这里应该用〈哪所〉。干什么不能修饰“学校”，应说“他是哪所学校的老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么晚了，你还不睡，干什么吗？", "corrected_sentence": "这么晚了，你还不睡，干什么呢？", "error_description": "错误：“干什么”后用了“吗”。“干什么”已是疑问代词，句末不能再加“吗”，应说“干什么呢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都在等你，你干什么吗？", "corrected_sentence": "大家都在等你，你干什么呢？", "error_description": "错误：句末用了“吗”。“干什么”已是疑问代词，句末不能再加“吗”，应说“你干什么呢？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某机构、国家或组织成立的日期。", "primary_collocate": null, "pronunciation": "jiàn lì shí jiān", "ipa": "tɕjɛn˥˩ li˥˩ ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "这所大学的建立时间是一九一二年。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这家公司的建立时间是什么时候？", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新中国的建立时间是一九四九年十月一日。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的建立时间比你们早十年。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“这个国家的建立时间你知道吗？”", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个银行的建立时间很早，有一百多年了。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着这家医院的建立时间。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个公司的建立时间一样，都是二〇〇〇年。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在表格里写下了小组的建立时间。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的建立时间不长，只有五十年。", "target_word": "建立时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "建立時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机构、国家、组织成立的日期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建立时间", "is_correct": true, "explanation": "「建立时间」指机构或国家成立的日期，与「一九一二年」相符。"}, {"text": "毕业时间", "is_correct": false, "explanation": "语义：「毕业时间」指学生结业的时候，不能用来说学校的成立年份。"}, {"text": "校龄", "is_correct": false, "explanation": "搭配：「校龄」说的是办学了多少年，是年数，不能与具体年份「一九一二年」搭配。"}, {"text": "学费", "is_correct": false, "explanation": "语义：「学费」是学生交的钱，不是时间，句子说的是某个年份。"}], "explanations": {"建立时间": "「建立时间」指机构或国家成立的日期，与「一九一二年」相符。", "毕业时间": "语义：「毕业时间」指学生结业的时候，不能用来说学校的成立年份。", "校龄": "搭配：「校龄」说的是办学了多少年，是年数，不能与具体年份「一九一二年」搭配。", "学费": "语义：「学费」是学生交的钱，不是时间，句子说的是某个年份。"}, "sentence_index": 0, "correct_answer": "建立时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的建立时间是三月五日。", "explanation": "「建立时间」只用于机构、国家、组织的成立日期，个人的生日应说〈生日〉。"}, {"text": "我们下周再建立时间见面吧。", "explanation": "这里应说〈安排时间〉，指约定见面的时间；「建立时间」只指机构、国家的成立日期，不能用来指安排。"}, {"text": "这场演出的建立时间是晚上七点。", "explanation": "演出的开始时间应说〈开演时间〉；「建立时间」指机构或国家的成立日期，不用于演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建立时间", "is_correct": true, "explanation": "「建立时间」指医院成立的日期，书上记载的就是这个。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指人或动物的身体重量，医院没有体重，不能这样说。"}, {"text": "班级", "is_correct": false, "explanation": "语义：「班级」属于学校，医院不设班级，句子说的是这家医院。"}, {"text": "校长", "is_correct": false, "explanation": "语义：「校长」是学校的负责人，医院的负责人应说「院长」。"}], "explanations": {"建立时间": "「建立时间」指医院成立的日期，书上记载的就是这个。", "体重": "语义：「体重」指人或动物的身体重量，医院没有体重，不能这样说。", "班级": "语义：「班级」属于学校，医院不设班级，句子说的是这家医院。", "校长": "语义：「校长」是学校的负责人，医院的负责人应说「院长」。"}, "sentence_index": 6, "correct_answer": "建立时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的建立时间是二十八岁。", "explanation": "人的岁数应说〈年龄〉；「建立时间」只指机构、国家的成立日期。"}, {"text": "这次考试的建立时间是两个小时。", "explanation": "考试持续多久应说〈时长〉；「建立时间」指机构、国家的成立日期，不用于表示时间的长短。"}, {"text": "这次会议的建立时间是下午两点。", "explanation": "会议的开始时间应说〈开始时间〉；「建立时间」不用于会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所中学的建立时间是一百年。", "corrected_sentence": "这所中学的建立时间是一九五〇年。", "error_description": "「建立时间」指成立的日期，后面应接具体年份（如「一九五〇年」），不能接「一百年」这样的时间长度。说办了多少年应该用别的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的建立时间了是一九〇三年。", "corrected_sentence": "这所学校的建立时间是一九〇三年。", "error_description": "「建立时间」是名词，后面不能直接加动态助词「了」。应为「这所学校的建立时间是一九〇三年」，「建立时间了」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
