INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94501, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "得便是有空的时候，顺手去做。", "primary_collocate": null, "pronunciation": "dé biàn", "ipa": "tɤ˧˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "您得便时，请帮我带本书来。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您得便时，烦请回电相告。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得便请把这封信寄出去。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去超市时，得便替你买些水果。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得便即来探望祖母。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师得便会审阅同学们的作业。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您下次路过邮局，得便代为寄出此包裹。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得便的话，请以短信相告。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得便会将书归还图书馆。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您得便前往银行一趟，代为取款。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "有空时顺手去做某件小事（多用于请求、嘱托）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94501, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得便", "is_correct": true, "explanation": "正确：得便表示有空时顺手去做，与请人帮忙的语境相符。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与请人帮忙带书的请求相矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急迫，与“有空时”的从容语境冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与请对方帮忙的语气不符。"}], "explanations": {"得便": "正确：得便表示有空时顺手去做，与请人帮忙的语境相符。", "不必": "语义：“不必”表示没有必要，与请人帮忙带书的请求相矛盾。", "赶紧": "语义：“赶紧”表示急迫，与“有空时”的从容语境冲突。", "偶尔": "语义：“偶尔”表示不常发生，与请对方帮忙的语气不符。"}, "sentence_index": 0, "correct_answer": "得便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我得便专门跑了一趟超市，替你买些水果。", "explanation": "这里应该用〈特意〉。得便表示顺手、趁方便，与“专门跑一趟”矛盾。"}, {"text": "我得便跟你吵了一架。", "explanation": "语义：“得便”只用于顺手去做的小事，不能用于吵架这类冲突。"}, {"text": "我得便一下子考了满分。", "explanation": "语义：“得便”修饰顺手去做的动作，不能用来说明考试得分这类结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得便", "is_correct": true, "explanation": "正确：得便表示趁方便时顺手去做，与“路过邮局”的语境相符。"}, {"text": "曾经", "is_correct": false, "explanation": "搭配：“曾经”指过去，与“下次”的将来时间冲突。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“下次”指向将来的时间冲突。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，与“下次”的将来时间不搭配。"}], "explanations": {"得便": "正确：得便表示趁方便时顺手去做，与“路过邮局”的语境相符。", "曾经": "搭配：“曾经”指过去，与“下次”的将来时间冲突。", "从不": "语义：“从不”表示从来没有，与“下次”指向将来的时间冲突。", "已经": "搭配：“已经”表示已经完成，与“下次”的将来时间不搭配。"}, "sentence_index": 6, "correct_answer": "得便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火灾了，你得便去叫消防车。", "explanation": "这里应该用〈赶紧〉。得便表示有空时顺手，紧急情况下不能用。"}, {"text": "我得便生气地摔了门。", "explanation": "语义：“得便”表示趁方便、从容地做事，不能与“生气地摔门”的激动情绪搭配。"}, {"text": "医生让他得便住进了重症监护室。", "explanation": "语义：“得便”表示顺手、趁方便的小事，不能用于住进重症监护室这类紧急治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你很得便时，记得把钥匙带上。", "corrected_sentence": "你得便时，记得把钥匙带上。", "error_description": "副词错误：“得便”是副词，前面不能加“很”修饰，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很得便把花浇了。", "corrected_sentence": "他得便把花浇了。", "error_description": "副词错误：“得便”是副词，前面不能加“很”修饰，应去掉“很”，写作“他得便把花浇了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
