INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94502, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "趁方便的时候；得到方便。", "primary_collocate": null, "pronunciation": "dé biàn", "ipa": "tɤ˧˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我想得便去看看那位老朋友。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得便即返乡一趟。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您得便来敝公司一叙。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张经理出差路过上海，得便拜访了老同学。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们得便再议此事。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算得便去书店买几本书。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您得便时，请到寒舍用餐。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得便即为花卉浇水。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机会的话，我得便去拜访您。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得便请到我办公室来一趟。", "target_word": "得便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "趁着方便、有机会时（去拜访、联系等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得便", "is_correct": true, "explanation": "正确：得便表示趁方便的时候，与想去探望老朋友的语境相符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“我想去”的意愿冲突。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示完成，与“想去”的将来意愿不搭配。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“想去看看”的意愿矛盾。"}], "explanations": {"得便": "正确：得便表示趁方便的时候，与想去探望老朋友的语境相符。", "从不": "语义：“从不”表示从来没有，与“我想去”的意愿冲突。", "已经": "搭配：“已经”表示完成，与“想去”的将来意愿不搭配。", "不必": "语义：“不必”表示没有必要，与“想去看看”的意愿矛盾。"}, "sentence_index": 0, "correct_answer": "得便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我得便从上海飞来看你。", "explanation": "这里应该用〈特意〉。得便表示趁方便顺手去做，不能用于专为某事而来。"}, {"text": "听到火警，他得便跑出了教室。", "explanation": "这里应该用〈立刻〉。火警需要马上行动，不能用“得便”这种从容的说法。"}, {"text": "张经理得便把车撞坏了。", "explanation": "语义：“得便”表示趁方便做的顺手之事，不能用于撞车这类意外事故。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得便", "is_correct": true, "explanation": "正确：得便表示有空时顺手去做，与热情邀请对方来家里吃饭的语境相符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与邀请对方来用餐的语境相矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急迫，与轻松的邀请语境冲突。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”表示马上，不能与“时”组合，也不符合“有空时”的邀请。"}], "explanations": {"得便": "正确：得便表示有空时顺手去做，与热情邀请对方来家里吃饭的语境相符。", "从不": "语义：“从不”表示从来没有，与邀请对方来用餐的语境相矛盾。", "赶紧": "语义：“赶紧”表示急迫，与轻松的邀请语境冲突。", "立即": "搭配：“立即”表示马上，不能与“时”组合，也不符合“有空时”的邀请。"}, "sentence_index": 6, "correct_answer": "得便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他得便把我的电脑摔坏了。", "explanation": "语义：“得便”表示趁方便顺手去做，不能用于摔坏别人东西这类意外行为。"}, {"text": "我得便大哭了一场。", "explanation": "语义：“得便”修饰从容、顺手的动作，不能用于大哭这类强烈的情绪表现。"}, {"text": "这场火灾，你得便快去报警吧。", "explanation": "这里应该用〈赶紧〉。火灾需要马上行动，不能用“得便”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
