INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "忽略是没有看到或没有想到。", "primary_collocate": null, "pronunciation": "hū lüè", "ipa": "xu˥ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "我忽略了门口的小台阶，差点摔倒。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看报告时，他忽略了最后一页。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都忽略了这个小细节。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作业时，我忽略了一个数字。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忽略了天气，没带伞。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太着急，忽略了价格标签。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只看大字，忽略了下面的小字。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划时，我们忽略了时间问题。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忽略了路上的红灯。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天忽略了一条重要的通知。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忽略了", "label": "体标"}, {"form": "忽略过", "label": "体标"}], "register": "中性", "sense_fingerprint": "一时没看到或没想到某个细节、情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：台阶不能被吃，“吃了台阶”不成立。"}, {"text": "忽略", "is_correct": true, "explanation": "忽略：没有看到台阶，所以差点摔倒，符合句意。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”指悬挂物品，不能用于台阶这种固定的建筑。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”接计划、机会，不接具体的台阶。"}], "explanations": {"吃": "语义：台阶不能被吃，“吃了台阶”不成立。", "忽略": "忽略：没有看到台阶，所以差点摔倒，符合句意。", "挂": "语义：“挂”指悬挂物品，不能用于台阶这种固定的建筑。", "放弃": "搭配：“放弃”接计划、机会，不接具体的台阶。"}, "sentence_index": 0, "correct_answer": "忽略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个字一个字地忽略了这份报告，连标点都没放过。", "explanation": "这里应该用〈检查〉。忽略表示没看到或没想到，与“一个字一个字地”“连标点都没放过”矛盾。"}, {"text": "我认真检查了一遍，却仔细地忽略了那个数字。", "explanation": "这里应该用〈注意到〉。忽略表示没看到或没想到，不能与“认真检查”“仔细地”搭配。"}, {"text": "我们认真忽略了每一份合同条款，确保一个也不漏掉。", "explanation": "这里应该用〈核对〉。忽略表示没看到，与“认真”“确保一个也不漏掉”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注视", "is_correct": false, "explanation": "语义：“注视”是专注地看，与“他只看大字”的语境矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲、台词，不接“小字”。"}, {"text": "忽略", "is_correct": true, "explanation": "忽略：没有看到下面的小字，与“只看大字”的语境相合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是擦拭、擦掉，与“只看”的动作不相容。"}], "explanations": {"注视": "语义：“注视”是专注地看，与“他只看大字”的语境矛盾。", "唱": "搭配：“唱”接歌曲、台词，不接“小字”。", "忽略": "忽略：没有看到下面的小字，与“只看大字”的语境相合。", "擦": "语义：“擦”是擦拭、擦掉，与“只看”的动作不相容。"}, "sentence_index": 6, "correct_answer": "忽略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真地忽略了这个细节，后来还去仔细查看了它。", "explanation": "这里应该用〈仔细查看〉。忽略表示没看到，与“认真地”“仔细查看”矛盾。"}, {"text": "他仔细地忽略了这一页，把每个字都读了一遍。", "explanation": "这里应该用〈阅读〉。忽略表示没看到，与“仔细地”“把每个字都读了一遍”矛盾。"}, {"text": "我们精心忽略了这份报告的每一个数字，确保一个也不漏掉。", "explanation": "这里应该用〈核对〉。忽略表示没看到，与“精心”“确保一个也不漏掉”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一时忽略了掉桌上的那把钥匙。", "corrected_sentence": "他一时忽略掉了桌上的那把钥匙。", "error_description": "“掉”应紧跟动词，说“忽略掉了”，不能说“忽略了掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾经忽略了过这个细节。", "corrected_sentence": "我曾经忽略过这个细节。", "error_description": "错误：动词“忽略”后面不能同时用“了”和“过”两个体标。正确：说“忽略过”，只用“过”表示经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
