INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有注意到；不放在心上。", "primary_collocate": null, "pronunciation": "hū lüè", "ipa": "xu˥ lɥe˥˩", "syllable_count": 2, "sentences": [{"text": "你不能忽略孩子的感受。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是忽略别人的意见。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小问题千万不要忽略。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，他忽略了家人。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要忽略身体发出的信号。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忽略了老师的提醒，结果考试出错。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能忽略安全问题。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友的话忽略了。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人忽略早餐的重要性。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙了，忽略了妻子的生日。", "target_word": "忽略", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忽略了", "label": "体标"}, {"form": "忽略过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对重要的人或事不重视、没放在心上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”需要食物等可吞咽的对象，“感受”不能被吃。"}, {"text": "忽略", "is_correct": true, "explanation": "忽略：不重视、不放在心上，与“不能……孩子的感受”的语境相合。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭具体的表面，不能用于“感受”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”针对具体的物体，不能用于心理上的“感受”。"}], "explanations": {"吃": "语义：“吃”需要食物等可吞咽的对象，“感受”不能被吃。", "忽略": "忽略：不重视、不放在心上，与“不能……孩子的感受”的语境相合。", "擦": "语义：“擦”指擦拭具体的表面，不能用于“感受”。", "洗": "语义：“洗”针对具体的物体，不能用于心理上的“感受”。"}, "sentence_index": 0, "correct_answer": "忽略"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把老板的每封邮件都忽略了，每封都仔细读了三遍。", "explanation": "这里应该用〈认真阅读〉。忽略是不放在心上，与“每封都仔细读了三遍”矛盾。"}, {"text": "他一直忽略老师的建议，每一条都认真照着做了。", "explanation": "这里应该用〈重视〉。忽略是不放在心上，与“每一条都认真照着做了”矛盾。"}, {"text": "这个问题很严重，我们却马上忽略它，并召集全员开会讨论。", "explanation": "这里应该用〈重视〉。忽略是不放在心上，与“召集全员开会讨论”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理具体的场所，不能用于“安全问题”。"}, {"text": "忽略", "is_correct": true, "explanation": "忽略：不重视，与“不能”搭配，表示不能不重视安全。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于食物，安全问题无法被煮。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”接颜料、药膏等，不说涂“问题”。"}], "explanations": {"打扫": "语义：“打扫”指清理具体的场所，不能用于“安全问题”。", "忽略": "忽略：不重视，与“不能”搭配，表示不能不重视安全。", "煮": "语义：“煮”用于食物，安全问题无法被煮。", "涂": "搭配：“涂”接颜料、药膏等，不说涂“问题”。"}, "sentence_index": 6, "correct_answer": "忽略"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他精心忽略了生病的父亲，每天都亲自照顾。", "explanation": "这里应该用〈照顾〉。忽略是不理会、不放在心上，与“精心”“亲自照顾”矛盾。"}, {"text": "他一直忽略这次晋升的机会，却努力争取到了它。", "explanation": "这里应该用〈争取〉。忽略是不放在心上，与“努力争取到”矛盾。"}, {"text": "这份合同条款我们逐条忽略，一条都没有放过。", "explanation": "这里应该用〈逐条核对〉。忽略是不放在心上，与“一条都没有放过”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我忽略了过你的感受，对不起。", "corrected_sentence": "我忽略过你的感受，对不起。", "error_description": "错误：动词“忽略”后面不能同时用“了”和“过”两个体标。正确：说“忽略过”，只用“过”表示经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些小事我都忽略了掉。", "corrected_sentence": "这些小事我都忽略掉了。", "error_description": "“掉”应紧跟动词，说“忽略掉了”，不能说“忽略了掉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
