INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94505, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94505, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "截图是把手机或电脑屏幕上的样子拍成一张图片。", "primary_collocate": null, "pronunciation": "jié tú", "ipa": "tɕjɛ˧˥ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "这张截图不太清楚。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我发了一张截图。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把截图发到我的邮箱。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手机里有很多旧截图。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看这张截图，价格已经变了。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有那条消息的截图？", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要看付款的截图。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张截图上有我的名字。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把截图发给了朋友。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "截图太大，发不出去。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}], "register": "口语", "sense_fingerprint": "名词：屏幕内容保存下来的那张图片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "搭配：量词“张”不用于动物，应说“只”或“头”。"}, {"text": "截图", "is_correct": true, "explanation": "截图：指屏幕内容保存的图片，可以用“张”来计量，且能“不清楚”。"}, {"text": "香蕉", "is_correct": false, "explanation": "搭配：香蕉的量词是“根”或“串”，不说“张”。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：河流用量词“条”，不说“这张河流”。"}], "explanations": {"老虎": "搭配：量词“张”不用于动物，应说“只”或“头”。", "截图": "截图：指屏幕内容保存的图片，可以用“张”来计量，且能“不清楚”。", "香蕉": "搭配：香蕉的量词是“根”或“串”，不说“张”。", "河流": "搭配：河流用量词“条”，不说“这张河流”。"}, "sentence_index": 0, "correct_answer": "截图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张截图是老师用粉笔画在黑板上的。", "explanation": "这里应该用〈画〉。截图是屏幕画面的保存，不是用粉笔画在黑板上的。"}, {"text": "这张截图是我在山上用相机拍的。", "explanation": "这里应该用〈照片〉。截图来自屏幕内容，不是用相机拍摄的。"}, {"text": "我昨天把那张截图放进冰箱里冷藏了。", "explanation": "这里的〈截图〉被当作食物，不能冷藏；截图指屏幕内容保存成的图片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生日", "is_correct": false, "explanation": "语义：付款的对象不可能是生日。"}, {"text": "截图", "is_correct": true, "explanation": "截图：付款后的截图可以作为凭证给老师看。"}, {"text": "芒果", "is_correct": false, "explanation": "搭配：“付款”的对象是账单、金额，不说付款的芒果。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不能作为付款的凭证。"}], "explanations": {"生日": "语义：付款的对象不可能是生日。", "截图": "截图：付款后的截图可以作为凭证给老师看。", "芒果": "搭配：“付款”的对象是账单、金额，不说付款的芒果。", "地铁": "语义：地铁是交通工具，不能作为付款的凭证。"}, "sentence_index": 6, "correct_answer": "截图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张截图是他在厨房里用面粉做出来的。", "explanation": "这里应该用〈面塑〉。截图是屏幕画面的保存，不是用面粉捏成的。"}, {"text": "这幅截图是他用画笔画的。", "explanation": "这里应该用〈画〉。截图来自屏幕，不是用画笔画出来的。"}, {"text": "这张截图是他用毛笔写在宣纸上的。", "explanation": "这里应该用〈书法作品〉。截图来自屏幕，不是用毛笔写在宣纸上的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这只截图保存在相册里。", "corrected_sentence": "我把这张截图保存在相册里。", "error_description": "“只”用于动物，截图是平面图片，量词应用“张”，这里误用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板让我发一首截图给他。", "corrected_sentence": "老板让我发一张截图给他。", "error_description": "“首”用于诗歌、歌曲，截图是平面图片，量词应用“张”，这里误用“首”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
