INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将屏幕上显示的内容截取保存成图片。", "primary_collocate": null, "pronunciation": "jié tú", "ipa": "tɕjɛ˧˥ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "我想把这个页面截图，发给朋友。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上怎么截图？我不会。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先截图，再发给我吧。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王看到有趣的聊天内容，马上截图保存。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把成绩单截图发到群里。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件不让用户截图。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按了两个键，就能截图。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了截图，现在找不到那条消息了。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付款成功后，请截图留作证明。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想截图的话，先打开这个页面。", "target_word": "截图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "截了图", "label": "完成体"}, {"form": "截过图", "label": "经历体"}], "register": "口语", "sense_fingerprint": "动作：把屏幕上的内容保存为图片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关闭", "is_correct": false, "explanation": "语义：页面关闭后就无法再发给朋友，与句意矛盾。"}, {"text": "截图", "is_correct": true, "explanation": "截图：把页面内容保存为图片，之后才能发给朋友。"}, {"text": "删除", "is_correct": false, "explanation": "语义：内容已删除，就没有可发给朋友的东西。"}, {"text": "登录", "is_correct": false, "explanation": "搭配：“登录”接账号、系统，不接“页面”。"}], "explanations": {"关闭": "语义：页面关闭后就无法再发给朋友，与句意矛盾。", "截图": "截图：把页面内容保存为图片，之后才能发给朋友。", "删除": "语义：内容已删除，就没有可发给朋友的东西。", "登录": "搭配：“登录”接账号、系统，不接“页面”。"}, "sentence_index": 0, "correct_answer": "截图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用相机截图留念。", "explanation": "这里应该用〈拍照〉。截图是把屏幕内容保存为图片，不能用相机拍摄人或实物。"}, {"text": "我在网上截图，一口气听完了整张专辑。", "explanation": "这里应该用〈听〉。截图只能保存屏幕画面，不能用来听音乐。"}, {"text": "他在纸上截图了一幅画。", "explanation": "这里应该用〈画〉。截图针对屏幕内容，不能在纸上截图。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗澡", "is_correct": false, "explanation": "语义：按两个键无法完成洗澡。"}, {"text": "截图", "is_correct": true, "explanation": "截图：按下按键就能截取屏幕内容，与句意相合。"}, {"text": "缝衣服", "is_correct": false, "explanation": "语义：按键无法完成缝衣服这类手工活动。"}, {"text": "更换", "is_correct": false, "explanation": "配价：“更换”后需要宾语，句中缺少宾语。"}], "explanations": {"洗澡": "语义：按两个键无法完成洗澡。", "截图": "截图：按下按键就能截取屏幕内容，与句意相合。", "缝衣服": "语义：按键无法完成缝衣服这类手工活动。", "更换": "配价：“更换”后需要宾语，句中缺少宾语。"}, "sentence_index": 6, "correct_answer": "截图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用手机截图，把声音都保存下来。", "explanation": "这里应该用〈录音〉。截图只能保存屏幕画面，不能保存声音。"}, {"text": "我用扫描仪截图了合同。", "explanation": "这里应该用〈扫描〉。扫描仪把纸质文件变成电子图片，截图只针对屏幕。"}, {"text": "他用手机截图，给整场比赛配上了背景音乐。", "explanation": "这里应该用〈剪辑〉。截图只能得到静态画面，无法配上背景音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他截图了一张图，发到了群里。", "corrected_sentence": "他截了一张图，发到了群里。", "error_description": "离合词错误：“截图”已含“图”这一宾语，后面不能再加“图”，应说“截了一张图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你先截图着，再发给我吧。", "corrected_sentence": "你先截图，再发给我吧。", "error_description": "体标误用：“截图”是一次完成的动作，不能加表示持续的“着”，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
