INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "击败是比赛或打仗时赢了别人。", "primary_collocate": null, "pronunciation": "jī bài", "ipa": "tɕi˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "中国队击败了日本队。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在决赛中击败了对手。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队昨天击败了最强的队。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王击败了去年的冠军。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队击败了入侵的敌人。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个年轻选手击败过很多高手。", "target_word": "击败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用三比一击败了客队。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我希望下次能击败他。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老虎队击败了狮子队，进了决赛。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟在象棋比赛中击败了爸爸。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "击败了", "label": "体标（完成）"}, {"form": "击败过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "比赛或战争中赢了对手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "击败", "is_correct": true, "explanation": "“击败”指在比赛或战争中胜过对方，与“中国队”“日本队”的比赛语境搭配。"}, {"text": "邀请", "is_correct": false, "explanation": "语义：“邀请”指请对方来做客或参加活动，与两队比赛胜负的语境不符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、方案，不能直接用于一支队伍。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”指以礼相待，与比赛胜负的语境不符。"}], "explanations": {"击败": "“击败”指在比赛或战争中胜过对方，与“中国队”“日本队”的比赛语境搭配。", "邀请": "语义：“邀请”指请对方来做客或参加活动，与两队比赛胜负的语境不符。", "讨论": "搭配：“讨论”的对象是问题、方案，不能直接用于一支队伍。", "欢迎": "语义：“欢迎”指以礼相待，与比赛胜负的语境不符。"}, "sentence_index": 0, "correct_answer": "击败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子弹击败了目标。", "explanation": "这里应该用〈击中〉。“击败”指在比赛或战争中胜过对手，子弹射中目标要用“击中”。"}, {"text": "他用力击败了地上的灰尘，弄得满屋都是。", "explanation": "这里应该用〈扫〉。“击败”指在比赛或战争中胜过对手，清扫地上的灰尘要用“扫”。"}, {"text": "他用力击败那面鼓。", "explanation": "这里应该用〈击打〉。“击败”的对象必须是对手或敌人，敲鼓要用“击打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "击败", "is_correct": true, "explanation": "“击败”指胜过对方，与“三比一”的比分和比赛语境搭配。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”指表示庆贺，与比分“三比一”的胜负语境不符。"}, {"text": "观察", "is_correct": false, "explanation": "搭配：“观察”的对象可以是人，但“用三比一观察”不通，与比分语境不符。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰”指妨碍他人，与比分语境不符。"}], "explanations": {"击败": "“击败”指胜过对方，与“三比一”的比分和比赛语境搭配。", "祝贺": "语义：“祝贺”指表示庆贺，与比分“三比一”的胜负语境不符。", "观察": "搭配：“观察”的对象可以是人，但“用三比一观察”不通，与比分语境不符。", "打扰": "语义：“打扰”指妨碍他人，与比分语境不符。"}, "sentence_index": 6, "correct_answer": "击败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "炸弹击败了那座大桥。", "explanation": "这里应该用〈击毁〉。“击败”用于在竞争中胜过对手，把大桥炸毁要用“击毁”。"}, {"text": "重锤击败了那块玻璃。", "explanation": "这里应该用〈击碎〉。“击败”的对象是对手，玻璃被打碎要用“击碎”。"}, {"text": "妈妈在厨房击败了几个鸡蛋，准备做饭。", "explanation": "这里应该用〈打〉。“击败”的对象是对手或敌人，打鸡蛋要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支球队曾经击败了过所有对手。", "corrected_sentence": "这支球队曾经击败过所有对手。", "error_description": "“了”和“过”不能同时用在动词后面：表示曾经有过的经历用“击败过”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个队在上赛季击败着三支强队。", "corrected_sentence": "这个队在上赛季击败了三支强队。", "error_description": "“着”错误，正确是“了”。“着”表示动作正在进行或状态持续；描述已经完成的比赛结果要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
