INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94512, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打败对方。", "primary_collocate": null, "pronunciation": "jī bài", "ipa": "tɕi˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司击败了所有对手。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在选举中击败了对手。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的新手机击败了别的牌子。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用新办法击败了老对手。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李在网络游戏里击败了我。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小店击败了大超市，生意很好。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她击败了三十个人，得到这份工作。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想击败对方，可是没有成功。", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能击败这个电脑棋手吗？", "target_word": "击败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人击败过很多年轻人。", "target_word": "击败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "击败了", "label": "体标（完成）"}, {"form": "击败过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "在竞争中打败对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "击败", "is_correct": true, "explanation": "“击败”指在竞争中胜过对手，与“公司”“对手”的竞争语境搭配。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、东西，不能说“修理所有对手”。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”指选取，不表示在竞争中胜过对方，与语境不符。"}, {"text": "辱骂", "is_correct": false, "explanation": "语义：“辱骂”指侮辱谩骂，不表示在竞争中胜过对方，与语境不符。"}], "explanations": {"击败": "“击败”指在竞争中胜过对手，与“公司”“对手”的竞争语境搭配。", "修理": "搭配：“修理”的对象是机器、东西，不能说“修理所有对手”。", "挑选": "语义：“挑选”指选取，不表示在竞争中胜过对方，与语境不符。", "辱骂": "语义：“辱骂”指侮辱谩骂，不表示在竞争中胜过对方，与语境不符。"}, "sentence_index": 0, "correct_answer": "击败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "球击败了门柱。", "explanation": "这里应该用〈击中〉。“击败”指在竞争中胜过对手，球打到门柱要用“击中”。"}, {"text": "一阵大风击败了那棵大树。", "explanation": "这里应该用〈击倒〉。“击败”针对对手，大树被风吹倒要用“击倒”。"}, {"text": "重锤击败了冰面。", "explanation": "这里应该用〈击碎〉。“击败”的对象是对手，冰面被打碎要用“击碎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "击败", "is_correct": true, "explanation": "“击败”指在竞争中胜过对手，与“得到这份工作”的竞争语境搭配。"}, {"text": "款待", "is_correct": false, "explanation": "语义：“款待”指热情招待，与“得到这份工作”的竞争语境不符。"}, {"text": "探望", "is_correct": false, "explanation": "语义：“探望”指看望，与求职竞争的语境不符。"}, {"text": "监视", "is_correct": false, "explanation": "语义：“监视”指暗中察看，与求职竞争的语境不符。"}], "explanations": {"击败": "“击败”指在竞争中胜过对手，与“得到这份工作”的竞争语境搭配。", "款待": "语义：“款待”指热情招待，与“得到这份工作”的竞争语境不符。", "探望": "语义：“探望”指看望，与求职竞争的语境不符。", "监视": "语义：“监视”指暗中察看，与求职竞争的语境不符。"}, "sentence_index": 6, "correct_answer": "击败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "炸弹击败了很多房子。", "explanation": "这里应该用〈击毁〉。“击败”用于在竞争中胜过对手，房子被炸毁要用“击毁”。"}, {"text": "那首老歌击败过很多听众。", "explanation": "这里应该用〈打动〉。“击败”指胜过对手，歌曲让听众感动要用“打动”。"}, {"text": "工人用锤子击败了很多石头。", "explanation": "这里应该用〈砸碎〉。“击败”的对象是对手，把石头打碎要用“砸碎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店凭低价击败了过所有竞争者。", "corrected_sentence": "这家店凭低价击败过所有竞争者。", "error_description": "“了”和“过”不能同时用在动词后面：表示曾经有过的经历用“击败过”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于那个难缠的对手击败了。", "corrected_sentence": "他终于把那个难缠的对手击败了。", "error_description": "漏用“把”：“把”字句中，“把”加宾语要放在动词前，应说“他终于把那个难缠的对手击败了”，不能省去“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
