INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94513, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收藏是把喜欢的东西好好地放起来。", "primary_collocate": null, "pronunciation": "shōu cáng", "ipa": "ʂoʊ˥ tsʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶把我小时候的衣服都收藏着。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把爸爸送的钢笔好好收藏起来。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一直收藏着这封信。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把孩子的第一双鞋收藏了很多年。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片我想好好收藏。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把这些小礼物都收藏在盒子里。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他舍不得用这支笔，只想收藏。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的画，妈妈都替我收藏着。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧围巾很有意义，我要收藏一辈子。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收藏了一朵朋友送的干花。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收藏了", "label": "完成体"}, {"form": "收藏着", "label": "持续体"}, {"form": "收藏过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动作：把喜爱的、有纪念意义的东西珍惜地存放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收藏", "is_correct": true, "explanation": "收藏：珍爱地保存，符合“都……着”和小时候的衣服的语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢掉，与“小时候的衣服要留下”的语境相反。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧是毁掉，与“都……着”表示保存的语境冲突。"}, {"text": "送", "is_correct": false, "explanation": "语义：送是把东西给别人，“都送着”不能表示把衣服留在身边保存。"}], "explanations": {"收藏": "收藏：珍爱地保存，符合“都……着”和小时候的衣服的语境。", "扔": "语义：扔是丢掉，与“小时候的衣服要留下”的语境相反。", "烧": "语义：烧是毁掉，与“都……着”表示保存的语境冲突。", "送": "语义：送是把东西给别人，“都送着”不能表示把衣服留在身边保存。"}, "sentence_index": 0, "correct_answer": "收藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把乱七八糟的房间收藏得很干净。", "explanation": "这里应该用〈收拾〉。收藏指把珍爱的东西好好存起来，整理房间要用收拾。"}, {"text": "他收藏了一只流浪猫。", "explanation": "这里应该用〈收养〉。收藏的对象是喜爱的物品，不能用于活的动物，要用收养。"}, {"text": "他把穿旧的袜子收藏在衣柜里。", "explanation": "这里应该用〈放〉。收藏的对象要有珍爱或价值，旧袜子不值得珍藏，只需放进衣柜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收藏", "is_correct": true, "explanation": "收藏：舍不得用，只想好好保存，符合句意。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：摔指使物品跌落损坏，不能用“只想摔”来表达对心爱之物的态度。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：破坏是损毁，与“舍不得用”的心态矛盾。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：浪费与“舍不得用”正相反，不符合句意。"}], "explanations": {"收藏": "收藏：舍不得用，只想好好保存，符合句意。", "摔": "搭配：摔指使物品跌落损坏，不能用“只想摔”来表达对心爱之物的态度。", "破坏": "语义：破坏是损毁，与“舍不得用”的心态矛盾。", "浪费": "语义：浪费与“舍不得用”正相反，不符合句意。"}, "sentence_index": 6, "correct_answer": "收藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把厨房收藏得很整齐。", "explanation": "这里应该用〈收拾〉。收藏指把珍爱的东西存起来，整理厨房要用收拾。"}, {"text": "这家公司收藏了一个工厂。", "explanation": "这里应该用〈收购〉。收藏是保存心爱之物，买下企业要用收购。"}, {"text": "警察收藏了那批违禁品。", "explanation": "这里应该用〈没收〉。收藏带有珍爱的意思，查获违禁品要用没收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把旧照片收藏上来了。", "corrected_sentence": "妈妈把旧照片收藏起来了。", "error_description": "错误：补语“上来”与“收藏”搭配不当。正确：把+宾语+动词+“起来”，说“收藏起来了”，表示把东西好好存放起来。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸一直收藏着了那枚戒指。", "corrected_sentence": "爸爸一直收藏着那枚戒指。", "error_description": "错误：“收藏”表示持续状态时用“着”，“着了”不能这样搭配。正确：一直收藏着那枚戒指。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
