INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把喜爱或有价值的东西收集并保存起来。", "primary_collocate": null, "pronunciation": "shōu cáng", "ipa": "ʂoʊ˥ tsʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他喜欢收藏旧邮票。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷收藏了很多老钱币。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家博物馆收藏着一千多幅画。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友收藏过很多外国硬币。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了十年收藏这些古董。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人收藏古代的字画。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱收藏各种漂亮的石头。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你也爱收藏，可以来参加这个展览。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把收藏的老书都捐给了图书馆。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生收藏了三千多本书。", "target_word": "收藏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收藏了", "label": "完成体"}, {"form": "收藏着", "label": "持续体"}, {"form": "收藏过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动作：把有价值或喜爱的物品收集起来并保存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18fb1b0-f1b5-4017-a2d3-64fcd7c50305') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收藏", "is_correct": true, "explanation": "收藏：把喜爱的旧邮票存起来，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢掉，与“喜欢”旧邮票的语境相反。"}, {"text": "踩", "is_correct": false, "explanation": "语义：踩是用脚踏压，与“喜欢”旧邮票的珍爱语境相反。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧是毁掉，与“喜欢”旧邮票的珍爱语境冲突。"}], "explanations": {"收藏": "收藏：把喜爱的旧邮票存起来，符合句意。", "扔": "语义：扔是丢掉，与“喜欢”旧邮票的语境相反。", "踩": "语义：踩是用脚踏压，与“喜欢”旧邮票的珍爱语境相反。", "烧": "语义：烧是毁掉，与“喜欢”旧邮票的珍爱语境冲突。"}, "sentence_index": 0, "correct_answer": "收藏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书桌收藏得很干净。", "explanation": "这里应该用〈收拾〉。收藏是珍爱地保存，整理书桌要用收拾。"}, {"text": "那家公司收藏了一家小店。", "explanation": "这里应该用〈收购〉。收藏指保存心爱之物，买下小店要用收购。"}, {"text": "他收藏了一只流浪猫。", "explanation": "这里应该用〈收养〉。收藏的对象是物品，不能用于活的动物，要用收养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收藏", "is_correct": true, "explanation": "收藏：珍爱地保存，符合“从小就爱”和漂亮石头的语境。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：砸指击碎，不能说“爱砸漂亮的石头”。"}, {"text": "抛", "is_correct": false, "explanation": "语义：抛是扔掉，与“爱”和“漂亮”的喜爱之情冲突。"}, {"text": "锁", "is_correct": false, "explanation": "语义：锁是用锁关上，“爱锁石头”不能表示收集并保存漂亮石头。"}], "explanations": {"收藏": "收藏：珍爱地保存，符合“从小就爱”和漂亮石头的语境。", "砸": "搭配：砸指击碎，不能说“爱砸漂亮的石头”。", "抛": "语义：抛是扔掉，与“爱”和“漂亮”的喜爱之情冲突。", "锁": "语义：锁是用锁关上，“爱锁石头”不能表示收集并保存漂亮石头。"}, "sentence_index": 6, "correct_answer": "收藏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察收藏了他的违禁品。", "explanation": "这里应该用〈没收〉。收藏带有珍爱的意思，查获违禁品要用没收。"}, {"text": "我把行李收藏在车站里。", "explanation": "这里应该用〈寄存〉。收藏指把珍爱之物好好保存，寄放行李要用寄存，不能说收藏。"}, {"text": "这家店收藏了一笔费用。", "explanation": "这里应该用〈收取〉。收藏是保存心爱之物，向客人收费要用收取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷把这些老钱币收藏上来了。", "corrected_sentence": "爷爷把这些老钱币收藏起来了。", "error_description": "错误：补语“上来”与“收藏”搭配不当。正确：把+宾语+收藏+“起来”，表示收集并保存好。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f2aa64b-1798-4ec7-bd59-e768467d3771') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
