INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "整是一点也不少，是全部的。", "primary_collocate": null, "pronunciation": "zhěng", "ipa": "ʈʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他一口气喝完了整瓶水。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子饿坏了，一个人吃了整碗饭。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了整晚的书，一分钟也没睡。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把整桶水倒进了池子里，一滴也没剩。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要买整箱牛奶，不要只买一瓶。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这锅汤太好喝，他一个人喝了整锅。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很饿，把整盘菜都吃光了。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电了，整栋楼都没有灯。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天下雨，整班同学都没来。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做了整桌菜，请大家来吃。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整整", "label": "重叠"}, {"form": "整个", "label": "复合"}, {"form": "整天", "label": "复合"}], "register": "中性", "sense_fingerprint": "整：全部、一点不少（整瓶水、三点整）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af238286-c549-4cf8-8736-86ca312c2e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是一点不少、全部。"}, {"text": "争", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。"}, {"text": "证", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。"}, {"text": "政", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是一点不少、全部。", "争": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。", "蒸": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。", "证": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。", "政": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示全部、一点不少，与“一口气喝完了”的瓶装水相符。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指没有东西，与“喝完了水”矛盾。"}, {"text": "零", "is_correct": false, "explanation": "数词：「零」表示没有，「零瓶水」与「一口气喝完」的数量矛盾。"}, {"text": "碎", "is_correct": false, "explanation": "搭配：“碎”说物体破裂，不能修饰装水的“瓶”，“碎瓶水”不成立。"}], "explanations": {"整": "「整」表示全部、一点不少，与“一口气喝完了”的瓶装水相符。", "空": "语义：“空”指没有东西，与“喝完了水”矛盾。", "零": "数词：「零」表示没有，「零瓶水」与「一口气喝完」的数量矛盾。", "碎": "搭配：“碎”说物体破裂，不能修饰装水的“瓶”，“碎瓶水”不成立。"}, "sentence_index": 0, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把整张桶倒进了池子里，一滴也没剩。", "explanation": "这里应该用〈整个〉。桶用“个”计量，“张”用于纸、桌面等平面的东西。"}, {"text": "他把桶里的水倒了整半。", "explanation": "这里应该用〈一〉。“整”表示全部、一点不少，不能和“半”连用，应说“倒了一半”。"}, {"text": "我把整根水都倒进了池子里，一滴也没剩。", "explanation": "这里应该用〈整桶〉。水要用“桶”计量，“根”用于细长的条状东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是一点不少、全部。"}, {"text": "正", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。"}, {"text": "挣", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。"}, {"text": "征", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。"}, {"text": "睁", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是一点不少、全部。", "正": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。", "挣": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。", "征": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。", "睁": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示全部，与“把整盘菜都吃光了”相符。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指腐坏，与“吃光了”的正常饭菜不合。"}, {"text": "脏", "is_correct": false, "explanation": "语义：“脏”指不干净，与饿了要吃光的语境不符。"}, {"text": "生", "is_correct": false, "explanation": "搭配：“生”多指未煮熟的食材，不能说“生盘菜”。"}], "explanations": {"整": "「整」表示全部，与“把整盘菜都吃光了”相符。", "烂": "语义：“烂”指腐坏，与“吃光了”的正常饭菜不合。", "脏": "语义：“脏”指不干净，与饿了要吃光的语境不符。", "生": "搭配：“生”多指未煮熟的食材，不能说“生盘菜”。"}, "sentence_index": 6, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做了整只菜，请大家来吃。", "explanation": "这里应该用〈整道〉。菜用“道”计量，“只”用于动物、器物等。"}, {"text": "妈妈只吃了整一口菜，就饱了。", "explanation": "这里不该用“整”。“整”表示全部，和“只……一口”的少量矛盾，应说“只吃了一口菜”。"}, {"text": "妈妈把整根蛋糕都端上来了。", "explanation": "这里应该用〈整个〉。蛋糕用“个”计量，“根”用于细长的条状东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一口气喝完了整张牛奶。", "corrected_sentence": "他一口气喝完了整箱牛奶。", "error_description": "错误：“张”用于纸、桌子等平面的东西，牛奶要用“箱”计量，应说“整箱牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把锅整汤都倒掉了。", "corrected_sentence": "妈妈把整锅汤都倒掉了。", "error_description": "错误：“整”与量词“锅”的语序颠倒，说成“锅整汤”。正确：应说“整锅汤”，“整”放在量词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "完整无缺，未被切开或拆散。", "primary_collocate": null, "pronunciation": "zhěng", "ipa": "ʈʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "盘子里放着整条鱼，鱼头鱼尾都在。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕还没切，我们买的是整块的。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师手里拿着整张地图，没有撕坏。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书很贵，我想买整套，不想只买一本。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把整句话读一遍，不要只读一半。", "target_word": "整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站远一点，才能看到整幅画。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子摔碎了，没有一块是整的。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想要整只鸡，不要鸡腿。", "target_word": "整", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书虽然旧了，但整本都在，没有缺页。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从山上搬回了整棵树，根也没断。", "target_word": "整", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "整整", "label": "重叠"}, {"form": "整个", "label": "复合"}, {"form": "整天", "label": "复合"}], "register": "中性", "sense_fingerprint": "整：完整无缺的，用在量词前（整条鱼、整块蛋糕）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af238286-c549-4cf8-8736-86ca312c2e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是完整、全部。"}, {"text": "正", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。"}, {"text": "蒸", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。"}, {"text": "争", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。"}, {"text": "证", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是完整、全部。", "正": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是正。", "蒸": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是蒸。", "争": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是争夺。", "证": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是证明。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示完整，与“鱼头鱼尾都在”相符，量词“条”前用“整”。"}, {"text": "残", "is_correct": false, "explanation": "语义：“残”指残缺，与“鱼头鱼尾都在”矛盾。"}, {"text": "碎", "is_correct": false, "explanation": "搭配：“碎”不能直接修饰量词“条”，“碎条鱼”不成立。"}, {"text": "烂", "is_correct": false, "explanation": "语义：“烂”指腐坏，与“鱼头鱼尾都在”的描述不符。"}], "explanations": {"整": "「整」表示完整，与“鱼头鱼尾都在”相符，量词“条”前用“整”。", "残": "语义：“残”指残缺，与“鱼头鱼尾都在”矛盾。", "碎": "搭配：“碎”不能直接修饰量词“条”，“碎条鱼”不成立。", "烂": "语义：“烂”指腐坏，与“鱼头鱼尾都在”的描述不符。"}, "sentence_index": 0, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一口气吃完了整张鸡。", "explanation": "这里应该用〈整只〉。鸡用“只”计量，“张”用于纸张、桌面等平面的东西。"}, {"text": "杯子摔成了好几块，可是还是整的。", "explanation": "这里不该用“整”。“整”指完整无缺，杯子已经摔成好几块，就不是整的了。"}, {"text": "我想买整只书，不想只买一本。", "explanation": "这里应该用〈整本〉。书用“本”计量，“只”用于动物、器物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」读 zhěng（第三声），意思是完整、全部。"}, {"text": "政", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。"}, {"text": "挣", "is_correct": false, "explanation": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。"}, {"text": "征", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。"}, {"text": "睁", "is_correct": false, "explanation": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}], "explanations": {"整": "「整」读 zhěng（第三声），意思是完整、全部。", "政": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是政治。", "挣": "zhèng（第四声）与 zhěng（第三声）声调不同，意思是赚取。", "征": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是征收、征求。", "睁": "zhēng（第一声）与 zhěng（第三声）声调不同，意思是张开眼睛。"}, "sentence_index": null, "correct_answer": "整"}, "level_3": {"options": [{"text": "整", "is_correct": true, "explanation": "「整」表示完整，与“没有一块是整的”相符，说明碎片都不完整。"}, {"text": "破", "is_correct": false, "explanation": "语义：“破”指损坏，说“没有一块是破的”与“摔碎了”的语境相反。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”说新旧，与句子讨论碎片是否完整的语境无关。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，与摔碎的杯子碎片无关，不能说「没有一块是甜的」。"}], "explanations": {"整": "「整」表示完整，与“没有一块是整的”相符，说明碎片都不完整。", "破": "语义：“破”指损坏，说“没有一块是破的”与“摔碎了”的语境相反。", "新": "语义：“新”说新旧，与句子讨论碎片是否完整的语境无关。", "甜": "语义：「甜」形容味道，与摔碎的杯子碎片无关，不能说「没有一块是甜的」。"}, "sentence_index": 6, "correct_answer": "整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家人吃掉了整条西瓜。", "explanation": "这里应该用〈整个〉。西瓜用“个”计量，“条”用于鱼、裤子等细长的东西。"}, {"text": "他买了一整棵鱼。", "explanation": "这里应该用〈整条〉。鱼用“条”计量，“棵”用于树木。"}, {"text": "他们从山上搬回了整棵石头。", "explanation": "这里应该用〈整块〉。石头用“块”计量，“棵”用于树木、植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了套整家具，搬进了新家。", "corrected_sentence": "他买了整套家具，搬进了新家。", "error_description": "错误：“整”放在了量词“套”后面，说成“套整”。正确：“整”应放在量词前，说“整套家具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他整把块蛋糕吃完了。", "corrected_sentence": "他把整块蛋糕吃完了。", "error_description": "错误：“把”与“整”的顺序颠倒。正确：“把”要放在处置对象前，应说“把整块蛋糕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '561b21ec-cf41-4622-953b-189026175999') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
