INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94519, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "月底是一个月快要结束的时候。", "primary_collocate": null, "pronunciation": "yuè dǐ", "ipa": "ɥɛ˥˩ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "月底到了，这个月的钱快花完了。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是月底，天气慢慢变凉了。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到月底，我就开始想下个月做什么。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底了，别忘了写这个月的总结。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底的晚上，街上人很少。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月底都给妈妈打电话。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底，办公室里大家都很累。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们月底开会，说说这个月的工作。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底的超市里人特别多。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快到月底了，我得算一下花了多少钱。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个月快要结束的时候，强调这个月将尽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月底", "is_correct": true, "explanation": "「月底」指一个月快结束的时候，与「快花完了」相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：「体温」是人的身体温度，不是时间，「体温到了」讲不通。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：「到了」后面要接时间，不接「墨水」这类物品。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是建筑部件，不能表示时间，句子的主语不能是窗户。"}], "explanations": {"月底": "「月底」指一个月快结束的时候，与「快花完了」相符。", "体温": "语义：「体温」是人的身体温度，不是时间，「体温到了」讲不通。", "墨水": "搭配：「到了」后面要接时间，不接「墨水」这类物品。", "窗户": "语义：「窗户」是建筑部件，不能表示时间，句子的主语不能是窗户。"}, "sentence_index": 0, "correct_answer": "月底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月底了，这个月才刚刚开始。", "explanation": "一个月刚开始应说〈月初了〉；「月底了」表示一个月快结束了。"}, {"text": "月底了，今天是这个月的第一天。", "explanation": "一个月的第一天应说〈月初〉；「月底」指一个月快结束的时候。"}, {"text": "月底了，这个月才过了一半。", "explanation": "这里应说〈月中〉。过了一半的时候是月中，「月底」指一个月快结束的时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月底", "is_correct": true, "explanation": "「月底」指一个月快结束的时候，办公室里的大家很累与此相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」指人的身体高度，不能作句子的时间状语。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是人或动物的岁数，不能表示某个时间点。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：「钥匙」是物品，不能作时间状语，句子说的是时间。"}], "explanations": {"月底": "「月底」指一个月快结束的时候，办公室里的大家很累与此相符。", "身高": "体貌：「身高」指人的身体高度，不能作句子的时间状语。", "年龄": "语义：「年龄」是人或动物的岁数，不能表示某个时间点。", "钥匙": "语义：「钥匙」是物品，不能作时间状语，句子说的是时间。"}, "sentence_index": 6, "correct_answer": "月底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月底是一周的最后一天。", "explanation": "一周的最后一天应说〈星期天〉；「月底」指一个月的最后几天。"}, {"text": "月底是一天的前半段。", "explanation": "一天的前半段应说〈上午〉；「月底」指一个月的最后几天，不指一天的时段。"}, {"text": "月底是一周的开始。", "explanation": "一周的开始应说〈星期一〉；「月底」不表示一周的开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份月底前，我们要把账单交上去。", "corrected_sentence": "这个月底前，我们要把账单交上去。", "error_description": "「月底」前的量词应用「个」，不用「份」。「份」用于文件、礼物等，不能修饰时间。应为「这个月底前」，「这份月底前」是错误的量词搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条月底，我们要把账单都整理好。", "corrected_sentence": "这个月底，我们要把账单都整理好。", "error_description": "「月底」前的量词应用「个」，不用「条」。「条」用于细长的东西，不能修饰时间。应为「这个月底」，「这条月底」是错误的量词搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
