INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每月的最后几天。", "primary_collocate": null, "pronunciation": "yuè dǐ", "ipa": "ɥɛ˥˩ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "月底我要交房租。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月底我们去北京旅游。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司月底发工资。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底的时候，我的钱总是不够用。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我月底才有时间见你。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月底，他就要回国了。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底前请把作业交给老师。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底商店在打折，很多人去买东西。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了月底，我常常很忙。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她月底搬家，朋友们都来帮忙。", "target_word": "月底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个月的最后几天，常与发工资、交租、截止日期有关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月底", "is_correct": true, "explanation": "「月底」指每月最后几天，与「交房租」的时间相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：「饭店」是地方，不是时间，不能作句子的时间主题。"}, {"text": "房东", "is_correct": false, "explanation": "语义：「房东」是人，不是时间，句子说的是什么时候交房租。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」是人的身体数据，不表示时间。"}], "explanations": {"月底": "「月底」指每月最后几天，与「交房租」的时间相符。", "饭店": "语义：「饭店」是地方，不是时间，不能作句子的时间主题。", "房东": "语义：「房东」是人，不是时间，句子说的是什么时候交房租。", "身高": "语义：「身高」是人的身体数据，不表示时间。"}, "sentence_index": 0, "correct_answer": "月底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月底是一个月的第一天。", "explanation": "一个月的第一天应说〈月初〉；「月底」指每月最后几天。"}, {"text": "月底是一年的最后一天。", "explanation": "一年的最后一天应说〈年底〉；「月底」只指一个月的最后几天。"}, {"text": "月底是一个月的中间日子。", "explanation": "一个月的中间时段应说〈中旬〉；「月底」在月末，不在中间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月底", "is_correct": true, "explanation": "「月底前」指一个月最后几天之前的期限，与句意相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：「工资」是收入，不是时间，不能作「前」的时间界限。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」是人的身体数据，不能表示截止时间。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是时段，「天气前」讲不通。"}], "explanations": {"月底": "「月底前」指一个月最后几天之前的期限，与句意相符。", "工资": "语义：「工资」是收入，不是时间，不能作「前」的时间界限。", "体重": "语义：「体重」是人的身体数据，不能表示截止时间。", "天气": "语义：「天气」不是时段，「天气前」讲不通。"}, "sentence_index": 6, "correct_answer": "月底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月底是一周的休息日。", "explanation": "一周的休息日应说〈周末〉；「月底」指一个月的最后几天。"}, {"text": "月底是一天的开始。", "explanation": "一天的开始应说〈早上〉；「月底」指一个月的最后几天，不指一天的时段。"}, {"text": "月底是一个月的前十天。", "explanation": "一个月的前十天应说〈上旬〉；「月底」在月末，不在月初。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条月底我们要搬家。", "corrected_sentence": "这个月底我们要搬家。", "error_description": "「月底」前的量词应用「个」，不用「条」。「条」用于细长的东西，不能修饰时间。应为「这个月底」，「这条月底」是错误的量词搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每个月底了都去看望奶奶。", "corrected_sentence": "我每个月底都去看望奶奶。", "error_description": "「每个月底」表示经常性的时间，后面不能再加「了」。应为「我每个月底都去看望奶奶」，「每个月底了」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
