INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94523, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东南是东边和南边中间的方向。", "primary_collocate": null, "pronunciation": "dōng nán", "ipa": "tʊŋ˥ nan˧˥", "syllable_count": 2, "sentences": [{"text": "窗户朝着东南,屋里很亮。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你往东南看，那边有彩虹。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车往东南开,不要往西北开。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东南和西北是相反的方向。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家在村子的东南。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东南的风带来了雨。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船向东南慢慢地走远了。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上指出东南的位置。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城的东南有一条河。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天,东南来的风很湿。", "target_word": "东南", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "东南方", "label": "复合"}, {"form": "东南部", "label": "复合"}], "register": "中性", "sense_fingerprint": "东边和南边中间的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5fa97b1-fd90-4ed3-8e63-a2bf197b8d55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东南", "is_correct": true, "explanation": "正确：“朝着东南”表示窗户面向东南方向，“东南”是方位名词。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是方向，窗户不能朝着声音。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能表示方向，不能和“朝着”搭配。"}, {"text": "数字", "is_correct": false, "explanation": "语义：“数字”不是方位，不能表示窗户的朝向。"}], "explanations": {"东南": "正确：“朝着东南”表示窗户面向东南方向，“东南”是方位名词。", "声音": "语义：“声音”不是方向，窗户不能朝着声音。", "价格": "搭配：“价格”不能表示方向，不能和“朝着”搭配。", "数字": "语义：“数字”不是方位，不能表示窗户的朝向。"}, "sentence_index": 0, "correct_answer": "东南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把东南放进了书包。", "explanation": "这里用“东南”不对。“东南”是方向，不是有形的东西，不能放进书包。"}, {"text": "他的东南很有礼貌。", "explanation": "“东南”是方位名词，不能用来描述人的性格或态度。"}, {"text": "今天东南刮得很大，骑车很累。", "explanation": "这里应该用〈东南风〉。东南指方向，不能作“刮”的主语，表示风要说东南风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东南", "is_correct": true, "explanation": "正确：“向东南”表示船朝东南方向前进，“东南”是方位名词。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是地点，小船不能走向桌子。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“走远”需要处所作去向，“作业”不能作去向。"}, {"text": "名字", "is_correct": false, "explanation": "配价：“名字”不能作去向，不能和“向”“走远”搭配。"}], "explanations": {"东南": "正确：“向东南”表示船朝东南方向前进，“东南”是方位名词。", "桌子": "语义：“桌子”不是地点，小船不能走向桌子。", "作业": "配价：“走远”需要处所作去向，“作业”不能作去向。", "名字": "配价：“名字”不能作去向，不能和“向”“走远”搭配。"}, "sentence_index": 6, "correct_answer": "东南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天要考东南。", "explanation": "“东南”是方位，不是考试的内容，不能说“考东南”。"}, {"text": "他一边走一边拿东南当拐杖。", "explanation": "这里不能这么用。东南是方位，不是可以当拐杖用的东西，不能作“拿”的宾语。"}, {"text": "他的东南是十八岁。", "explanation": "“东南”是方位名词，不能用来表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家在学校的东南里，走路十分钟就到。", "corrected_sentence": "我家在学校的东南，走路十分钟就到。", "error_description": "错误：“学校的东南里”，多加了“里”。正确：“学校的东南”。“东南”本身就是方位词，表示位置，后面不能再加“里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小船向东南地走远了，大家挥手告别。", "corrected_sentence": "小船向东南走远了，大家挥手告别。", "error_description": "错误：“向东南地走远了”，多加了“地”。正确：“向东南走远了”。“向东南”是介词短语作状语，后面不能再加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ba0dbeb-43eb-4596-a7da-0ec262fa1ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
