INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "档是按高低大小分出的层级，如风扇的几档、价格分几档。", "primary_collocate": null, "pronunciation": "dàng", "ipa": "taŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这台风扇有三档风。", "target_word": "档", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把空调调到二档。", "target_word": "档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜按价格分三档。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电饭锅的火力分两档，火大火小不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水开了，把火调小一档。", "target_word": "档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的价格分几档，你要哪一档？", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风太大了，调低一档吧。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店的房间分三档，价钱不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电吹风的风速分两档，风大风小不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台洗衣机的转速分两档，快慢不同。", "target_word": "档", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高档", "label": "复合"}, {"form": "档次", "label": "复合"}, {"form": "檔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按高低大小分出的层级，如风扇的几档、价格分几档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: 4 words above tier T2 (max 3): 这台 (Zipf 3.53), 洗衣机 (Zipf 3.69), 转速 (Zipf 3.51), 快慢 (Zipf 3.13)']::text[], 'ec13897d-af07-46b2-a20a-db12a5ed8bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "档", "is_correct": true, "explanation": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。"}, {"text": "当", "is_correct": false, "explanation": "当 dāng（第一声）与 dàng 只差声调，意思是承担或正在，不是档。"}, {"text": "挡", "is_correct": false, "explanation": "挡 dǎng（第三声）与 dàng 只差声调，意思是阻挡。"}, {"text": "党", "is_correct": false, "explanation": "党 dǎng（第三声）与 dàng 只差声调，意思是政党。"}, {"text": "但", "is_correct": false, "explanation": "但 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是但是。"}, {"text": "烫", "is_correct": false, "explanation": "烫 tàng 与 dàng 只差声母 t/d，意思是温度高。"}], "explanations": {"档": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。", "当": "当 dāng（第一声）与 dàng 只差声调，意思是承担或正在，不是档。", "挡": "挡 dǎng（第三声）与 dàng 只差声调，意思是阻挡。", "党": "党 dǎng（第三声）与 dàng 只差声调，意思是政党。", "但": "但 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是但是。", "烫": "烫 tàng 与 dàng 只差声母 t/d，意思是温度高。"}, "sentence_index": null, "correct_answer": "档"}, "level_3": {"options": [{"text": "档", "is_correct": true, "explanation": "档指风扇的风力等级，填入后「这台风扇有三档风」通顺。"}, {"text": "季", "is_correct": false, "explanation": "语义：季风是按季节吹的风，风扇不分季节，不能说「三季风」。"}, {"text": "阵", "is_correct": false, "explanation": "搭配：「阵」用于一阵风这类间歇出现的风，不用于数风扇的档位。"}, {"text": "声", "is_correct": false, "explanation": "语义：「声」指声音，风扇的风力不能按声计数，句子不通。"}], "explanations": {"档": "档指风扇的风力等级，填入后「这台风扇有三档风」通顺。", "季": "语义：季风是按季节吹的风，风扇不分季节，不能说「三季风」。", "阵": "搭配：「阵」用于一阵风这类间歇出现的风，不用于数风扇的档位。", "声": "语义：「声」指声音，风扇的风力不能按声计数，句子不通。"}, "sentence_index": 0, "correct_answer": "档"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋楼有三档，每档有五间房。", "explanation": "这里应该用〈层〉。楼房的层数要用〈层〉，档只用于按高低大小分出的层级，不用于楼层。"}, {"text": "这列火车有八档车厢。", "explanation": "这里应该用〈节〉。车厢数量要用〈节〉，档不能用来数车厢。"}, {"text": "电影院有十档座位。", "explanation": "这里应该用〈排〉。座位的前后排列要用〈排〉，档不能用于座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "档", "is_correct": true, "explanation": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。"}, {"text": "定", "is_correct": false, "explanation": "定 dìng（第四声）与 dàng 只差元音 i/a，意思是固定或决定。"}, {"text": "浪", "is_correct": false, "explanation": "浪 làng 与 dàng 只差声母 l/d，意思是波浪。"}, {"text": "弹", "is_correct": false, "explanation": "弹 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是弹药。"}, {"text": "巷", "is_correct": false, "explanation": "巷 hàng 与 dàng 只差声母 h/d，意思是小巷。"}], "explanations": {"档": "档 dàng（第四声）指按高低大小分出的层级，是正确答案。", "定": "定 dìng（第四声）与 dàng 只差元音 i/a，意思是固定或决定。", "浪": "浪 làng 与 dàng 只差声母 l/d，意思是波浪。", "弹": "弹 dàn（第四声）与 dàng 只差韵尾 n/ng，意思是弹药。", "巷": "巷 hàng 与 dàng 只差声母 h/d，意思是小巷。"}, "sentence_index": null, "correct_answer": "档"}, "level_3": {"options": [{"text": "档", "is_correct": true, "explanation": "档指风力等级，「调低一档」表示把风力降低一级。"}, {"text": "种", "is_correct": false, "explanation": "语义：「种」指类别，「调低一种」说不通，风力只能说调低一档。"}, {"text": "套", "is_correct": false, "explanation": "搭配：「套」用于成套的物品，不能用来数风力等级。"}, {"text": "片", "is_correct": false, "explanation": "搭配：「片」用于成片的事物，不能说「调低一片」。"}], "explanations": {"档": "档指风力等级，「调低一档」表示把风力降低一级。", "种": "语义：「种」指类别，「调低一种」说不通，风力只能说调低一档。", "套": "搭配：「套」用于成套的物品，不能用来数风力等级。", "片": "搭配：「片」用于成片的事物，不能说「调低一片」。"}, "sentence_index": 6, "correct_answer": "档"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语档很高。", "explanation": "这里应该用〈水平〉。〈档〉指按高低分出的层级，不能用来说人的能力高低；说能力的高低要用〈水平〉。"}, {"text": "这次地震的档很严重。", "explanation": "这里应该用〈程度〉。〈档〉指按高低分出的等级，不能用来说事情的严重程度；形容严重程度要用〈程度〉。"}, {"text": "这条路有三档，车可以并排走。", "explanation": "这里应该用〈车道〉。路上并排行车的道要用〈车道〉；档指按高低大小分出的层级，不指路的分道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台空调有四只档风。", "corrected_sentence": "这台空调有四档风。", "error_description": "错误：「四只档风」。正确：「四档风」。「只」用于动物或成对物品中的一件，不能修饰「档」；表示风力等级时，数词直接接「档」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风太小了，调高档一吧。", "corrected_sentence": "风太小了，调高一档吧。", "error_description": "错误：「调高档一吧」。正确：「调高一档吧」。数量词「一档」要放在动词后面，不能把数词放到「档」的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
