INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94527, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "死当是考试差得太多，没有办法再补，要重新学。", "primary_collocate": null, "pronunciation": "sǐ dàng", "ipa": "sɨ˨˩˦ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他这门课考得太差，死当了。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "期末考得太差，这门课就会死当。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕这门课死当，天天去图书馆。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作业都没交，所以这科死当了。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学死当以后，他得明年再学一次。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把三个没来考试的同学死当了。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课死当了，不能再补考。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友大一有两科死当，要重新学。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次考试都只考十分，这科一定死当。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听说这科死当了，难过得说不出话。", "target_word": "死当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "死當", "label": "繁体"}, {"form": "死当了", "label": "体标"}, {"form": "死当过", "label": "体标"}], "register": "口语", "sense_fingerprint": "考试成绩太差，不能补考，必须重修", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "死当", "is_correct": true, "explanation": "“死当”指考试太差、不能补考，与“考得太差”相符。"}, {"text": "及格", "is_correct": false, "explanation": "语义：“及格”表示成绩合格，与“考得太差”矛盾。"}, {"text": "加分", "is_correct": false, "explanation": "搭配：“加分”与“考得太差”搭配不当，不说考差了加分。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：考得太差不会被夸奖，句子不通。"}], "explanations": {"死当": "“死当”指考试太差、不能补考，与“考得太差”相符。", "及格": "语义：“及格”表示成绩合格，与“考得太差”矛盾。", "加分": "搭配：“加分”与“考得太差”搭配不当，不说考差了加分。", "夸奖": "语义：考得太差不会被夸奖，句子不通。"}, "sentence_index": 0, "correct_answer": "死当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这门课他考了五十分，死当了，但还能补考。", "explanation": "这里应该用〈不及格〉。死当指不能补考、必须重修，句中说还能补考，应用不及格。"}, {"text": "这次考试他考得最好，所以死当了。", "explanation": "这里应该用〈被表扬〉。死当指成绩太差、不能补考，考得最好不能说死当。"}, {"text": "这门课他没及格，只好死当。", "explanation": "这里应该用〈重修〉。死当是不及格、不能补考的结果，不是自己选择的补救办法，不能说“只好死当”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死当", "is_correct": true, "explanation": "“死当”与“不能再补考”相符，表示课程不及格、必须重修。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”需要人作主语，不说课生病了。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”用于房屋，不能用于课程。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”需要人作主语，不说课迟到了。"}], "explanations": {"死当": "“死当”与“不能再补考”相符，表示课程不及格、必须重修。", "生病": "搭配：“生病”需要人作主语，不说课生病了。", "装修": "语义：“装修”用于房屋，不能用于课程。", "迟到": "搭配：“迟到”需要人作主语，不说课迟到了。"}, "sentence_index": 6, "correct_answer": "死当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直找不到工作，所以死当了。", "explanation": "这里应该用〈很着急〉。死当只用于课程考试不及格、不能补考，不能用于找工作。"}, {"text": "这门课他考了九十分，结果死当了。", "explanation": "这里应该用〈及格〉。死当指成绩太差、不能补考，九十分是及格的，不能说死当。"}, {"text": "这门课他没及格，下学期要死当。", "explanation": "这里应该用〈重修〉。死当本身是不能补考的结果，不说“下学期要死当”，应说重修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期的数学成绩太差，很死当了。", "corrected_sentence": "他这学期的数学成绩太差，死当了。", "error_description": "“死当”是动词，不能受程度副词“很”修饰。应去掉“很”，说“死当了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门课他考了二十分，已经死当着。", "corrected_sentence": "这门课他考了二十分，已经死当了。", "error_description": "“死当”表示已经完成的结果，要用“了”；“着”表示动作的持续，不能用于已经完成的结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94529, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暂时", "is_correct": true, "explanation": "正确：“暂时”与“永久”意思相反，表示时间短、不长久。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容明白，与“永久”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力，与“永久”没有反义关系。"}, {"text": "丰富", "is_correct": false, "explanation": "无关：“丰富”形容数量多，与“永久”没有反义关系。"}], "correct_answer": "暂时", "explanations": {"暂时": "正确：“暂时”与“永久”意思相反，表示时间短、不长久。", "清楚": "无关：“清楚”形容明白，与“永久”没有反义关系。", "聪明": "无关：“聪明”形容智力，与“永久”没有反义关系。", "丰富": "无关：“丰富”形容数量多，与“永久”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
