INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94529, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "永久是一直都在，永远不会没有。", "primary_collocate": null, "pronunciation": "yǒng jiǔ", "ipa": "jʊŋ˨˩˦ tɕjou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张照片我会永久保存。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要永久的和平。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有什么东西是永久的。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字将永久留在大家心里。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这座城市有永久的家。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墨水写的字可以永久不变。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸希望我们的友谊永久存在。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定是永久的，不会再改。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是永久的，不会拆掉。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他永久离开了这个国家，再也没回来。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "永久性", "label": "复合"}], "register": "中性", "sense_fingerprint": "永久：一直存在，不会消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94529, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永久", "is_correct": true, "explanation": "正确：“永久”修饰“保存”，表示长久保存，与“我会”的打算相符。"}, {"text": "凌乱", "is_correct": false, "explanation": "搭配：“凌乱”形容杂乱的样子，不能用来修饰“保存”。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易损坏，与“会保存、要长久留存”的意图相反。"}, {"text": "模糊", "is_correct": false, "explanation": "搭配：“模糊”形容不清楚，不能用来修饰“保存”这一动作。"}], "explanations": {"永久": "正确：“永久”修饰“保存”，表示长久保存，与“我会”的打算相符。", "凌乱": "搭配：“凌乱”形容杂乱的样子，不能用来修饰“保存”。", "脆弱": "语义：“脆弱”指容易损坏，与“会保存、要长久留存”的意图相反。", "模糊": "搭配：“模糊”形容不清楚，不能用来修饰“保存”这一动作。"}, "sentence_index": 0, "correct_answer": "永久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次相聚是永久的，我们很快就要分开。", "explanation": "这里应该用〈短暂〉。永久表示长久不变，与“很快就要分开”矛盾。"}, {"text": "这种颜料很永久，洗很多次也不褪色。", "explanation": "这里应该用〈持久〉。持久说颜色、材料耐用；永久强调一直存在、不会消失，不能用“很”来修饰耐用的程度。"}, {"text": "这家店因为装修永久停业一周。", "explanation": "这里应该用〈暂时〉。永久表示长久不变，不能与“一周”这种有期限的时间并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永久", "is_correct": true, "explanation": "正确：“永久”修饰“存在”，表示友谊长久留存，与“希望”的语境相符。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容缺少水分，不能用来说友谊“存在”。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”形容负担，与“希望友谊长久存在”的语境相反。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：“幼稚”形容想法或性格不成熟，不能用来说友谊“存在”。"}], "explanations": {"永久": "正确：“永久”修饰“存在”，表示友谊长久留存，与“希望”的语境相符。", "干燥": "搭配：“干燥”形容缺少水分，不能用来说友谊“存在”。", "沉重": "语义：“沉重”形容负担，与“希望友谊长久存在”的语境相反。", "幼稚": "搭配：“幼稚”形容想法或性格不成熟，不能用来说友谊“存在”。"}, "sentence_index": 6, "correct_answer": "永久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子是永久的，明天就要搬走了。", "explanation": "这里应该用〈暂时的〉。永久表示长久不变，与“明天就要搬走”矛盾。"}, {"text": "我永久去那家书店买书。", "explanation": "这里应该用〈经常〉。永久说的是存在时间长，不表示行为发生的次数。"}, {"text": "这份合同的期限很永久，一个月就到期了。", "explanation": "这里应该用〈有期限〉的说法。永久表示长久不变，不能与“一个月就到期”这种有期限的情况并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个永久地记号。", "corrected_sentence": "这是一个永久的记号。", "error_description": "“永久”修饰名词“记号”时要用“的”，写成“地”是错的，“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我会永久的保存这张照片。", "corrected_sentence": "我会永久地保存这张照片。", "error_description": "“永久”作状语修饰动词“保存”时要用“地”，写成“的”是错的，“的”用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
