INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94530, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "长久存在，永远。", "primary_collocate": null, "pronunciation": "yǒng jiǔ", "ipa": "jʊŋ˨˩˦ tɕjou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他永久地离开了家乡。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山永久地站在海边。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把这些故事永久留下来。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰雪永久不化的地方很少有人住。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字永久刻在这块石头上。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司送给我一张永久会员卡。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能永久年轻。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座纪念碑会永久矗立在广场中央。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种爱是永久的，不会因为时间改变。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的作者永久地活在读者心里。", "target_word": "永久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "永久性", "label": "复合"}], "register": "中性", "sense_fingerprint": "永久：长久不变，永远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永久", "is_correct": true, "explanation": "正确：“永久地”修饰“离开”，表示永远离开家乡。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间小，不能用来修饰“离开”这一动作。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质地不光滑，不能用来说离开的方式。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指事物过时，与“离开”的动作没有关系。"}], "explanations": {"永久": "正确：“永久地”修饰“离开”，表示永远离开家乡。", "狭窄": "搭配：“狭窄”形容空间小，不能用来修饰“离开”这一动作。", "粗糙": "搭配：“粗糙”形容表面质地不光滑，不能用来说离开的方式。", "陈旧": "语义：“陈旧”指事物过时，与“离开”的动作没有关系。"}, "sentence_index": 0, "correct_answer": "永久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老房子是永久的，去年就已经拆掉了。", "explanation": "这里应该用〈临时的〉。永久表示长久不变，与“去年就已经拆掉”矛盾。"}, {"text": "工厂因为搬迁永久停工一周。", "explanation": "这里应该用〈暂时〉。永久表示长久不变，不能与“一周”这种有期限的时间并用。"}, {"text": "这种墨水很永久，写在纸上不会褪色。", "explanation": "这里应该用〈持久〉。持久说颜色耐用；永久强调存在不消失，不能用“很”来修饰耐用程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "永久", "is_correct": true, "explanation": "正确：“永久”修饰“年轻”，表示长久保持年轻，与句意相符。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道，不能用来修饰“年轻”。"}, {"text": "深沉", "is_correct": false, "explanation": "语义：“深沉”形容性格或感情，与“年轻”这种状态不相合。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度低，不能用来说人“年轻”。"}], "explanations": {"永久": "正确：“永久”修饰“年轻”，表示长久保持年轻，与句意相符。", "辛辣": "搭配：“辛辣”形容味道，不能用来修饰“年轻”。", "深沉": "语义：“深沉”形容性格或感情，与“年轻”这种状态不相合。", "冰凉": "搭配：“冰凉”形容温度低，不能用来说人“年轻”。"}, "sentence_index": 6, "correct_answer": "永久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只是永久的冲动，他转眼就忘了。", "explanation": "这里应该用〈一时的〉。永久表示长久不变，与“转眼就忘了”这种短暂的冲动矛盾。"}, {"text": "他永久来过这家店三次。", "explanation": "这里应该用〈经常〉或〈多次〉。永久说的是存在时间长，不表示行为发生的次数。"}, {"text": "今天的天气永久很好，明天就要下雨了。", "explanation": "这里应该用〈暂时〉。永久表示长久不变，与“明天就要下雨”这种很快改变的情况矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他永久的留在了这座城市。", "corrected_sentence": "他永久地留在了这座城市。", "error_description": "“永久”修饰动词“留”时要用“地”，写成“的”是错的，“的”用于修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张地图会永久的挂在墙上。", "corrected_sentence": "这张地图会永久地挂在墙上。", "error_description": "“永久”作状语修饰动词“挂”时要用“地”，写成“的”是错的，“的”用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
