INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94531, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沿海是靠着大海边上的地方。", "primary_collocate": null, "pronunciation": "yán hǎi", "ipa": "jɛn˧˥ xaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家住在沿海，每天都能吃到新鲜的鱼。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的夏天很热，但是风很大。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从沿海来到北方上大学。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的人喜欢吃海鲜。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，沿海的学校都放假了。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去沿海玩几天，看看大海。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的天气比山里湿。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在沿海工作了三十年。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的冬天不太冷，很少下雪。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说沿海的海鲜很便宜，我们去吃吧。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿海地区", "label": "复合"}, {"form": "沿海城市", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠着大海边上的地方，常见于地区、城市、天气与海鲜等语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94531, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沿海", "is_correct": true, "explanation": "沿海：靠着大海的地方，与“每天都能吃到新鲜的鱼”相合。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干旱缺水，不可能每天吃到新鲜的鱼。"}, {"text": "高空", "is_correct": false, "explanation": "语义：高空不适合居住，且与“每天都能吃到新鲜的鱼”不相合。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地是埋葬死人的地方，不能居住，与句意矛盾。"}], "explanations": {"沿海": "沿海：靠着大海的地方，与“每天都能吃到新鲜的鱼”相合。", "沙漠": "语义：沙漠干旱缺水，不可能每天吃到新鲜的鱼。", "高空": "语义：高空不适合居住，且与“每天都能吃到新鲜的鱼”不相合。", "墓地": "语义：墓地是埋葬死人的地方，不能居住，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "沿海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条江的沿海地区发展很快。", "explanation": "这里应该用〈沿江〉。沿海指靠着大海的地方；江边一带要用〈沿江〉。"}, {"text": "这个湖的沿海有很多渔船。", "explanation": "这里应该用〈沿湖〉。沿海指靠着大海的地方，湖边要用〈沿湖〉。"}, {"text": "这条公路的沿海地区有很多村庄。", "explanation": "这里应该用〈沿路〉。沿海指靠着大海的地方，路边一带要用〈沿路〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94531, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沿海", "is_correct": true, "explanation": "沿海：靠海的地方，空气湿润，与“比山里湿”相合。"}, {"text": "太空", "is_correct": false, "explanation": "语义：太空没有我们所说的天气，句子不通。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底没有地面意义上的天气，与“比山里湿”不合。"}, {"text": "人体", "is_correct": false, "explanation": "搭配：“天气”不修饰人体，说“人体的天气”不通。"}], "explanations": {"沿海": "沿海：靠海的地方，空气湿润，与“比山里湿”相合。", "太空": "语义：太空没有我们所说的天气，句子不通。", "海底": "语义：海底没有地面意义上的天气，与“比山里湿”不合。", "人体": "搭配：“天气”不修饰人体，说“人体的天气”不通。"}, "sentence_index": 6, "correct_answer": "沿海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街的沿海店铺都关门了。", "explanation": "这里应该用〈沿街〉。沿海指靠着大海的地方，街边的店铺要用〈沿街〉。"}, {"text": "这个湖很大，沿海有很多餐厅。", "explanation": "这里应该用〈沿湖〉。沿海指靠着大海的地方，湖边要用〈沿湖〉。"}, {"text": "这条路很长，沿海都是茶园。", "explanation": "这里应该用〈沿途〉。沿海指靠着大海的地方；说的是“这条路”两边，要用〈沿途〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐沿海开了一家小饭馆。", "corrected_sentence": "我姐姐在沿海开了一家小饭馆。", "error_description": "错误在“沿海”前缺少介词“在”。“沿海”作地点状语时要加“在”，应说“在沿海开”，不说“沿海开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些渔船每天在沿海里捕鱼。", "corrected_sentence": "这些渔船每天在沿海捕鱼。", "error_description": "错误在“沿海”后多加了方位词“里”。“沿海”是地区名词，不能加“里”，应说“在沿海捕鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
