INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近海岸的地带。", "primary_collocate": null, "pronunciation": "yán hǎi", "ipa": "jɛn˧˥ xaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "中国的沿海有很多大城市。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的工厂把东西卖到国外。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是沿海，不是内地。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的港口每天都有很多船。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沿海建了一个新机场。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的经济比内地发展得快。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条高速公路连着沿海和内地。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风过后，沿海的农民开始修房子。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿海的渔民早上就出海打鱼了。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人去沿海找工作。", "target_word": "沿海", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿海地带", "label": "复合"}, {"form": "沿海城市", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠近海岸的地带，地理和经济的角度，与内地相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '535bc513-1eb8-43f4-ac82-0543e4e571a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沿海", "is_correct": true, "explanation": "沿海：靠近海岸的地带，城市较多，与“有很多大城市”相合。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原地广人稀，城市很少，不符合“有很多大城市”。"}, {"text": "农村", "is_correct": false, "explanation": "搭配：“农村”与“大城市”相对，不说农村有很多大城市。"}, {"text": "牧场", "is_correct": false, "explanation": "语义：牧场是放牧牲畜的地方，一般不会有大城市，与「有很多大城市」不合。"}], "explanations": {"沿海": "沿海：靠近海岸的地带，城市较多，与“有很多大城市”相合。", "草原": "语义：草原地广人稀，城市很少，不符合“有很多大城市”。", "农村": "搭配：“农村”与“大城市”相对，不说农村有很多大城市。", "牧场": "语义：牧场是放牧牲畜的地方，一般不会有大城市，与「有很多大城市」不合。"}, "sentence_index": 0, "correct_answer": "沿海"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的沿海地区有很多农田。", "explanation": "这里应该用〈沿河〉。沿海指靠着大海的地方，河边一带要用〈沿河〉。"}, {"text": "这条街的沿海店铺很多。", "explanation": "这里应该用〈沿街〉。沿海指靠着大海的地方，街边的店铺要用〈沿街〉。"}, {"text": "这条高速公路的沿海地区有很多工厂。", "explanation": "这里应该用〈沿线〉。沿海指靠着大海的地带，公路旁边要用〈沿线〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沿海", "is_correct": true, "explanation": "沿海：靠近海岸的地带，与“和内地”相对，构成地区对比。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被公路连接，句子不通。"}, {"text": "云端", "is_correct": false, "explanation": "语义：云端是虚指的高处，公路无法连到那里。"}, {"text": "梦境", "is_correct": false, "explanation": "搭配：“连着”后接的是地点，不说连着梦境。"}], "explanations": {"沿海": "沿海：靠近海岸的地带，与“和内地”相对，构成地区对比。", "天空": "语义：天空不能被公路连接，句子不通。", "云端": "语义：云端是虚指的高处，公路无法连到那里。", "梦境": "搭配：“连着”后接的是地点，不说连着梦境。"}, "sentence_index": 6, "correct_answer": "沿海"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条江的沿海地区很繁华。", "explanation": "这里应该用〈沿江〉。沿海指靠着大海的地方，江边一带要用〈沿江〉。"}, {"text": "这条铁路的沿海有很多车站。", "explanation": "这里应该用〈沿线〉。沿海指靠近海岸的地带，铁路两旁一带要用〈沿线〉。"}, {"text": "这个湖很大，沿海有很多餐厅。", "explanation": "这里应该用〈沿湖〉。沿海指靠着大海的地方，湖边要用〈沿湖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅在沿海里开了一家工厂。", "corrected_sentence": "我舅舅在沿海开了一家工厂。", "error_description": "错误在“沿海”后多加了方位词“里”。“沿海”是地区名词，不能加“里”，应说“在沿海开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的表哥沿海做生意。", "corrected_sentence": "我的表哥在沿海做生意。", "error_description": "错误在“沿海”前缺少介词“在”。“沿海”作地点状语时要加“在”，应说“在沿海做生意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c51cccb7-a79d-4351-9efa-1bbd38e9ee48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。"}, {"text": "打开", "is_correct": false, "explanation": "无关：“打开”不表示传承或保留，与“流传”没有反义关系。"}, {"text": "关闭", "is_correct": false, "explanation": "无关：“关闭”指使门窗、开关等停止开放，与“流传”没有反义关系。"}, {"text": "移动", "is_correct": false, "explanation": "无关：“移动”指位置的改变，与“一代代传下去”这一义无关。"}], "correct_answer": "失传", "explanations": {"失传": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。", "打开": "无关：“打开”不表示传承或保留，与“流传”没有反义关系。", "关闭": "无关：“关闭”指使门窗、开关等停止开放，与“流传”没有反义关系。", "移动": "无关：“移动”指位置的改变，与“一代代传下去”这一义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。"}, {"text": "收回", "is_correct": false, "explanation": "无关：“收回”指把已经给出的东西要回来，与“一代代传下去”没有关系。"}, {"text": "逃跑", "is_correct": false, "explanation": "无关：“逃跑”指迅速离开以躲避危险，与“一代代传下去”没有关系。"}, {"text": "扔掉", "is_correct": false, "explanation": "无关：“扔掉”指丢弃，与“一代代传下去”没有反义关系。"}], "correct_answer": "失传", "explanations": {"失传": "正确：“失传”与“流传”在“一代代传下去”这一义上相反，指传承中断。", "收回": "无关：“收回”指把已经给出的东西要回来，与“一代代传下去”没有关系。", "逃跑": "无关：“逃跑”指迅速离开以躲避危险，与“一代代传下去”没有关系。", "扔掉": "无关：“扔掉”指丢弃，与“一代代传下去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "故事、传说、习俗等一代代传下去，保留至今。", "primary_collocate": null, "pronunciation": "liú chuán", "ipa": "ljoʊ˧˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "这个故事在我们村里流传了几百年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说这个习俗是祖先流传下来的。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首民歌从古代一直流传到现在。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的菜谱代代流传着。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于长城的传说流传了两千多年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老故事从奶奶传给妈妈，一直流传下来。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书在中国流传了很多年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地流传着一个古老的传说。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多古诗至今还在流传。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法已经流传了上百年。", "target_word": "流传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流传着", "label": "体标"}, {"form": "流传过", "label": "体标"}, {"form": "流传下来", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事、传说、习俗等一代一代往下传，保留至今", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7730a907-17d6-4070-8ade-01789c2b16ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流传", "is_correct": true, "explanation": "正确：“流传了几百年”指故事在村里一代代传下来，符合语境。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的对象是活动、展览，故事不能说“举办了几百年”。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事情在某一时刻出现，不能表示延续几百年。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品或资料，故事不能被“收藏了几百年”。"}], "explanations": {"流传": "正确：“流传了几百年”指故事在村里一代代传下来，符合语境。", "举办": "搭配：“举办”的对象是活动、展览，故事不能说“举办了几百年”。", "发生": "语义：“发生”指事情在某一时刻出现，不能表示延续几百年。", "收藏": "搭配：“收藏”的对象是物品或资料，故事不能被“收藏了几百年”。"}, "sentence_index": 0, "correct_answer": "流传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要流传民族文化。", "explanation": "这里应该用〈传承〉。流传指故事、习俗等自然地一代代传下来，主动有意识地把文化接续下去要用〈传承〉。"}, {"text": "老师把新课本流传给了每个学生。", "explanation": "这里应该用〈发〉。流传指故事、习俗等一代代自然传下来，把课本分给学生要用〈发〉。"}, {"text": "他流传了父亲的事业。", "explanation": "这里应该用〈继承〉。流传说的是事物在人群中传开，接收前人留下的事业要用〈继承〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流传", "is_correct": true, "explanation": "正确：“流传了很多年”指书在中国一直被传阅、保存，符合语境。"}, {"text": "施工", "is_correct": false, "explanation": "搭配：“施工”的对象是建筑、工程，书不能“施工了很多年”。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等建筑，书不能被“修建”。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”指把物体射出或送入太空，与书在中国传阅的情境不符。"}], "explanations": {"流传": "正确：“流传了很多年”指书在中国一直被传阅、保存，符合语境。", "施工": "搭配：“施工”的对象是建筑、工程，书不能“施工了很多年”。", "修建": "搭配：“修建”的对象是房屋、道路等建筑，书不能被“修建”。", "发射": "语义：“发射”指把物体射出或送入太空，与书在中国传阅的情境不符。"}, "sentence_index": 6, "correct_answer": "流传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的深色眼睛流传自母亲。", "explanation": "这里应该用〈遗传〉。流传指故事、习俗等在人们中一代代传下来，眼睛颜色这类生理特征由父母传给子女要用〈遗传〉。"}, {"text": "博物馆流传了很多古画。", "explanation": "这里应该用〈收藏〉。流传指事物一代代传下去，博物馆把古画收存保管要用〈收藏〉。"}, {"text": "这场火灾很快流传到了整栋楼。", "explanation": "这里应该用〈扩散〉。流传指消息、说法辗转传开，火势向四周蔓延要用〈扩散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门手艺一直流传来。", "corrected_sentence": "这门手艺一直流传下来。", "error_description": "错误：“流传来”；正确：“流传下来”。“流传”后须接趋向补语“下来”，表示一代代传下去，缺少“下”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个古老的歌谣被流传了好几代。", "corrected_sentence": "这个古老的歌谣流传了好几代。", "error_description": "错误：“被流传”；正确：“流传”。“流传”是不及物动词，不能用“被”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed372619-d457-4ac1-9882-809ee2c7e7f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
