INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "淘汰是比赛时输了的人要离开，不能再比。", "primary_collocate": null, "pronunciation": "táo tài", "ipa": "tʰɑʊ˧˥ tʰai˥˩", "syllable_count": 2, "sentences": [{"text": "这场比赛淘汰了八个队。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一轮比赛淘汰了一半的人。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "输了的队就淘汰了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛一共淘汰了五个选手。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们队在半决赛淘汰了对手。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "输一场就淘汰，所以大家都很紧张。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥昨天在比赛里淘汰了三个人。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们队很快就淘汰出局了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛每天淘汰一个人，最后只有三个人。", "target_word": "淘汰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在歌唱比赛中被淘汰了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "淘汰了", "label": "体标（完成）"}, {"form": "被淘汰", "label": "被动式"}], "register": "中性", "sense_fingerprint": "比赛中输的人出局，不能继续比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：比赛中输掉的队伍出局，不能继续比赛，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地方，不能说“打扫了八个队”。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的宾语是活动，不是队伍，“举办八个队”搭配不当。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”的宾语是节目，不能用于“队”。"}], "explanations": {"淘汰": "淘汰：比赛中输掉的队伍出局，不能继续比赛，符合句意。", "打扫": "搭配：“打扫”的对象是房间、地方，不能说“打扫了八个队”。", "举办": "搭配：“举办”的宾语是活动，不是队伍，“举办八个队”搭配不当。", "表演": "搭配：“表演”的宾语是节目，不能用于“队”。"}, "sentence_index": 0, "correct_answer": "淘汰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们队淘汰了这次比赛。", "explanation": "这里应该用〈赢得〉。淘汰只用于队伍或选手出局，比赛本身不能被淘汰。"}, {"text": "学校淘汰了这次歌唱比赛的奖金。", "explanation": "这里应该用〈发放〉。淘汰是使选手或队伍出局，奖金不能被淘汰，应说发放。"}, {"text": "他淘汰了这座城市。", "explanation": "这里应该用〈离开〉。淘汰是使选手或队伍出局，城市不能被淘汰，应说“他离开了这座城市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：在比赛中输掉而出局，符合句意。"}, {"text": "辩论", "is_correct": false, "explanation": "语义：“辩论”是就问题争论，与在比赛里淘汰人不符。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”的对象是作品或方案，不能说“设计三个人”。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”的对象是文章或计划，不能说“修改三个人”。"}], "explanations": {"淘汰": "淘汰：在比赛中输掉而出局，符合句意。", "辩论": "语义：“辩论”是就问题争论，与在比赛里淘汰人不符。", "设计": "搭配：“设计”的对象是作品或方案，不能说“设计三个人”。", "修改": "搭配：“修改”的对象是文章或计划，不能说“修改三个人”。"}, "sentence_index": 6, "correct_answer": "淘汰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在歌唱比赛中淘汰了一首歌。", "explanation": "这里应该用〈演唱〉。淘汰用于选手或队伍出局，歌曲不能被淘汰出局，应说演唱。"}, {"text": "评委淘汰了她的掌声。", "explanation": "这里应该用〈获得〉。淘汰是使选手或队伍出局，掌声不能被淘汰，应说获得。"}, {"text": "选手淘汰了领先。", "explanation": "这里应该用〈保持〉。淘汰是使人出局，“领先”这种状态不能被淘汰，应说保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
