INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场比赛被淘汰了四个队。", "corrected_sentence": "这场比赛淘汰了四个队。", "error_description": "“淘汰”带宾语“四个队”时不能加“被”。“这场比赛被淘汰了四个队”错误，应去掉“被”，说“这场比赛淘汰了四个队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
