INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在竞争中去掉不合格或落后的；被去掉。", "primary_collocate": null, "pronunciation": "táo tài", "ipa": "tʰɑʊ˧˥ tʰai˥˩", "syllable_count": 2, "sentences": [{"text": "这种旧手机早就淘汰了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司淘汰了很多旧机器。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场会淘汰不好的产品。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校淘汰了这些旧桌子。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂把旧设备都淘汰了。", "target_word": "淘汰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种慢电脑现在没人用，已经淘汰了。", "target_word": "淘汰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年淘汰几个工作不好的人。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店淘汰了过时的商品。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公平的竞争会淘汰落后的做法。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种车太旧了，早就该淘汰了。", "target_word": "淘汰", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "淘汰了", "label": "体标（完成）"}, {"form": "被淘汰", "label": "被动式"}], "register": "中性", "sense_fingerprint": "去掉不合格或落后的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afddcc02-8f51-4ae4-9a81-fb0515ef9584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：在竞争中去掉落后或不合格的东西，旧手机已经落后，符合句意。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学生完成学业，手机不能毕业。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象应是人或人的行为，不能用于手机。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：手机没有意志，不能“拒绝”，句意不通。"}], "explanations": {"淘汰": "淘汰：在竞争中去掉落后或不合格的东西，旧手机已经落后，符合句意。", "毕业": "语义：“毕业”指学生完成学业，手机不能毕业。", "表扬": "搭配：“表扬”的对象应是人或人的行为，不能用于手机。", "拒绝": "语义：手机没有意志，不能“拒绝”，句意不通。"}, "sentence_index": 0, "correct_answer": "淘汰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们淘汰了电脑里的病毒。", "explanation": "这里应该用〈清除〉。淘汰指因落后或不合格而被替换，病毒不属于这一类，应说清除。"}, {"text": "我把刚买的新衣服淘汰了。", "explanation": "这里应该用〈送人〉。淘汰指去掉不合格或落后的东西，刚买的新衣服不属于这种情况，应说送人。"}, {"text": "他淘汰了这封信。", "explanation": "这里应该用〈撕掉〉。淘汰针对不合格或落后的对象，信件不属于这类，应说撕掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "淘汰", "is_correct": true, "explanation": "淘汰：去掉工作不好、落后的人，符合句意。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是给好的表现，与“工作不好”的人相矛盾。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，与“工作不好”的人相矛盾。"}, {"text": "表彰", "is_correct": false, "explanation": "搭配：“表彰”多用于先进人物或突出成绩，不能与“工作不好的人”搭配。"}], "explanations": {"淘汰": "淘汰：去掉工作不好、落后的人，符合句意。", "奖励": "语义：“奖励”是给好的表现，与“工作不好”的人相矛盾。", "夸奖": "语义：“夸奖”是称赞，与“工作不好”的人相矛盾。", "表彰": "搭配：“表彰”多用于先进人物或突出成绩，不能与“工作不好的人”搭配。"}, "sentence_index": 6, "correct_answer": "淘汰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们淘汰了合格的人才。", "explanation": "这里应该用〈挑选〉。淘汰针对不合格或落后的对象，合格的人才不能用淘汰。"}, {"text": "他淘汰了一杯热茶。", "explanation": "这里应该用〈喝〉。淘汰指去掉不合格或落后的人或事物，喝茶不能说淘汰。"}, {"text": "他淘汰了这次晚会。", "explanation": "这里应该用〈参加〉。淘汰指去掉不合格或落后的人或事物，晚会不属于这种情况，应说参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把这张旧桌子淘汰。", "corrected_sentence": "学校把这张旧桌子淘汰了。", "error_description": "“把”字句中，动词“淘汰”后面要带“了”等成分才完整。“学校把这张旧桌子淘汰”不完整，应说“学校把这张旧桌子淘汰了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "商店被淘汰了过时的电器。", "corrected_sentence": "商店淘汰了过时的电器。", "error_description": "“淘汰”是及物动词，“被淘汰”后面不能再带宾语“过时的电器”。“被”多余，应去掉，说“商店淘汰了过时的电器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a297d623-2c51-4397-85b7-01608988de1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
