INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94537, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无辜是自己没有做错事，却被怪罪。", "primary_collocate": null, "pronunciation": "wú gū", "ipa": "u˧˥ ku˥", "syllable_count": 2, "sentences": [{"text": "我什么都没做，真的很无辜。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有偷东西，大家却都说是我，我真无辜。", "target_word": "无辜", "complexity_tier": "T3", "furigana": "wú gū", "sentence_source": "generated"}, {"text": "我根本没参与这件事，却被大家怪罪，觉得很无辜。", "target_word": "无辜", "complexity_tier": "T3", "furigana": "wú gū", "sentence_source": "generated"}, {"text": "明明不是我的错，大家都怪我，我好无辜。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有做错任何事，却被老师批评了，真无辜。", "target_word": "无辜", "complexity_tier": "T3", "furigana": "wú gū", "sentence_source": "generated"}, {"text": "妈妈骂了我，可是我觉得很无辜。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事跟我没关系，我很无辜。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她摇摇头，说自己真的很无辜。", "target_word": "无辜", "complexity_tier": "T3", "furigana": "wú gū", "sentence_source": "generated"}, {"text": "孩子们吵架，却都怪我，我这个路人真无辜。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学迟到了，却怪我没叫他，我太无辜了。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無辜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没做错事却被怪罪，感到委屈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无辜", "is_correct": true, "explanation": "正确。“无辜”表示没做错事却被怪罪，与“真的很”后面的感受相符。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“勤快”表示经常干活，与“我什么都没做”正相反，句意矛盾。"}, {"text": "积极", "is_correct": false, "explanation": "语义：“积极”表示主动努力，与“我什么都没做”矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容身高，与“什么都没做”没有关系，句子说不通。"}], "explanations": {"无辜": "正确。“无辜”表示没做错事却被怪罪，与“真的很”后面的感受相符。", "勤快": "语义：“勤快”表示经常干活，与“我什么都没做”正相反，句意矛盾。", "积极": "语义：“积极”表示主动努力，与“我什么都没做”矛盾。", "高": "体貌：“高”形容身高，与“什么都没做”没有关系，句子说不通。"}, "sentence_index": 0, "correct_answer": "无辜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无辜地放弃了比赛。", "explanation": "这里应该用〈无奈〉。“无奈地放弃”指迫不得已而放弃；“无辜”说的是没做错事却被怪罪，不能用来形容放弃比赛这个行为。"}, {"text": "这件事跟我完全无辜。", "explanation": "这里应该用〈无关〉。“跟我无关”指与我没有联系；“无辜”说的是人没做错事，不能用来说事情与我的关系。"}, {"text": "他无辜地旷了三天工。", "explanation": "这里应该用〈无故〉。“无故旷工”指没有理由地缺勤；“无辜”说的是没做错事却被怪罪，不表示没有理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无辜", "is_correct": true, "explanation": "正确。“无辜”表示没做错事却被怪罪，与“这件事跟我没关系”的语境相符。"}, {"text": "热心", "is_correct": false, "explanation": "语义：“热心”指乐于帮助，与“这件事跟我没关系”不相符。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指身体需要食物，与“这件事跟我没关系”的语境毫不相干。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身材，不能用来表达对这件事的感受。"}], "explanations": {"无辜": "正确。“无辜”表示没做错事却被怪罪，与“这件事跟我没关系”的语境相符。", "热心": "语义：“热心”指乐于帮助，与“这件事跟我没关系”不相符。", "饿": "语义：“饿”指身体需要食物，与“这件事跟我没关系”的语境毫不相干。", "瘦": "体貌：“瘦”形容身材，不能用来表达对这件事的感受。"}, "sentence_index": 6, "correct_answer": "无辜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这门学科很无辜。", "explanation": "这里应该用〈无知〉。“无知”指缺少知识，“无辜”不能表示对学科的了解程度。"}, {"text": "这条老街的名声很无辜。", "explanation": "这里应该用〈清白〉。“清白”可以用于名声，“无辜”说的是人没做错事，不用来形容名声。"}, {"text": "那几块旧木板已经无辜了。", "explanation": "这里应该用〈无用〉。“无用”指东西没有用处，“无辜”只指人没有过错，不能用于木板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得我是无辜的的。", "corrected_sentence": "我觉得我是无辜的。", "error_description": "错误：句末多写了一个“的”。“是……的”只需要一个“的”，应说“我觉得我是无辜的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察查清楚了，那个司机是无辜地。", "corrected_sentence": "警察查清楚了，那个司机是无辜的。", "error_description": "错误：“是……的”句中要用“的”，不能用“地”。“地”放在动词前面修饰动作，这里应说“那个司机是无辜的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94538, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有罪", "is_correct": true, "explanation": "正确。“有罪”指犯了罪或有过错，与“无辜”正相反，是这一义项的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“无辜”没有反义关系。"}, {"text": "健康", "is_correct": false, "explanation": "“健康”形容身体状况，与“无辜”没有反义关系。"}, {"text": "勤快", "is_correct": false, "explanation": "“勤快”形容愿意干活，与“无辜”没有反义关系。"}], "correct_answer": "有罪", "explanations": {"有罪": "正确。“有罪”指犯了罪或有过错，与“无辜”正相反，是这一义项的反义词。", "聪明": "“聪明”形容智力，与“无辜”没有反义关系。", "健康": "“健康”形容身体状况，与“无辜”没有反义关系。", "勤快": "“勤快”形容愿意干活，与“无辜”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
