INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94538, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有罪过的；没有过错的。", "primary_collocate": null, "pronunciation": "wú gū", "ipa": "u˧˥ ku˥", "syllable_count": 2, "sentences": [{"text": "法官证明他是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓错了人，他是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子完全是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直说自己无辜。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过调查，大家知道她是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想伤害无辜的人。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无辜的人不应该坐牢。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证据说明这位老人是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐了十年牢，其实他是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板相信我是无辜的。", "target_word": "无辜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无辜者", "label": "复合词"}, {"form": "無辜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "没有罪过、没有过错的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无辜", "is_correct": true, "explanation": "正确。“无辜”指没有罪过，与“法官证明”的结论相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，法官证明的是事实，不会证明一个人身材高大。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色，与法官证明的罪责或清白毫无关系。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”形容形状，用来修饰人说不通，句子无法成立。"}], "explanations": {"无辜": "正确。“无辜”指没有罪过，与“法官证明”的结论相符。", "高大": "体貌：“高大”形容身材，法官证明的是事实，不会证明一个人身材高大。", "红": "语义：“红”是颜色，与法官证明的罪责或清白毫无关系。", "圆": "体貌：“圆”形容形状，用来修饰人说不通，句子无法成立。"}, "sentence_index": 0, "correct_answer": "无辜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很无辜。", "explanation": "这里应该用〈优秀〉。“优秀”形容成绩好；“无辜”只说人没有罪过，不能用来形容成绩。"}, {"text": "他无辜地答应了朋友的请求。", "explanation": "这里应该用〈无奈〉。“无奈地答应”指迫不得已而答应；“无辜”说的是人没有罪过，不能用来描述答应这个动作。"}, {"text": "这两件事完全无辜。", "explanation": "这里应该用〈无关〉。“无关”指两件事没有联系；“无辜”说的是人没有罪过，不能用来形容事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无辜", "is_correct": true, "explanation": "正确。“无辜”指没有罪过，无辜的人不该坐牢，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，用来修饰人毫无道理，与坐牢的语境不符。"}, {"text": "硬", "is_correct": false, "explanation": "体貌：“硬”形容质地，用来形容人说不通，与句子的意思不相符。"}, {"text": "方", "is_correct": false, "explanation": "体貌：“方”形容形状，用来形容人与“坐牢”的语境完全无关。"}], "explanations": {"无辜": "正确。“无辜”指没有罪过，无辜的人不该坐牢，符合句意。", "甜": "语义：“甜”形容味道，用来修饰人毫无道理，与坐牢的语境不符。", "硬": "体貌：“硬”形容质地，用来形容人说不通，与句子的意思不相符。", "方": "体貌：“方”形容形状，用来形容人与“坐牢”的语境完全无关。"}, "sentence_index": 6, "correct_answer": "无辜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对历史很无辜。", "explanation": "这里应该用〈无知〉。“无知”指缺少知识，“无辜”只说人没有罪过，不能用来形容对历史的了解程度。"}, {"text": "他的名声很无辜。", "explanation": "这里应该用〈清白〉。“清白”可以用于名声，“无辜”说的是人没有罪过，不用来形容名声。"}, {"text": "这些旧书已经无辜了。", "explanation": "这里应该用〈无用〉。“无用”指东西没有用处，“无辜”只指人没有过错，不能用来形容书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "律师坚持说当事人是无辜的的。", "corrected_sentence": "律师坚持说当事人是无辜的。", "error_description": "错误：句末多写了一个“的”。“是……的”只需要一个“的”，应说“律师坚持说当事人是无辜的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察抓了一条无辜的人。", "corrected_sentence": "警察抓了一个无辜的人。", "error_description": "量词错误：“人”的量词用“个”或“位”，不能用“条”；应说“一个无辜的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
