INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "培养日常生活能力和习惯的教育。", "primary_collocate": null, "pronunciation": "shēng huó jiào yù", "ipa": "ʂɤŋ˥ xuɔ˧˥ tɕjɑʊ˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "幼儿园很重视生活教育。", "target_word": "生活教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生活教育要从小开始。", "target_word": "生活教育", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校给孩子上生活教育课。", "target_word": "生活教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣服、做饭都是生活教育的内容。", "target_word": "生活教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生活教育能让孩子更独立。", "target_word": "生活教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个夏令营的生活教育很有名。", "target_word": "生活教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长也要做好孩子的生活教育。", "target_word": "生活教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校每周有一节生活教育课。", "target_word": "生活教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活教育让他学会了自己整理房间。", "target_word": "生活教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多家长觉得生活教育和学习一样重要。", "target_word": "生活教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生活教育|名词|培养日常生活能力和习惯的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81aba494-6514-4052-93d8-2027c397c7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活教育", "is_correct": true, "explanation": "生活教育指培养日常生活能力的教育，与幼儿园的教育内容相符，句意通顺。"}, {"text": "高考", "is_correct": false, "explanation": "语义：「高考」是高中升学考试，幼儿园不涉及，句意不通。"}, {"text": "研究生", "is_correct": false, "explanation": "语义：「研究生」指高等教育阶段的学生，与幼儿园的语境不符，句意不通。"}, {"text": "汇率", "is_correct": false, "explanation": "语义：「汇率」与幼儿园的教育内容无关，句意不通。"}], "explanations": {"生活教育": "生活教育指培养日常生活能力的教育，与幼儿园的教育内容相符，句意通顺。", "高考": "语义：「高考」是高中升学考试，幼儿园不涉及，句意不通。", "研究生": "语义：「研究生」指高等教育阶段的学生，与幼儿园的语境不符，句意不通。", "汇率": "语义：「汇率」与幼儿园的教育内容无关，句意不通。"}, "sentence_index": 0, "correct_answer": "生活教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们每天都在为考试复习，生活教育的压力很大。", "explanation": "这里应该用〈应试教育〉。〈生活教育〉侧重日常生活能力的培养，不是考试带来的压力。"}, {"text": "这个城市的生活教育很高。", "explanation": "这里应该用〈生活水平〉。〈生活教育〉是一种教育，不能用“高”来形容一个城市的生活状况。"}, {"text": "这家超市的生活教育很便宜。", "explanation": "这里应该用〈生活用品〉。〈生活教育〉是教育活动，不是商品，不能用“便宜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活教育", "is_correct": true, "explanation": "生活教育是培养孩子日常生活能力的教育，与「做好孩子的」搭配，符合句意。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：「做好」通常修饰事情或工作，不说「做好学费」，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「做好天气」不成立，「做好」不能修饰天气，句意不通。"}, {"text": "电池", "is_correct": false, "explanation": "语义：「电池」不是可以「做好」的教育内容，与孩子的生活能力无关，句意不通。"}], "explanations": {"生活教育": "生活教育是培养孩子日常生活能力的教育，与「做好孩子的」搭配，符合句意。", "学费": "搭配：「做好」通常修饰事情或工作，不说「做好学费」，句意不通。", "天气": "搭配：「做好天气」不成立，「做好」不能修饰天气，句意不通。", "电池": "语义：「电池」不是可以「做好」的教育内容，与孩子的生活能力无关，句意不通。"}, "sentence_index": 6, "correct_answer": "生活教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根生活教育很长。", "explanation": "这里应该用〈绳子〉。〈生活教育〉是抽象的教育活动，不能用量词「根」，也不能说“很长”。"}, {"text": "很多老年人注重养生，生活教育很健康。", "explanation": "这里应该用〈生活方式〉。〈生活教育〉是一种教育，不能用“健康”来形容一个人的生活方式。"}, {"text": "这个生活教育很甜，我每天都吃。", "explanation": "这里应该用〈零食〉。〈生活教育〉是教育活动，不能吃，也不能用“甜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区每个月都组织一本生活教育。", "corrected_sentence": "社区每个月都组织一次生活教育。", "error_description": "「生活教育」作为活动计量时应用「次」，不能用「本」（「本」用于书籍）。正确的是：社区每个月都组织一次生活教育。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师认为生活教育得内容很实用。", "corrected_sentence": "老师认为生活教育的内容很实用。", "error_description": "结构助词错误：修饰名词「内容」时应用「的」，不能用「得」（「得」用于补语）。错误形式：生活教育得内容；正确形式：生活教育的内容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bd80528-d127-4906-a385-29bc3f42f99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
