INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94543, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "由此是说从刚才说的这件事开始。", "primary_collocate": null, "pronunciation": "yóu cǐ", "ipa": "jou˧˥ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他说完这句话，新的讨论由此开始。", "target_word": "由此", "complexity_tier": "T3", "furigana": "tā shuō wán zhè jù huà xīn de tǎolùn yóu cǐ kāishǐ", "sentence_source": "generated"}, {"text": "他们的友谊由此开始。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完老师的解释，我们的学习由此开始。", "target_word": "由此", "complexity_tier": "T3", "furigana": "tīng wán lǎoshī de jiěshì wǒmen de xuéxí yóu cǐ kāishǐ", "sentence_source": "generated"}, {"text": "这个故事由此开始，一直讲到今天。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说先学拼音，我的汉语学习由此开始。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在中国过了春节，新的生活由此开始。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把房间打扫干净，整理工作由此开始。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家讨论完这个问题，新的研究由此开始。", "target_word": "由此", "complexity_tier": "T3", "furigana": "dàjiā tǎolùn wán zhège wèntí xīn de yánjiū yóu cǐ kāishǐ", "sentence_source": "generated"}, {"text": "大家握了手，两家人的合作由此开始。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束后，他的新计划由此开始。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "由此：从刚才说的这件事或这个地方开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "由此", "is_correct": true, "explanation": "由此：从刚才说的这件事开始，与“开始”搭配，符合句意。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：仍然表示持续不变，与“新的讨论”所表示的起点义相冲突。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：一直表示持续进行，不能与表示起点的“开始”搭配。"}, {"text": "再", "is_correct": false, "explanation": "语义：再表示重新，与“新的”讨论不能同时成立。"}], "explanations": {"由此": "由此：从刚才说的这件事开始，与“开始”搭配，符合句意。", "仍然": "语义：仍然表示持续不变，与“新的讨论”所表示的起点义相冲突。", "一直": "搭配：一直表示持续进行，不能与表示起点的“开始”搭配。", "再": "语义：再表示重新，与“新的”讨论不能同时成立。"}, "sentence_index": 0, "correct_answer": "由此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "由此十年，他成了一名医生。", "explanation": "这里应该用〈十年后〉。由此只能从前面的事情推出结论，或指从这件事开始，不能表示一段时间之后。"}, {"text": "由此明天开始，我们每天六点起床。", "explanation": "这里应该用〈从〉。由此要指向前面已经提到的事情或地点，不能直接接“明天”这样的时间词。"}, {"text": "由此他搬来以后，这条街变得很热闹。", "explanation": "这里应该用〈自从〉。由此不能用来引出一段时间的起点，表示从某个时间起要说自从。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由此", "is_correct": true, "explanation": "由此：从前面的事情（打扫房间）之后开始，与“先…”的先后顺序相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：曾经表示过去发生过，与“先”所表示的正在进行的先后顺序不符。"}, {"text": "反而", "is_correct": false, "explanation": "配价：反而要求前文有与预期相反的情况，这句前文没有这样的情况。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：竟然表示出乎意料，与“先把房间打扫干净”这种按部就班的语境不合。"}], "explanations": {"由此": "由此：从前面的事情（打扫房间）之后开始，与“先…”的先后顺序相合。", "曾经": "语义：曾经表示过去发生过，与“先”所表示的正在进行的先后顺序不符。", "反而": "配价：反而要求前文有与预期相反的情况，这句前文没有这样的情况。", "竟然": "语义：竟然表示出乎意料，与“先把房间打扫干净”这种按部就班的语境不合。"}, "sentence_index": 6, "correct_answer": "由此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "由此小时候起，他就喜欢画画。", "explanation": "这里应该用〈打从〉。由此要指向前面提到的事情或地方，不能接“小时候起”这样的时间起点。"}, {"text": "由此春节以来，他的身体越来越好了。", "explanation": "这里应该用〈自从〉。由此只能指向前面提到的事情或地点，不能直接接“春节”这样的时间词；表示从某个时间以来要说“自从春节以来”。"}, {"text": "由此上个月，他每天都去跑步。", "explanation": "这里应该用〈从〉。由此要指向前面已经说过的事情，不能直接接“上个月”这样的时间词，应说“从上个月起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动从由此开始。", "corrected_sentence": "这次活动由此开始。", "error_description": "“由此”已经包含“从这件事开始”的意思，前面再加“从”就重复了，应删掉“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的学期从由此开始。", "corrected_sentence": "新的学期由此开始。", "error_description": "“由此”已经包含“从这里开始”的意思，前面再加“从”就重复了，应删掉“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
