INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94544, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，根据前面的情况得出结论或引出结果，相当于“因此”。", "primary_collocate": null, "pronunciation": "yóu cǐ", "ipa": "jou˧˥ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每天都最早到学校，由此可见他很认真。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上全是水，由此可知昨晚下过大雨。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得很开心，由此看来，考试一定考得不错。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们做了很多调查，由此得出了这个结论。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有很多人排队，由此可见这家店很受欢迎。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到旧照片，由此想到了小时候的生活。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一天只睡四个小时，由此带来了很多健康问题。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不说话，由此看来，他们不同意这个办法。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水越来越少，由此引起了人们的注意。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书都很旧，由此可知它们已经有很多年了。", "target_word": "由此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "由此：根据前面的情况，得出结论或引出结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7831dbf0-2d1a-405b-a9bd-3c644e931314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "由此", "is_correct": true, "explanation": "由此：根据前面“早到”的事实推出“他很认真”的结论，与“可见”搭配，符合句意。"}, {"text": "然而", "is_correct": false, "explanation": "语义：然而表示转折，与“由此可见”表示的推论不相符。"}, {"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，前后内容并不相反，不能用来引出结论。"}, {"text": "否则", "is_correct": false, "explanation": "配价：否则要求前面是条件或命令，这句前文只是陈述，不能接“否则”。"}], "explanations": {"由此": "由此：根据前面“早到”的事实推出“他很认真”的结论，与“可见”搭配，符合句意。", "然而": "语义：然而表示转折，与“由此可见”表示的推论不相符。", "但是": "语义：但是表示转折，前后内容并不相反，不能用来引出结论。", "否则": "配价：否则要求前面是条件或命令，这句前文只是陈述，不能接“否则”。"}, "sentence_index": 0, "correct_answer": "由此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会说英语，由此还会说法语。", "explanation": "这里应该用〈此外〉。由此表示由前面推出的结论，而“会说英语”和“会说法语”之间没有因果关系，要在前面内容之外补充时用〈此外〉。"}, {"text": "他很努力，由此成绩不好。", "explanation": "这里应该用〈然而〉。由此表示由前面推出的结论，而“很努力”和“成绩不好”是转折关系，要用〈然而〉。"}, {"text": "我以为他很忙，由此他在睡觉。", "explanation": "这里应该用〈原来〉。由此表示由前面推出的结论，而这里是说话人发现了真实情况，要用〈原来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由此", "is_correct": true, "explanation": "由此：引出睡眠少带来的结果，与“带来”的因果语境相合。"}, {"text": "不过", "is_correct": false, "explanation": "语义：不过表示转折，前后内容并不相反，不符合因果关系。"}, {"text": "可是", "is_correct": false, "explanation": "语义：可是表示转折，前后内容并不相反，与“由此带来”的因果关系不合；另外口语色彩较强，与书面语体不合。"}, {"text": "反而", "is_correct": false, "explanation": "语义：反而表示出乎意料，睡眠少带来健康问题本在意料之中，不能用反而。"}], "explanations": {"由此": "由此：引出睡眠少带来的结果，与“带来”的因果语境相合。", "不过": "语义：不过表示转折，前后内容并不相反，不符合因果关系。", "可是": "语义：可是表示转折，前后内容并不相反，与“由此带来”的因果关系不合；另外口语色彩较强，与书面语体不合。", "反而": "语义：反而表示出乎意料，睡眠少带来健康问题本在意料之中，不能用反而。"}, "sentence_index": 6, "correct_answer": "由此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你要带伞，由此淋湿。", "explanation": "这里应该用〈以免〉。由此表示由前面推出的结论，不能表示为避免某种情况而采取的行动；“带伞”是为了不淋湿，要用〈以免〉。"}, {"text": "由此下雨，我们就不去。", "explanation": "这里应该用〈如果〉。由此只能引出由前面推出的结论，不能引出假设条件；“下雨”还没有发生，是假设，要用〈如果〉。"}, {"text": "由此天气冷，我们没去爬山。", "explanation": "这里应该用〈因为〉。由此用于引出结论，不能引出原因；这里“天气冷”是原因，应用〈因为〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每次都提前到校，由此可是他很守时。", "corrected_sentence": "他每次都提前到校，由此可见他很守时。", "error_description": "“由此可见”是固定搭配，“见”不能换成“是”。“可是”表示转折，与前面的因果推论不合；应说“由此可见他很守时”，不能说“由此可是他很守时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里很暖和，从由此可知暖气开了。", "corrected_sentence": "屋里很暖和，由此可知暖气开了。", "error_description": "“由此”本身已经包含“从这里推出”的意思，前面再加“从”就重复了，应删掉“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7747be2b-3591-47c9-b017-325251ba6d58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
