INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "与某件事有直接关系的人。", "primary_collocate": null, "pronunciation": "dāng shì rén", "ipa": "taŋ˥ ʂɻ̩˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "法官请双方当事人坐下。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同上有两位当事人的名字。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这起交通事故有三个当事人。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师正在帮当事人写材料。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当事人没有在合同上签字。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察让所有当事人留下电话。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当事人的意见很重要。", "target_word": "当事人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不是当事人，不能决定这件事。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生和病人都是这次事件的当事人。", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师说：“请当事人放心。”", "target_word": "当事人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位当事人", "label": "量词"}, {"form": "當事人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "当事人|名词|与事件有直接关系的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec13897d-af07-46b2-a20a-db12a5ed8bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当事人", "is_correct": true, "explanation": "当事人指争议双方中的每一方，「法官请双方当事人坐下」通顺。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不能被请去坐下。"}, {"text": "证据", "is_correct": false, "explanation": "语义：证据是材料，不能被请去坐下。"}, {"text": "旁听者", "is_correct": false, "explanation": "搭配：「双方」指争议的两方，旁听者不属于双方。"}], "explanations": {"当事人": "当事人指争议双方中的每一方，「法官请双方当事人坐下」通顺。", "窗户": "语义：窗户不是人，不能被请去坐下。", "证据": "语义：证据是材料，不能被请去坐下。", "旁听者": "搭配：「双方」指争议的两方，旁听者不属于双方。"}, "sentence_index": 0, "correct_answer": "当事人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子是这次事故的当事人。", "explanation": "这里应该用〈物品〉。当事人指与事情有直接关系的人，桌子不是人，不能做当事人。"}, {"text": "我只是在电视上看到这件事，我是这件事的当事人。", "explanation": "这里应该用〈旁观者〉。只在电视上看到的人与事情没有直接关系，不是当事人。"}, {"text": "今天的天气是比赛的当事人。", "explanation": "这里应该用〈因素〉。当事人只能指人，天气不能做当事人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当事人", "is_correct": true, "explanation": "当事人的意见很重要，「当事人的意见很重要」通顺。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不能有意见。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有意见。"}, {"text": "判决", "is_correct": false, "explanation": "搭配：意见属于人，不能说「判决的意见」。"}], "explanations": {"当事人": "当事人的意见很重要，「当事人的意见很重要」通顺。", "墙": "语义：墙不能有意见。", "天气": "语义：天气没有意见。", "判决": "搭配：意见属于人，不能说「判决的意见」。"}, "sentence_index": 6, "correct_answer": "当事人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同上有一只当事人签了字。", "explanation": "这里应该用〈位〉。〈当事人〉指人，应数作〈位〉，不能用来数动物或成对物品。"}, {"text": "这份合同上有一本当事人签了字。", "explanation": "这里应该用〈位〉。〈当事人〉指人，应数作〈位〉，不能用来数书籍等物品。"}, {"text": "这份合同上有一条当事人签了字。", "explanation": "这里应该用〈位〉。〈当事人〉指人，应数作〈位〉，不能用来数细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只当事人都同意了这个方案。", "corrected_sentence": "双方当事人都同意了这个方案。", "error_description": "错误：「两只当事人」。正确：「双方当事人」。「只」不能用来数人，指人应用「双方」或「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '855becb3-2dc7-46ad-bb43-da58ca3488a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
