INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94550, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体因受伤或生病而产生的难受感觉。", "primary_collocate": null, "pronunciation": "téng", "ipa": "tʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他的腿受伤了，现在还很疼。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我感冒了，嗓子特别疼。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后，伤口疼了三天。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，一直说胸口疼。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手划破了，疼得很厉害。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我扭伤了脚，走路时很疼。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，肚子不那么疼了。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问他：“伤口还疼不疼？”", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打球时摔倒，膝盖又红又疼。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙发炎了，我连喝水都疼。", "target_word": "疼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疼了", "label": "体标"}, {"form": "疼过", "label": "体标"}], "register": "口语", "sense_fingerprint": "身体因受伤或生病而感到难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16ad29f2-6d3f-4c2f-a448-5904d0d176f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94550, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疼", "is_correct": true, "explanation": "正确答案：疼 téng，意思是受伤或生病后身体难受。"}, {"text": "糖", "is_correct": false, "explanation": "táng（第二声）与 téng 韵母不同（ang/eng），意思是糖。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 téng 韵母不同（ing/eng），意思是停止。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 téng 韵母不同（o/e），意思是相同。"}, {"text": "能", "is_correct": false, "explanation": "néng（第二声）与 téng 声母不同（n/t），意思是能够。"}], "explanations": {"疼": "正确答案：疼 téng，意思是受伤或生病后身体难受。", "糖": "táng（第二声）与 téng 韵母不同（ang/eng），意思是糖。", "停": "tíng（第二声）与 téng 韵母不同（ing/eng），意思是停止。", "同": "tóng（第二声）与 téng 韵母不同（o/e），意思是相同。", "能": "néng（第二声）与 téng 声母不同（n/t），意思是能够。"}, "sentence_index": null, "correct_answer": "疼"}, "level_3": {"options": [{"text": "结实", "is_correct": false, "explanation": "语义：“结实”指牢固有力，与“腿受伤了”矛盾。"}, {"text": "疼", "is_correct": true, "explanation": "正确答案：疼。“现在还很疼”说明受伤后的难受感觉。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”表示人的心情，不能用来形容腿。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外观，与伤后的感受无关。"}], "explanations": {"结实": "语义：“结实”指牢固有力，与“腿受伤了”矛盾。", "疼": "正确答案：疼。“现在还很疼”说明受伤后的难受感觉。", "高兴": "搭配：“高兴”表示人的心情，不能用来形容腿。", "漂亮": "体貌：“漂亮”形容外观，与伤后的感受无关。"}, "sentence_index": 0, "correct_answer": "疼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次手术后，他的腿疼了，什么感觉也没有。", "explanation": "这里应该用〈麻〉。麻指失去知觉，与“什么感觉也没有”相符；疼表示有痛感，两者矛盾。"}, {"text": "这碗饭很疼，我一点胃口都没有。", "explanation": "这里应该用〈香〉。香指气味好，与饭菜相符；疼指身体的难受感觉，不能形容饭菜。"}, {"text": "房间里的灯很疼，我睡不着。", "explanation": "这里应该用〈亮〉。亮指光线强，与灯相符；疼指身体的痛感，不能形容灯光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94550, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "疼", "is_correct": true, "explanation": "正确答案：疼 téng，意思是受伤或生病后身体难受。"}, {"text": "堂", "is_correct": false, "explanation": "táng（第二声）与 téng 韵母不同（ang/eng），意思是厅堂。"}, {"text": "亭", "is_correct": false, "explanation": "tíng（第二声）与 téng 韵母不同（ing/eng），意思是亭子。"}, {"text": "童", "is_correct": false, "explanation": "tóng（第二声）与 téng 韵母不同（o/e），意思是儿童。"}], "explanations": {"疼": "正确答案：疼 téng，意思是受伤或生病后身体难受。", "堂": "táng（第二声）与 téng 韵母不同（ang/eng），意思是厅堂。", "亭": "tíng（第二声）与 téng 韵母不同（ing/eng），意思是亭子。", "童": "tóng（第二声）与 téng 韵母不同（o/e），意思是儿童。"}, "sentence_index": null, "correct_answer": "疼"}, "level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外观好看，不能用来说明肚子的状态。"}, {"text": "疼", "is_correct": true, "explanation": "正确答案：疼。“肚子不那么疼了”说明吃药后痛感减轻。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，与肚子的不适没有关系。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明事情或看得明白，不能用来形容肚子。"}], "explanations": {"漂亮": "体貌：“漂亮”形容外观好看，不能用来说明肚子的状态。", "疼": "正确答案：疼。“肚子不那么疼了”说明吃药后痛感减轻。", "亮": "语义：“亮”指光线明亮，与肚子的不适没有关系。", "清楚": "搭配：“清楚”说明事情或看得明白，不能用来形容肚子。"}, "sentence_index": 6, "correct_answer": "疼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的小腿很疼，一直想用手挠一挠。", "explanation": "这里应该用〈痒〉。痒是皮肤发痒的感觉，所以想挠；疼指痛感，与“想挠”不符。"}, {"text": "他熬了一整夜，疼得直打哈欠，眼皮都抬不起来。", "explanation": "这里应该用〈困〉。打哈欠、眼皮抬不起来说明想睡，与“熬夜”相符；疼指痛感，与此不符。"}, {"text": "放假的第一天，我睡到自然醒，觉得很疼。", "explanation": "这里应该用〈舒服〉。舒服指身体感觉良好，与“睡到自然醒”相符；疼表示痛感，与此相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑车摔倒后，膝盖疼很，走路都困难。", "corrected_sentence": "他骑车摔倒后，膝盖很疼，走路都困难。", "error_description": "错误：“疼很”。正确应为“很疼”。程度副词“很”应放在形容词“疼”前面表示程度，放在“疼”后面不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一不小心碰到了热锅，手心疼的直叫。", "corrected_sentence": "我一不小心碰到了热锅，手心疼得直叫。", "error_description": "错误：“疼的”。“的”连接名词或定语，不能修饰动词“叫”；应为“疼得”，“得”引出程度补语，表示疼到什么程度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5afb40d-8bb7-48f5-9340-300f962d7b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
