INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "确切的一百年时间，即一个世纪。", "primary_collocate": null, "pronunciation": "bǎi nián", "ipa": "paɪ̯²¹⁴ nʲɛn³⁵", "syllable_count": 2, "sentences": [{"text": "这所学校有百年历史。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个世纪就是百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔从动工到竣工，前后恰好百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年是学校成立百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是1900年到2000年这百年的故事。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百年里，这座城市换了三个名字。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树种下到今年，正好百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的茶店是1925年开的，到今年正好百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去百年中，世界变化很大。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥建于1925年，到今年整整百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "百年老店", "label": "复合"}], "register": "中性", "sense_fingerprint": "确切的一百年时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1426ce4-1f9f-4599-b218-e53fd9592105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：百年，bǎi nián，指确切的一百年。"}, {"text": "拜年", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是新年互相问候。"}, {"text": "半年", "is_correct": false, "explanation": "bàn（第四声）与 bǎi（第三声）韵母不同（an 与 ai），声调也不同，意思是六个月。"}, {"text": "八年", "is_correct": false, "explanation": "bā（第一声）与 bǎi（第三声）韵母、声调都不同，意思是八个年头。"}], "explanations": {"百年": "正确：百年，bǎi nián，指确切的一百年。", "拜年": "bài（第四声）与 bǎi（第三声）声调不同，意思是新年互相问候。", "半年": "bàn（第四声）与 bǎi（第三声）韵母不同（an 与 ai），声调也不同，意思是六个月。", "八年": "bā（第一声）与 bǎi（第三声）韵母、声调都不同，意思是八个年头。"}, "sentence_index": null, "correct_answer": "百年"}, "level_3": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：“百年历史”指一百年的历史，是确切的时间。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”不是时间，不能用来表示学校有多少年的历史。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“名声”不能用来衡量“历史”的长短，“有……历史”需要时间词。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”指房间，不能说“有教室历史”来表示年数。"}], "explanations": {"百年": "正确：“百年历史”指一百年的历史，是确切的时间。", "食堂": "语义：“食堂”不是时间，不能用来表示学校有多少年的历史。", "名声": "搭配：“名声”不能用来衡量“历史”的长短，“有……历史”需要时间词。", "教室": "语义：“教室”指房间，不能说“有教室历史”来表示年数。"}, "sentence_index": 0, "correct_answer": "百年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔只用了三个礼拜就建好了，却说花了百年。", "explanation": "这里应该用〈几周〉。三周就能建好的工程不能说花了“百年”，“百年”指确切的一百年，与几周的时长不符。"}, {"text": "他今年百年了。", "explanation": "这里应该用〈百岁〉。说人的年龄用“百岁”，“百年”不用于人的年纪。"}, {"text": "他百年都在这所学校工作。", "explanation": "这里应该用〈一辈子〉。“百年”指一个世纪或很长的时间，不能当作“一辈子”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：“正好”后接确切的时间长度，“百年”就是一百年。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”指一顿饭，不是时间长度。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是时间，不能说种下到今年“正好歌曲”。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是物品，不能表示时间长度。"}], "explanations": {"百年": "正确：“正好”后接确切的时间长度，“百年”就是一百年。", "午饭": "语义：“午饭”指一顿饭，不是时间长度。", "歌曲": "语义：“歌曲”不是时间，不能说种下到今年“正好歌曲”。", "眼镜": "语义：“眼镜”是物品，不能表示时间长度。"}, "sentence_index": 6, "correct_answer": "百年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的时长是百年。", "explanation": "这里应该用〈三分钟〉。歌曲时长以分钟计，“百年”指确切的一百年，不能用来表示歌曲的长度。"}, {"text": "这辆车的百年只有五年。", "explanation": "这里应该用〈寿命〉。说物体能用多久要用“寿命”，“百年”不能指车的使用年限。"}, {"text": "他百年都在这条河边生活。", "explanation": "这里应该用〈一生〉。“百年”指一个世纪或很长的时间，不能当作“一生”来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校已经有一位百年了。", "corrected_sentence": "这所学校已经有百年了。", "error_description": "量词错误：“位”只用于人，不能修饰时间词“百年”，应说“有百年了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥到今年很百年了。", "corrected_sentence": "这座桥到今年整整百年了。", "error_description": "副词错误：“很”不修饰“百年”这样的时间词，可说“整整百年了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
