INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不指确切数目，引申指很长的时间。", "primary_collocate": null, "pronunciation": "bǎi nián", "ipa": "paɪ̯²¹⁴ nʲɛn³⁵", "syllable_count": 2, "sentences": [{"text": "这座桥已经有百年的历史了。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百年以后，这里会变成什么样？", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店是百年老店。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树活了百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百年来，这个城市变化很大。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一座百年的老房子。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事在这里流传了百年。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生不过百年，要好好生活。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的友谊，百年也不会变。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百年前，这里只有一条小路。", "target_word": "百年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "百年老店", "label": "复合"}], "register": "中性", "sense_fingerprint": "非确切数目，引申为很长的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1426ce4-1f9f-4599-b218-e53fd9592105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：百年，bǎi nián，指一百年，也指很长的时间。"}, {"text": "拜年", "is_correct": false, "explanation": "bài（第四声）与 bǎi（第三声）声调不同，意思是新年互相问候。"}, {"text": "半年", "is_correct": false, "explanation": "bàn（第四声）与 bǎi（第三声）韵母不同（an 与 ai），声调也不同，意思是六个月。"}, {"text": "八年", "is_correct": false, "explanation": "bā（第一声）与 bǎi（第三声）韵母、声调都不同，意思是八个年头。"}], "explanations": {"百年": "正确：百年，bǎi nián，指一百年，也指很长的时间。", "拜年": "bài（第四声）与 bǎi（第三声）声调不同，意思是新年互相问候。", "半年": "bàn（第四声）与 bǎi（第三声）韵母不同（an 与 ai），声调也不同，意思是六个月。", "八年": "bā（第一声）与 bǎi（第三声）韵母、声调都不同，意思是八个年头。"}, "sentence_index": null, "correct_answer": "百年"}, "level_3": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：“百年”指很长的时间，可以与“的历史”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是材料，不是时间段，不能说“有石头的历史”。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”不能修饰“历史”，“有……的历史”要用表示时间长度的词。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”与这座桥无关，不能说这座桥有“地图的历史”。"}], "explanations": {"百年": "正确：“百年”指很长的时间，可以与“的历史”搭配。", "石头": "语义：“石头”是材料，不是时间段，不能说“有石头的历史”。", "寿命": "搭配：“寿命”不能修饰“历史”，“有……的历史”要用表示时间长度的词。", "地图": "语义：“地图”与这座桥无关，不能说这座桥有“地图的历史”。"}, "sentence_index": 0, "correct_answer": "百年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶今年百年了。", "explanation": "这里应该用〈百岁〉。说人的年龄用“百岁”，“百年”指时间长度，不能用来说人今年多大。"}, {"text": "这份合同的百年是三年。", "explanation": "这里应该用〈期限〉。合同的期限是约定的时长，“百年”指很长的时间，不能用来表示合同的期限。"}, {"text": "这学期已经过了百年。", "explanation": "这里应该用〈几个月〉。一个学期只有几个月，“百年”表示很长的时间，与学期的长度不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "百年", "is_correct": true, "explanation": "正确：“流传了”后接时间长度，“百年”可以作时量补语。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“流传了”后接的是时间长度，不接“历史”这样的名词。"}, {"text": "名声", "is_correct": false, "explanation": "语义：“名声”是对人或事物的评价，不指时间长短，这里需要表示时长的词。"}, {"text": "习惯", "is_correct": false, "explanation": "配价：“流传”不带“习惯”这样的事物作宾语，这里只能接时间长度。"}], "explanations": {"百年": "正确：“流传了”后接时间长度，“百年”可以作时量补语。", "历史": "搭配：“流传了”后接的是时间长度，不接“历史”这样的名词。", "名声": "语义：“名声”是对人或事物的评价，不指时间长短，这里需要表示时长的词。", "习惯": "配价：“流传”不带“习惯”这样的事物作宾语，这里只能接时间长度。"}, "sentence_index": 6, "correct_answer": "百年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的百年只有十年。", "explanation": "这里应该用〈寿命〉。说物体能用多久要用“寿命”，“百年”不能指机器的使用年限。"}, {"text": "这个工程从开工到竣工只用了百年。", "explanation": "这里应该用〈几个月〉。“只用了”强调时间短，“百年”表示很长的时间，二者矛盾。"}, {"text": "他的鞋码是百年。", "explanation": "这里应该用〈四十二〉。鞋码是尺码数字，“百年”是时间，不能用来表示鞋码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f236f9d7-d95c-4d5d-b81b-187f1cb6024e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
