INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇后是国王或皇帝的妻子。", "primary_collocate": null, "pronunciation": "huáng hòu", "ipa": "xwɑŋ˧˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "国王和皇后住在很大的城堡里。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇后是国王的妻子。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王请皇后一起去花园散步。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的皇后很善良，常常帮助穷人。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王去世以后，皇后一个人管理国家。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的皇后生了一个可爱的小王子。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王给皇后买了一条很漂亮的项链。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在话剧里演皇后，穿着长长的裙子。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇后站在城堡的窗前，看着花园。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王和皇后都很爱他们的女儿。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "皇后娘娘", "label": "复合"}], "register": "中性", "sense_fingerprint": "国王或皇帝的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇后", "is_correct": true, "explanation": "皇后：国王或皇帝的妻子，与“国王”同住城堡，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是物品，不能和“国王”并列作为住在城堡里的人。"}, {"text": "船", "is_correct": false, "explanation": "搭配：“住”要求有生命的主语，“船”不能和国王并列作居住的主体。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是场所，不是人，不能与“国王”并列作为住在城堡里的人。"}], "explanations": {"皇后": "皇后：国王或皇帝的妻子，与“国王”同住城堡，符合句意。", "椅子": "语义：“椅子”是物品，不能和“国王”并列作为住在城堡里的人。", "船": "搭配：“住”要求有生命的主语，“船”不能和国王并列作居住的主体。", "花园": "语义：“花园”是场所，不是人，不能与“国王”并列作为住在城堡里的人。"}, "sentence_index": 0, "correct_answer": "皇后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是宫里的皇后，每天负责打扫院子。", "explanation": "这里应该用〈宫女〉。皇后指国王或皇帝的妻子，负责打扫的侍女要用〈宫女〉。"}, {"text": "英国的皇后伊丽莎白二世统治了国家很多年。", "explanation": "这里应该用〈女王〉。皇后指国王或皇帝的妻子，君主本人是女性时称〈女王〉。"}, {"text": "王子的妻子是皇后，大家都叫她殿下。", "explanation": "这里应该用〈王妃〉。皇后只指皇帝的正妻，王子的妻子称〈王妃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇后", "is_correct": true, "explanation": "皇后：国王的妻子，是国王送项链的对象，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，不能作为国王买礼物的对象。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不能成为收礼的人，与“给”的对象不符。"}, {"text": "云", "is_correct": false, "explanation": "搭配：“买”给某人作礼物，“云”不能作为买东西送礼的对象。"}], "explanations": {"皇后": "皇后：国王的妻子，是国王送项链的对象，符合句意。", "石头": "语义：“石头”不是人，不能作为国王买礼物的对象。", "桌子": "语义：“桌子”是物品，不能成为收礼的人，与“给”的对象不符。", "云": "搭配：“买”给某人作礼物，“云”不能作为买东西送礼的对象。"}, "sentence_index": 6, "correct_answer": "皇后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "皇帝有很多皇后，个个都很受宠。", "explanation": "这里应该用〈妃子〉。皇后是皇帝唯一的正妻，其他妻妾要用〈妃子〉。"}, {"text": "国王的女儿是皇后。", "explanation": "这里应该用〈公主〉。国王的女儿是公主，皇后指国王或皇帝的妻子，二者身份不同。"}, {"text": "邻居家的皇后很会做饭，大家都夸她。", "explanation": "这里应该用〈夫人〉。皇后只用于国王或皇帝的妻子，普通人家的妻子称〈夫人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宴会上来了一只皇后。", "corrected_sentence": "宴会上来了一位皇后。", "error_description": "量词错误：皇后指人，量词应用“位”，“只”多用于动物；应说“一位皇后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国王去世后，一位善良的皇后们管理着国家。", "corrected_sentence": "国王去世后，一位善良的皇后管理着国家。", "error_description": "错误：「们」表示复数，不能与数量词「一位」同用，应删去「们」，说「一位善良的皇后」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
