INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇帝的正妻。", "primary_collocate": null, "pronunciation": "huáng hòu", "ipa": "xwɑŋ˧˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "古代皇帝的妻子叫皇后。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝很爱他的皇后。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位皇后帮皇帝处理了很多事。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝生病时，皇后每天都陪着他。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这部古装剧里演皇帝的皇后。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝和皇后一起坐马车去了山上。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新皇后是皇帝从全国选出来的。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇后住在后宫里。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝送了皇后一块白玉。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写过一位帮皇帝管国家的皇后。", "target_word": "皇后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "皇后娘娘", "label": "复合"}], "register": "中性", "sense_fingerprint": "皇帝的正妻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皇后", "is_correct": true, "explanation": "皇后：皇帝的正妻，与“古代皇帝的妻子”一致，是句中要填的词。"}, {"text": "太后", "is_correct": false, "explanation": "语义：“太后”指皇帝的母亲，不是皇帝的妻子，与句意矛盾。"}, {"text": "公主", "is_correct": false, "explanation": "语义：“公主”指皇帝的女儿，不能称皇帝的妻子。"}, {"text": "皇冠", "is_correct": false, "explanation": "搭配：“叫”后面接人的称谓，“皇冠”是物品，不能作为妻子的称呼。"}], "explanations": {"皇后": "皇后：皇帝的正妻，与“古代皇帝的妻子”一致，是句中要填的词。", "太后": "语义：“太后”指皇帝的母亲，不是皇帝的妻子，与句意矛盾。", "公主": "语义：“公主”指皇帝的女儿，不能称皇帝的妻子。", "皇冠": "搭配：“叫”后面接人的称谓，“皇冠”是物品，不能作为妻子的称呼。"}, "sentence_index": 0, "correct_answer": "皇后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皇帝的女儿是皇后，每天都来看他。", "explanation": "这里应该用〈公主〉。皇帝的女儿是公主，皇后指皇帝的正妻，二者身份不同。"}, {"text": "皇帝的母亲是皇后，每天都来看他。", "explanation": "这里应该用〈太后〉。皇后是皇帝的正妻，皇帝的母亲称〈太后〉。"}, {"text": "皇帝的儿子是皇后。", "explanation": "这里应该用〈皇子〉。皇后只指皇帝的正妻，皇帝的儿子称〈皇子〉，不能叫皇后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皇后", "is_correct": true, "explanation": "皇后：皇帝的正妻，可以由皇帝从全国选出，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是人，不能作为皇帝选出的对象。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然事物，与“皇帝从全国选出来的”这一语境不符。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“选出来”的对象应是人，“雨水”不能被皇帝选出来。"}], "explanations": {"皇后": "皇后：皇帝的正妻，可以由皇帝从全国选出，符合句意。", "月亮": "语义：“月亮”不是人，不能作为皇帝选出的对象。", "河流": "语义：“河流”是自然事物，与“皇帝从全国选出来的”这一语境不符。", "雨水": "搭配：“选出来”的对象应是人，“雨水”不能被皇帝选出来。"}, "sentence_index": 6, "correct_answer": "皇后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宫里的皇后很多，个个都很受宠。", "explanation": "这里应该用〈嫔妃〉。皇后是皇帝唯一的正妻，其他妃嫔要用〈嫔妃〉。"}, {"text": "皇帝的妹妹被封为皇后。", "explanation": "这里应该用〈公主〉。皇后只能封给皇帝的正妻，皇帝的妹妹应被封为〈公主〉。"}, {"text": "英国的皇后玛丽一世统治着整个国家。", "explanation": "这里应该用〈女王〉。皇后指皇帝的正妻，女性君主称〈女王〉，玛丽一世不是君主的妻子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宫里住着一座皇后。", "corrected_sentence": "宫里住着一位皇后。", "error_description": "量词错误：皇后指人，量词应用“位”，“座”用于建筑等；应说“一位皇后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宫里住着一位美丽的皇后们。", "corrected_sentence": "宫里住着一位美丽的皇后。", "error_description": "错误：「们」表示复数，不能与数量词「一位」同用，应删去「们」，说「一位美丽的皇后」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
