INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94555, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看出是看了以后发现了什么。", "primary_collocate": null, "pronunciation": "kàn chū", "ipa": "kʰan˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "我看出墙上有一道裂缝。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看出他的腿受了伤。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一眼就看出这张画是假的。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看出我哭过。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看出这张桌子少了一条腿。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了半天，才看出两张照片不一样。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很快看出了地图上的错误。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看出天要下雨，就回家了。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看出他今天换了新手机。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看出作业本上有一个错字。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看出了", "label": "体标"}, {"form": "看不出", "label": "可能补语否定式"}, {"form": "看得出", "label": "可能补语肯定式"}], "register": "中性", "sense_fingerprint": "看了之后发现某个事物或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”指看了以后发现了某种情况。"}, {"text": "干出", "is_correct": false, "explanation": "干（gàn，第四声）与 kàn 声母不同（g 与 k），意思是做出、干出来。"}, {"text": "刊出", "is_correct": false, "explanation": "刊（kān，第一声）与 kàn 声调不同，意思是登出、刊登出来。"}, {"text": "喊出", "is_correct": false, "explanation": "喊（hǎn，第三声）与 kàn 声母不同（h 与 k），声调也不同，意思是大声叫出来。"}], "explanations": {"看出": "正确。“看出”指看了以后发现了某种情况。", "干出": "干（gàn，第四声）与 kàn 声母不同（g 与 k），意思是做出、干出来。", "刊出": "刊（kān，第一声）与 kàn 声调不同，意思是登出、刊登出来。", "喊出": "喊（hǎn，第三声）与 kàn 声母不同（h 与 k），声调也不同，意思是大声叫出来。"}, "sentence_index": null, "correct_answer": "看出"}, "level_3": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”表示看了以后发现墙上的裂缝，与句意相符。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”需要可以买卖的对象，裂缝不能被买，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与墙上的裂缝毫无关系。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，“墙上有一道裂缝”不能被写。"}], "explanations": {"看出": "正确。“看出”表示看了以后发现墙上的裂缝，与句意相符。", "买": "搭配：“买”需要可以买卖的对象，裂缝不能被买，句子说不通。", "吃": "语义：“吃”指进食，与墙上的裂缝毫无关系。", "写": "搭配：“写”的对象是文字，“墙上有一道裂缝”不能被写。"}, "sentence_index": 0, "correct_answer": "看出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看出了一阵香味。", "explanation": "这里应该用〈闻出〉。“看出”靠视觉发现情况，闻到气味要用“闻出”，不能用“看出”。"}, {"text": "这部电影我看出了三遍。", "explanation": "这里应该用〈看〉。看电影、看书要用“看”，“看出”表示通过观察发现情况。"}, {"text": "我终于看出了那阵鸟叫。", "explanation": "这里应该用〈听出〉。鸟叫要靠耳朵辨认，“看出”靠视觉，不能用来感知声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94555, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”指看了以后发现了某种情况。"}, {"text": "赶出", "is_correct": false, "explanation": "赶（gǎn，第三声）与 kàn 声母不同（g 与 k），声调也不同，意思是驱逐出去。"}, {"text": "砍出", "is_correct": false, "explanation": "砍（kǎn，第三声）与 kàn 声母韵母相同，只是声调不同，意思是用刀斧砍出来。"}, {"text": "看书", "is_correct": false, "explanation": "“书”（shū）与“出”（chū）只有声母不同（sh 与 ch），“看书”是常用短语，意思是读书。"}], "explanations": {"看出": "正确。“看出”指看了以后发现了某种情况。", "赶出": "赶（gǎn，第三声）与 kàn 声母不同（g 与 k），声调也不同，意思是驱逐出去。", "砍出": "砍（kǎn，第三声）与 kàn 声母韵母相同，只是声调不同，意思是用刀斧砍出来。", "看书": "“书”（shū）与“出”（chū）只有声母不同（sh 与 ch），“看书”是常用短语，意思是读书。"}, "sentence_index": null, "correct_answer": "看出"}, "level_3": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”表示发现了地图上的错误，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于“错误”，句中是发现错误而不是唱错误。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与地图上的错误毫不相干。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”的对象是气味，地图上的错误不能用鼻子闻。"}], "explanations": {"看出": "正确。“看出”表示发现了地图上的错误，与句意相符。", "唱": "搭配：“唱”不能用于“错误”，句中是发现错误而不是唱错误。", "喝": "语义：“喝”指饮用，与地图上的错误毫不相干。", "闻": "搭配：“闻”的对象是气味，地图上的错误不能用鼻子闻。"}, "sentence_index": 6, "correct_answer": "看出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她看出了一阵花香。", "explanation": "这里应该用〈闻出〉。花香要用鼻子闻，“看出”靠视觉发现情况，不能用来感知气味。"}, {"text": "我看出了他的声音。", "explanation": "这里应该用〈听出〉。通过听来辨认声音要用“听出”，“看出”靠视觉发现情况，不能用来辨认声音。"}, {"text": "他看出了那道菜的酸味。", "explanation": "这里应该用〈尝出〉。酸味要用舌头辨别，“看出”不能用来感知味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不看出墙上有裂缝。", "corrected_sentence": "我没看出墙上有裂缝。", "error_description": "错误：否定“看出”应说“没看出”，用“不看出”不符合习惯说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板看出得店里的账目有问题。", "corrected_sentence": "老板看出了店里的账目有问题。", "error_description": "错误：“看出”后的完成标记应用“了”，不能用“得”。“得”只用于“看得出”这类可能补语，写成“看出得”不通顺，正确说法是“看出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
