INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94556, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过观察发现或辨别出来。", "primary_collocate": null, "pronunciation": "kàn chū", "ipa": "kʰan˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "我看出他在说谎。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从她的眼睛里，我看出了她的紧张。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看出我没有认真听课。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都看出他不想去。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看出这个人很可靠。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看出这个年轻人很有才能。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有看出哪张画是真的。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看出我有心事，就问了我。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看出了对方的想法，所以没有说话。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们看出这场比赛会很难。", "target_word": "看出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看出了", "label": "体标"}, {"form": "看不出", "label": "可能补语否定式"}, {"form": "看得出", "label": "可能补语肯定式"}], "register": "中性", "sense_fingerprint": "通过观察辨别、判断出某种情况或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913192cc-a3f8-4592-8386-3e743a80734d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”指通过观察辨别出某种情况或想法。"}, {"text": "赶出", "is_correct": false, "explanation": "赶（gǎn，第三声）与 kàn 声母不同（g 与 k），声调也不同，意思是驱逐出去。"}, {"text": "刊出", "is_correct": false, "explanation": "刊（kān，第一声）与 kàn 声调不同，意思是登出、刊登出来。"}, {"text": "看书", "is_correct": false, "explanation": "“书”（shū）与“出”（chū）只有声母不同（sh 与 ch），“看书”是常用短语，意思是读书。"}], "explanations": {"看出": "正确。“看出”指通过观察辨别出某种情况或想法。", "赶出": "赶（gǎn，第三声）与 kàn 声母不同（g 与 k），声调也不同，意思是驱逐出去。", "刊出": "刊（kān，第一声）与 kàn 声调不同，意思是登出、刊登出来。", "看书": "“书”（shū）与“出”（chū）只有声母不同（sh 与 ch），“看书”是常用短语，意思是读书。"}, "sentence_index": null, "correct_answer": "看出"}, "level_3": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”表示通过观察判断出他在说谎，与句意相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服，不能用来接“他在说谎”这样的句子。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，与说谎毫无关系。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是物体表面，不能接“他在说谎”，句子说不通。"}], "explanations": {"看出": "正确。“看出”表示通过观察判断出他在说谎，与句意相符。", "穿": "搭配：“穿”的对象是衣服，不能用来接“他在说谎”这样的句子。", "烧": "语义：“烧”指燃烧或加热，与说谎毫无关系。", "擦": "搭配：“擦”的对象是物体表面，不能接“他在说谎”，句子说不通。"}, "sentence_index": 0, "correct_answer": "看出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看出了一阵雨声。", "explanation": "这里应该用〈听出〉。雨声要靠耳朵辨认，“看出”靠视觉发现情况，不能用来感知声音。"}, {"text": "小王看出了一首好歌。", "explanation": "这里应该用〈写出〉。“写出一首好歌”指创作出歌曲；“看出”指通过观察发现情况，不能用于创作。"}, {"text": "他看出了一阵甜味。", "explanation": "这里应该用〈尝出〉。甜味要用舌头辨别，“看出”不能用来感知味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94556, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”指通过观察辨别出某种情况。"}, {"text": "干出", "is_correct": false, "explanation": "干（gàn，第四声）与 kàn 声母不同（g 与 k），意思是做出、干出来。"}, {"text": "砍出", "is_correct": false, "explanation": "砍（kǎn，第三声）与 kàn 声母韵母相同，只是声调不同，意思是用刀斧砍出来。"}, {"text": "喊出", "is_correct": false, "explanation": "喊（hǎn，第三声）与 kàn 声母不同（h 与 k），声调也不同，意思是大声叫出来。"}], "explanations": {"看出": "正确。“看出”指通过观察辨别出某种情况。", "干出": "干（gàn，第四声）与 kàn 声母不同（g 与 k），意思是做出、干出来。", "砍出": "砍（kǎn，第三声）与 kàn 声母韵母相同，只是声调不同，意思是用刀斧砍出来。", "喊出": "喊（hǎn，第三声）与 kàn 声母不同（h 与 k），声调也不同，意思是大声叫出来。"}, "sentence_index": null, "correct_answer": "看出"}, "level_3": {"options": [{"text": "看出", "is_correct": true, "explanation": "正确。“看出”与“没有”搭配，表示没有辨别出哪张画是真的，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与画的真假毫不相干。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是照片或衣物，不能接“哪张画是真的”。"}, {"text": "画", "is_correct": false, "explanation": "搭配：“画”指绘制，与辨别画的真假无关，“画哪张画”说不通。"}], "explanations": {"看出": "正确。“看出”与“没有”搭配，表示没有辨别出哪张画是真的，符合句意。", "唱": "语义：“唱”指发出歌声，与画的真假毫不相干。", "洗": "搭配：“洗”的对象是照片或衣物，不能接“哪张画是真的”。", "画": "搭配：“画”指绘制，与辨别画的真假无关，“画哪张画”说不通。"}, "sentence_index": 6, "correct_answer": "看出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看出了一阵汽油味。", "explanation": "这里应该用〈闻出〉。汽油味要用鼻子闻，“看出”靠视觉发现情况，不能用来感知气味。"}, {"text": "他看出了一顿饭。", "explanation": "这里应该用〈做〉。“做饭”指动手准备饭菜；“看出”指通过观察发现情况，不能用于做饭。"}, {"text": "我看出了一阵雷声。", "explanation": "这里应该用〈听出〉。雷声要靠耳朵辨认，“看出”靠视觉，不能用来感知声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不看出那个孩子在撒谎。", "corrected_sentence": "我没看出那个孩子在撒谎。", "error_description": "错误：否定“看出”应说“没看出”，用“不看出”不符合习惯说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师看出得小明的心思。", "corrected_sentence": "老师看出了小明的心思。", "error_description": "错误：“看出”后的完成标记应用“了”，不能用“得”。“得”只用于“看得出”这类可能补语，写成“看出得”不通顺，正确说法是“看出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55f9ea9-720e-41ed-b3a1-8cba0d09a742') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谬误", "is_correct": true, "explanation": "反义：谬误指错误的认识或道理，与“真理”正相对。"}, {"text": "习俗", "is_correct": false, "explanation": "无反义关系：习俗指社会上长期形成的风俗习惯，与“真理”不构成反义。"}, {"text": "童话", "is_correct": false, "explanation": "无反义关系：童话是虚构的故事，与“真理”不是相对的概念。"}, {"text": "梦想", "is_correct": false, "explanation": "无反义关系：梦想指对未来的美好愿望，不与“真理”相对。"}], "correct_answer": "谬误", "explanations": {"谬误": "反义：谬误指错误的认识或道理，与“真理”正相对。", "习俗": "无反义关系：习俗指社会上长期形成的风俗习惯，与“真理”不构成反义。", "童话": "无反义关系：童话是虚构的故事，与“真理”不是相对的概念。", "梦想": "无反义关系：梦想指对未来的美好愿望，不与“真理”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谬误", "is_correct": true, "explanation": "反义：谬误指错误的认识或道理，与“真理”正相对。"}, {"text": "传说", "is_correct": false, "explanation": "无反义关系：传说指口头流传的故事，与“真理”不是相对的概念。"}, {"text": "习惯", "is_correct": false, "explanation": "无反义关系：习惯指长期形成的行为方式，与“真理”不构成反义。"}, {"text": "故事", "is_correct": false, "explanation": "无反义关系：故事指叙述人或事的作品，与“真理”不构成反义。"}], "correct_answer": "谬误", "explanations": {"谬误": "反义：谬误指错误的认识或道理，与“真理”正相对。", "传说": "无反义关系：传说指口头流传的故事，与“真理”不是相对的概念。", "习惯": "无反义关系：习惯指长期形成的行为方式，与“真理”不构成反义。", "故事": "无反义关系：故事指叙述人或事的作品，与“真理”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真理是大家都知道是对的、不会错的道理。", "primary_collocate": null, "pronunciation": "zhēn lǐ", "ipa": "ʈʂən˥ li˨˩", "syllable_count": 2, "sentences": [{"text": "人都会老，这是一条真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳从东边升起，这是真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常说，好人有好报是真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，诚实就是最大的真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话大家都信，好像是真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一加一等于二，这是永远的真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“水往低处流是真理吗？”", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些话听起来简单，却是真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，吃一堑长一智是真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能改变这个真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝对真理", "label": "复合词"}, {"form": "相对真理", "label": "复合词"}], "register": "书面", "sense_fingerprint": "人人认可、不会错的道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 堑 (Zipf 2.32)']::text[], '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真理", "is_correct": true, "explanation": "正确。“这是一条真理”指大家都认可、不会错的道理，句意通顺。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“人都会老”是一条道理，不能说它是一条河流。"}, {"text": "裙子", "is_correct": false, "explanation": "语义：“人都会老”说的是道理，不是衣物，不能说是一条裙子。"}, {"text": "段子", "is_correct": false, "explanation": "语义：段子指笑话或小故事，“人都会老”是一个普遍的道理，不是笑话。"}], "explanations": {"真理": "正确。“这是一条真理”指大家都认可、不会错的道理，句意通顺。", "河流": "语义：“人都会老”是一条道理，不能说它是一条河流。", "裙子": "语义：“人都会老”说的是道理，不是衣物，不能说是一条裙子。", "段子": "语义：段子指笑话或小故事，“人都会老”是一个普遍的道理，不是笑话。"}, "sentence_index": 0, "correct_answer": "真理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题的真理是三十五。", "explanation": "这里应该用〈答案〉。真理指普遍的道理，不用于具体题目的结果。"}, {"text": "春节吃饺子是我们的真理。", "explanation": "这里应该用〈习俗〉。习俗是社会长期形成的风俗，不是普遍的正确认识。"}, {"text": "这次考试的真理比上次大多了。", "explanation": "这里应该用〈难度〉。真理指大家都认可的正确道理，不能用来说考试的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真理", "is_correct": true, "explanation": "正确。问句“……是真理吗”询问的是大家认可的道理，符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“水往低处流”是自然规律，不是体重，问句说不通。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送给别人的东西，“水往低处流”不能是礼物。"}, {"text": "定义", "is_correct": false, "explanation": "语义：“水往低处流”是自然规律，不是定义，用“定义”来问说不通。"}], "explanations": {"真理": "正确。问句“……是真理吗”询问的是大家认可的道理，符合语境。", "体重": "语义：“水往低处流”是自然规律，不是体重，问句说不通。", "礼物": "语义：礼物是送给别人的东西，“水往低处流”不能是礼物。", "定义": "语义：“水往低处流”是自然规律，不是定义，用“定义”来问说不通。"}, "sentence_index": 6, "correct_answer": "真理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的真理是考进年级前十。", "explanation": "这里应该用〈目标〉。目标是想要达到的地方，真理指客观的正确认识。"}, {"text": "这个游戏的真理是不许耍赖。", "explanation": "这里应该用〈规则〉。规则是大家共同遵守的约定，真理不是游戏的约定。"}, {"text": "这顿饭的真理很好吃，大家都吃了两碗。", "explanation": "这里应该用〈味道〉。真理指大家都认可的正确道理，不能用来说饭菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这就是一只真理，大家都知道。", "corrected_sentence": "这就是一条真理，大家都知道。", "error_description": "量词错误：“真理”前面应该用量词“条”，“只”不能用来数真理。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经坚守过这只真理。", "corrected_sentence": "他们曾经坚守过这条真理。", "error_description": "量词错误：“真理”是抽象名词，应用量词“条”；“只”多用于动物或成对物品中的单只，不能用来数真理。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谬误", "is_correct": true, "explanation": "反义：谬误指错误的认识或道理，与“真理”正相对。"}, {"text": "习俗", "is_correct": false, "explanation": "无反义关系：习俗指社会上长期形成的风俗习惯，与“真理”不构成反义。"}, {"text": "传说", "is_correct": false, "explanation": "无反义关系：传说指口头流传的故事，与“真理”不是相对的概念。"}, {"text": "梦想", "is_correct": false, "explanation": "无反义关系：梦想指对未来的美好愿望，不与“真理”相对。"}], "correct_answer": "谬误", "explanations": {"谬误": "反义：谬误指错误的认识或道理，与“真理”正相对。", "习俗": "无反义关系：习俗指社会上长期形成的风俗习惯，与“真理”不构成反义。", "传说": "无反义关系：传说指口头流传的故事，与“真理”不是相对的概念。", "梦想": "无反义关系：梦想指对未来的美好愿望，不与“真理”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谬误", "is_correct": true, "explanation": "反义：谬误指错误的认识或道理，与“真理”正相对。"}, {"text": "童话", "is_correct": false, "explanation": "无反义关系：童话是虚构的故事，与“真理”不构成反义。"}, {"text": "习惯", "is_correct": false, "explanation": "无反义关系：习惯指长期形成的行为方式，与“真理”不是相对的概念。"}, {"text": "故事", "is_correct": false, "explanation": "无反义关系：故事指叙述人或事的作品，与“真理”不构成反义。"}], "correct_answer": "谬误", "explanations": {"谬误": "反义：谬误指错误的认识或道理，与“真理”正相对。", "童话": "无反义关系：童话是虚构的故事，与“真理”不构成反义。", "习惯": "无反义关系：习惯指长期形成的行为方式，与“真理”不是相对的概念。", "故事": "无反义关系：故事指叙述人或事的作品，与“真理”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "客观事物及其规律在人们意识中的正确反映。", "primary_collocate": null, "pronunciation": "zhēn lǐ", "ipa": "ʈʂən˥ li˨˩", "syllable_count": 2, "sentences": [{"text": "科学家一直在寻找自然界的真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实践是检验真理的唯一标准。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真理往往掌握在少数人手中。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一生都在追求真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥白尼的发现让人们看到了真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真理需要用事实来证明。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学研究的目的是发现真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了坚持真理，离开了学校。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史最终会证明谁掌握了真理。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真理不会因为人多就变成错的。", "target_word": "真理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝对真理", "label": "复合词"}, {"form": "相对真理", "label": "复合词"}], "register": "书面", "sense_fingerprint": "科学意义上对客观规律的正确认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048b119b-ad33-43f5-bdcb-1cf74fb1a422') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真理", "is_correct": true, "explanation": "正确。“真理”指自然界客观规律的正确认识，与“寻找”搭配，符合句意。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票是人造的货币，科学家不会在自然界里寻找钞票。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“寻找”可以说寻找答案、线索，但不说“寻找工资”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是人造的物品，自然界里不存在需要科学家去寻找的玩具。"}], "explanations": {"真理": "正确。“真理”指自然界客观规律的正确认识，与“寻找”搭配，符合句意。", "钞票": "语义：钞票是人造的货币，科学家不会在自然界里寻找钞票。", "工资": "搭配：“寻找”可以说寻找答案、线索，但不说“寻找工资”。", "玩具": "语义：玩具是人造的物品，自然界里不存在需要科学家去寻找的玩具。"}, "sentence_index": 0, "correct_answer": "真理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察终于查清了这起事故的真理。", "explanation": "这里应该用〈真相〉。真相指事情的实际经过，真理指普遍规律的正确认识，不用于具体事件。"}, {"text": "这台机器的真理很简单，我一看就懂。", "explanation": "这里应该用〈原理〉。原理指机器等事物的基本道理，说机器的工作道理要用原理，不用真理。"}, {"text": "这次考试的真理比上次大多了。", "explanation": "这里应该用〈难度〉。真理指普遍的正确认识，不能用来说考试的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真理", "is_correct": true, "explanation": "正确。句中“发现”的对象是客观规律，用“真理”合适。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“发现”的对象是客观规律，饺子是食物，科学研究不以发现饺子为目的。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，指闲话和传闻，与书面语体的科学论述不合。"}, {"text": "考场", "is_correct": false, "explanation": "语义：考场是考试的地方，科学研究的目的不是发现考场。"}], "explanations": {"真理": "正确。句中“发现”的对象是客观规律，用“真理”合适。", "饺子": "语义：“发现”的对象是客观规律，饺子是食物，科学研究不以发现饺子为目的。", "八卦": "语域：“八卦”是口语，指闲话和传闻，与书面语体的科学论述不合。", "考场": "语义：考场是考试的地方，科学研究的目的不是发现考场。"}, "sentence_index": 6, "correct_answer": "真理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次讲座的真理很长，讲了三个小时。", "explanation": "这里应该用〈内容〉。真理指客观规律的正确认识，不能用来说讲座的长短，应说内容。"}, {"text": "这台电脑的真理很好用，我们每次上网都用它。", "explanation": "这里应该用〈功能〉。真理是客观规律的正确认识，不能用来说电脑的作用，应说功能。"}, {"text": "这部电影的真理很感人，我看哭了。", "explanation": "这里应该用〈剧情〉。剧情是影视作品的情节，真理指客观规律的正确认识，不能用来说电影的情节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应当记住这只真理。", "corrected_sentence": "我们应当记住这条真理。", "error_description": "量词错误：“真理”前面应该用量词“条”，“只”多用于动物，不能用来数真理。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家发现了一只新的真理。", "corrected_sentence": "科学家发现了一条新的真理。", "error_description": "量词错误：“真理”应该用量词“条”，“只”多用于动物，不能用来数真理。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d235003-eefd-46c7-acdd-ddb9ae3cfbea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
