INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "硕士是在大学毕业后，又继续读书，得到的一种学位。", "primary_collocate": null, "pronunciation": "shuò shì", "ipa": "ʂwɔ˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "大学毕业后，他决定继续读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，读硕士要先考试。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想读硕士，所以每天学习到很晚。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李大学毕业就工作了，没有读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读硕士的时候住在学校里。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟明年考硕士，现在很忙。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读硕士的第一年，他学了很多新东西。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他硕士毕业后，进了一家大公司。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外读完了硕士，才回国工作。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸希望我大学以后再读硕士。", "target_word": "硕士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "硕士生", "label": "复合"}, {"form": "硕士学位", "label": "复合"}, {"form": "碩士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大学毕业后继续读书所得的学位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54747f1c-7f82-48a2-943c-930173304b61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硕士", "is_correct": true, "explanation": "硕士是大学毕业后继续深造所得的学位，与“大学毕业后继续读”相合。"}, {"text": "小学", "is_correct": false, "explanation": "语义：大学毕业后继续读的是更高的学位，“小学”是更低的学段，与语境矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“读”搭配的是书籍、课程等，不能说“读房子”。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”是食物，不能用“读”，“继续读早饭”不通。"}], "explanations": {"硕士": "硕士是大学毕业后继续深造所得的学位，与“大学毕业后继续读”相合。", "小学": "语义：大学毕业后继续读的是更高的学位，“小学”是更低的学段，与语境矛盾。", "房子": "搭配：“读”搭配的是书籍、课程等，不能说“读房子”。", "早饭": "搭配：“早饭”是食物，不能用“读”，“继续读早饭”不通。"}, "sentence_index": 0, "correct_answer": "硕士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把硕士放进了冰箱。", "explanation": "这里应该用〈牛奶〉。牛奶是实物，可以放进冰箱；硕士是学位，不能放进冰箱。"}, {"text": "我们中午一起去硕士吃饭吧。", "explanation": "这里应该用〈食堂〉。食堂是吃饭的地方；硕士是学位，不是场所。"}, {"text": "他去年参观了硕士。", "explanation": "这里应该用〈学校〉。“参观”的对象是场所，硕士是学位，不能被参观；参观的对象应是学校这类场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ab1556-aae7-4217-8022-86a0cbe971cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
